
// ═══════════ STATE ═══════════
let co = 'rl'; // 'rl' | 'nl'
let currentPage = 'dashboard';
let sidebarOpen = false;
let CRM_USER = 'tawanna'; // 'tawanna' | 'doren' | 'caroline'

const ACCENT = { rl: '#021D40', nl: '#3D0740' };

// ── Email brand config (from Blocks.diy action) ──────────────
const BRAND_CONFIGS = {
  rl: { brandColor:'#021D40', brandName:'RealtyLine',  websiteUrl:'https://realtyline.us' },
  nl: { brandColor:'#3D0740', brandName:'Newsline', websiteUrl:'https://newslinesa.com' }
};

function buildRenewalEmailHtml(params) {
  var brand=params.brand, advertiserName=params.advertiserName||'Advertiser';
  var companyName=params.companyName||'', formattedDate=params.formattedDate||'';
  var adRate=params.adRate||0, adSize=params.adSize, signingLink=params.signingLink;
  var frequency=params.frequency||'', daysRemaining=params.daysRemaining||0;
  var agreementDataUri=params.agreementDataUri||'';
  var rateStr=adRate.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  var brandColor=brand.brandColor;
  var brandName=brand.brandName;
  var websiteUrl=brand.websiteUrl;

  // Urgency label
  var urgencyLabel = daysRemaining<=0
    ? 'EXPIRED'
    : daysRemaining<=7 ? 'EXPIRES SOON'
    : 'RENEWAL NOTICE';
  var urgencyColor = daysRemaining<=0?'#DB1924':daysRemaining<=14?'#F59E0B':'#6B7A99';

  // Expiry sentence
  var expirySentence = daysRemaining<=0
    ? 'The contract <strong style="color:'+brandColor+'">'+companyName+'</strong> made between '+brandName+' and '+companyName+' <strong>expired on '+formattedDate+'</strong>.'
    : 'The contract <strong style="color:'+brandColor+'">'+companyName+'</strong> made between '+brandName+' and '+companyName+' <strong>expires on '+formattedDate+'</strong> — in <strong style="color:'+urgencyColor+'">'+daysRemaining+' day'+(daysRemaining!==1?'s':'')+'</strong>.';

  // CTA button
  var ctaButton = signingLink
    ? '<tr><td align="center" style="padding:28px 40px 8px 40px"><a href="'+signingLink+'" style="display:inline-block;background:'+brandColor+';color:#fff;font-family:Georgia,serif;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 40px;border-radius:4px;letter-spacing:.5px">Sign &amp; Renew Agreement</a></td></tr>'
    : '<tr><td align="center" style="padding:28px 40px 8px 40px"><a href="'+websiteUrl+'" style="display:inline-block;background:'+brandColor+';color:#fff;font-family:Georgia,serif;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 40px;border-radius:4px;letter-spacing:.5px">View Agreement</a></td></tr>';

  // Agreement details rows
  var detailRows = ''
    + '<tr><td style="font-family:Arial,sans-serif;font-size:14px;color:#444;padding:5px 0;border-bottom:1px solid #f0f0f0"><span style="color:#888;display:inline-block;width:130px">Advertiser</span><strong>'+companyName+'</strong></td></tr>'
    + '<tr><td style="font-family:Arial,sans-serif;font-size:14px;color:#444;padding:5px 0;border-bottom:1px solid #f0f0f0"><span style="color:#888;display:inline-block;width:130px">Expiration Date</span><strong style="color:'+urgencyColor+'">'+formattedDate+'</strong></td></tr>'
    + (adSize?'<tr><td style="font-family:Arial,sans-serif;font-size:14px;color:#444;padding:5px 0;border-bottom:1px solid #f0f0f0"><span style="color:#888;display:inline-block;width:130px">Ad Size</span>'+adSize+'</td></tr>':'')
    + (frequency?'<tr><td style="font-family:Arial,sans-serif;font-size:14px;color:#444;padding:5px 0;border-bottom:1px solid #f0f0f0"><span style="color:#888;display:inline-block;width:130px">Frequency</span>'+frequency+'</td></tr>':'')
    + '<tr><td style="font-family:Arial,sans-serif;font-size:14px;color:#444;padding:5px 0"><span style="color:#888;display:inline-block;width:130px">Current Rate</span><strong>$'+rateStr+'/issue</strong></td></tr>';

  // Attachment block
  var attachBlock = agreementDataUri
    ? '<tr><td style="padding:0 40px 24px 40px"><table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f0f9f4;border:2px solid #10b981;border-radius:6px"><tr><td style="padding:16px 20px"><p style="margin:0 0 8px 0;font-family:Arial,sans-serif;font-size:12px;font-weight:800;color:#065f46;text-transform:uppercase;letter-spacing:.8px">&#128196; Renewal Agreement Attached</p><p style="margin:0;font-family:Arial,sans-serif;font-size:13px;color:#059669;line-height:1.6">Your pre-filled renewal agreement is attached and ready to sign. Rate locked at <strong>$'+rateStr+'/issue</strong>.</p></td></tr></table></td></tr>'
    : '';

  return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><title>Advertising Agreement Renewal — '+brandName+'</title></head>'
    +'<body style="margin:0;padding:0;background:#f2f4f7;font-family:Arial,sans-serif">'
    +'<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#f2f4f7;padding:40px 0"><tr><td align="center">'
    +'<table role="presentation" cellpadding="0" cellspacing="0" width="600" style="max-width:600px;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.10)">'

    // Header bar with brand color
    +'<tr><td style="background:'+brandColor+';padding:0"><table role="presentation" cellpadding="0" cellspacing="0" width="100%"><tr>'
    +'<td style="padding:22px 32px"><span style="font-family:Georgia,serif;font-size:22px;font-weight:bold;color:#fff;letter-spacing:-.5px">'+brandName+'</span></td>'
    +'<td align="right" style="padding:22px 32px"><span style="font-family:Arial,sans-serif;font-size:11px;color:rgba(255,255,255,.75);text-transform:uppercase;letter-spacing:1.5px">Advertising Renewal</span></td>'
    +'</tr></table></td></tr>'

    // Urgency strip
    +'<tr><td style="background:'+urgencyColor+';padding:8px 32px;text-align:center"><span style="font-family:Arial,sans-serif;font-size:12px;font-weight:800;color:#fff;letter-spacing:1.5px;text-transform:uppercase">'+urgencyLabel+'</span></td></tr>'

    // Clock icon + body
    +'<tr><td style="padding:36px 40px 0 40px;text-align:center">'
    +'<div style="width:56px;height:56px;border-radius:50%;background:'+urgencyColor+'22;border:3px solid '+urgencyColor+';display:inline-flex;align-items:center;justify-content:center;margin-bottom:20px">'
    +'<span style="font-size:26px">&#128336;</span></div>'
    +'<p style="margin:0 0 6px 0;font-family:Arial,sans-serif;font-size:16px;color:#222">Hi <strong>'+advertiserName+'</strong>,</p>'
    +'</td></tr>'

    +'<tr><td style="padding:12px 40px 24px 40px;text-align:center">'
    +'<p style="margin:0;font-family:Arial,sans-serif;font-size:15px;color:#444;line-height:1.8">'+expirySentence+'</p>'
    +'</td></tr>'

    // CTA button
    +ctaButton

    // Agreement details card
    +'<tr><td style="padding:16px 40px 28px 40px">'
    +'<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#fafafa;border:1px solid #e8e8e8;border-radius:6px;border-left:4px solid '+brandColor+'">'
    +'<tr><td style="padding:18px 24px">'
    +'<p style="margin:0 0 12px 0;font-family:Arial,sans-serif;font-size:11px;color:#999;text-transform:uppercase;letter-spacing:1px">Agreement Details</p>'
    +'<table role="presentation" cellpadding="0" cellspacing="0" width="100%">'+detailRows+'</table>'
    +'</td></tr></table>'
    +'</td></tr>'

    +attachBlock

    // Rate lock notice
    +'<tr><td style="padding:0 40px 28px 40px">'
    +'<table role="presentation" cellpadding="0" cellspacing="0" width="100%" style="background:#fffbf0;border:1px solid #ffe58f;border-radius:6px">'
    +'<tr><td style="padding:14px 20px"><p style="margin:0;font-family:Arial,sans-serif;font-size:13px;color:#7a5c00;line-height:1.6">&#9200; <strong>Rate Lock:</strong> Renew before <strong>'+formattedDate+'</strong> to lock in your current rate of <strong>$'+rateStr+'/issue</strong>. After expiration, rates are subject to change.</p></td></tr>'
    +'</table></td></tr>'

    // Closing
    +'<tr><td style="padding:0 40px 32px 40px">'
    +'<p style="margin:0;font-family:Arial,sans-serif;font-size:14px;color:#555;line-height:1.8">If you have any questions, please reach out to your account manager. We value your continued partnership.</p>'
    +'<p style="margin:20px 0 0 0;font-family:Arial,sans-serif;font-size:14px;color:#444">Warm regards,<br><strong>The '+brandName+' Advertising Team</strong></p>'
    +'</td></tr>'

    // Footer
    +'<tr><td style="background:#f8f9fb;border-top:1px solid #e8e8e8;padding:20px 40px;text-align:center">'
    +'<p style="margin:0 0 4px 0;font-family:Arial,sans-serif;font-size:12px;color:#999"><strong style="color:'+brandColor+'">'+brandName+'</strong> &nbsp;|&nbsp; <a href="'+websiteUrl+'" style="color:#999;text-decoration:none">'+websiteUrl+'</a></p>'
    +'<p style="margin:4px 0 0 0;font-family:Arial,sans-serif;font-size:11px;color:#bbb">This is an automated renewal reminder from '+brandName+'. Please do not reply directly to this email.</p>'
    +'</td></tr>'

    +'</table></td></tr></table>'
    +'</body></html>';
}

