// ── openEmailComposer — full rich email composer ────────────────
function openEmailComposer(toEmail, toName, subjectDefault, accentColor) {
  var accent = accentColor || ACCENT[co];
  var accentHex = (co==='nl'?'#3D0740':'#021D40');
  var pub = co==='rl' ? 'RealtyLine' : 'Newsline';
  var senders = EMAIL_SENDERS[co] || EMAIL_SENDERS.rl;
  var defaultSenderIdx = 0;
  senders.forEach(function(s, i) {
    if (s.name.toLowerCase().indexOf(CRM_USER) === 0) defaultSenderIdx = i;
  });
  var senderOpts = senders.map(function(s, i) {
    return '<option value="' + i + '"' + (i===defaultSenderIdx?' selected':'') + '>' + esc(s.name) + ' &lt;' + esc(s.email) + '&gt;</option>';
  }).join('');

  var bodyHtml = '<div style="display:flex;flex-direction:column;gap:12px">'

    // To
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">To</label>'
    + '<input id="ec_to" value="' + esc(toEmail) + '" placeholder="recipient@email.com" style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit;outline:none">'
    + '</div>'

    // From
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">From</label>'
    + '<select id="ec_from" style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit;outline:none">' + senderOpts + '</select>'
    + '</div>'

    // Subject
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">Subject</label>'
    + '<input id="ec_subj" value="' + esc(subjectDefault||'') + '" placeholder="Subject line..." style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit;outline:none">'
    + '</div>'

    // Rich text toolbar
    + '<div>'
    + '<div style="display:flex;gap:4px;padding:6px 8px;background:var(--muted);border:1px solid var(--border);border-bottom:none;border-radius:var(--r) var(--r) 0 0;flex-wrap:wrap">'
    + '<button type="button" onclick="document.execCommand(\'bold\')" title="Bold" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-weight:700;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">B</button>'
    + '<button type="button" onclick="document.execCommand(\'italic\')" title="Italic" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-style:italic;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">I</button>'
    + '<button type="button" onclick="document.execCommand(\'underline\')" title="Underline" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;text-decoration:underline;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">U</button>'
    + '<div style="width:1px;background:var(--border);margin:2px 4px"></div>'
    + '<button type="button" onclick="document.execCommand(\'insertUnorderedList\')" title="Bullet list" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">&#8226; List</button>'
    + '<button type="button" onclick="document.execCommand(\'insertOrderedList\')" title="Numbered list" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">1. List</button>'
    + '<div style="width:1px;background:var(--border);margin:2px 4px"></div>'
    + '<button type="button" onclick="ecInsertLink()" title="Insert link" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">&#128279; Link</button>'
    + '<div style="width:1px;background:var(--border);margin:2px 4px"></div>'
    + '<button type="button" onclick="document.execCommand(\'justifyLeft\')" title="Align left" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">&#8676;</button>'
    + '<button type="button" onclick="document.execCommand(\'justifyCenter\')" title="Align center" style="padding:4px 8px;border:none;background:transparent;color:var(--text);cursor:pointer;border-radius:4px;font-size:13px" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">&#8801;</button>'
    + '</div>'

    // Editable body
    + '<div id="ec_body" contenteditable="true" style="min-height:220px;padding:14px;background:#fff;color:#222;border:1px solid var(--border);border-top:none;border-radius:0 0 var(--r) var(--r);font-family:Arial,sans-serif;font-size:14px;line-height:1.7;outline:none">'
    + '</div>'
    + '</div>'

    // Attachments
    + '<div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">'
    + '<label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">Attachments</label>'
    + '<button type="button" onclick="document.getElementById(\'ec_file\').click()" style="padding:4px 10px;border:1px solid var(--border2);background:var(--muted2);color:var(--text);border-radius:var(--r);font-size:12px;cursor:pointer">+ Add File</button>'
    + '</div>'
    + '<input type="file" id="ec_file" multiple style="display:none" onchange="ecAddFiles(this.files)">'
    + '<div id="ec_attachments" style="display:flex;flex-wrap:wrap;gap:6px;min-height:28px"></div>'
    + '</div>'

    + '</div>';

  var footHtml = '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-sm" style="background:' + accent + ';color:#fff;font-weight:600;gap:5px;margin-left:auto" onclick="ecSend(\'' + accentHex + '\',\'' + esc(pub) + '\',\'' + esc(toName) + '\')">' + icon('mail') + ' Send</button>';

  openModal('<div class="modal-title">' + icon('mail') + ' New Email</div>', bodyHtml, footHtml, true);

  // Store attachments list
  window._ecFiles = [];
}

// Keep openEmailPreview as alias for other callers (agreements, renewals etc)
function openEmailPreview(toEmail, toName, subject, htmlBody, accentColor) {
  var accent  = accentColor || ACCENT[co];
  var pub     = co === 'rl' ? 'RealtyLine' : 'Newsline';
  var senders = EMAIL_SENDERS[co] || EMAIL_SENDERS.rl;
  var defaultSenderIdx = 0;
  senders.forEach(function(s, i) {
    if (s.name.toLowerCase().indexOf(CRM_USER) === 0) defaultSenderIdx = i;
  });
  var senderOpts = senders.map(function(s, i) {
    return '<option value="' + i + '"' + (i === defaultSenderIdx ? ' selected' : '') + '>' + esc(s.name) + ' &lt;' + esc(s.email) + '&gt;</option>';
  }).join('');

  // Store html for sending
  window._epHtmlBody = htmlBody;
  window._epToEmail  = toEmail;
  window._epToName   = toName;
  window._epAccent   = accent;
  window._epPub      = pub;

  var body = '<div style="display:flex;flex-direction:column;gap:10px">'
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">To</label>'
    + '<input id="ep_to" value="' + esc(toEmail) + '" style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit"></div>'
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">From</label>'
    + '<select id="ep_from" style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit">' + senderOpts + '</select></div>'
    + '<div class="fg full"><label style="font-size:12px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em">Subject</label>'
    + '<input id="ep_subj" value="' + esc(subject) + '" style="width:100%;padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit"></div>'
    + '<div><div style="font-size:11.5px;font-weight:600;color:var(--text2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px">Preview</div>'
    + '<iframe id="ep_iframe" style="width:100%;height:480px;border:1px solid var(--border);border-radius:var(--r);background:#fff" frameborder="0"></iframe>'
    + '</div></div>';

  var foot = '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-sm" style="background:' + accent + ';color:#fff;font-weight:600;gap:5px" onclick="epSend()">' + icon('mail') + ' Send</button>';

  openModal('<div class="modal-title">' + icon('mail') + ' Email Agreement</div>', body, foot, true);

  // Write HTML into iframe after modal renders
  setTimeout(function() {
    var iframe = document.getElementById('ep_iframe');
    if (iframe && htmlBody) {
      var doc = iframe.contentDocument || iframe.contentWindow.document;
      doc.open(); doc.write(htmlBody); doc.close();
    }
  }, 80);
}

function epSend() {
  var to      = (document.getElementById('ep_to')   || {}).value || window._epToEmail || '';
  var subj    = (document.getElementById('ep_subj') || {}).value || '';
  var fromIdx = parseInt((document.getElementById('ep_from') || {}).value || '0');
  var senders = EMAIL_SENDERS[co] || EMAIL_SENDERS.rl;
  var sender  = senders[fromIdx] || senders[0];
  if (!to)   { toast('Recipient email required', 'err'); return; }
  if (!subj) { toast('Subject required', 'err'); return; }

  var btn = document.querySelector('#modalFoot .btn-sm');
  if (btn) { btn.disabled = true; btn.textContent = 'Sending...'; }

  fetch('https://email.myrealtyline.com/send-email', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      to:      to,
      subject: subj,
      html:    window._epHtmlBody || '',
      from:    sender.name + ' <' + sender.email + '>'
    })
  })
  .then(function(r) { return r.json(); })
  .then(function(d) {
    if (d.success) {
      toast('Email sent to ' + to, 'ok');
      closeModal();
    } else {
      toast('Send failed: ' + sanitizeApiError(d.error || 'unknown'), 'err');
      if (btn) { btn.disabled = false; btn.innerHTML = icon('mail') + ' Send'; }
    }
  })
  .catch(function(e) {
    toast('Error: ' + sanitizeApiError(e.message), 'err');
    if (btn) { btn.disabled = false; btn.innerHTML = icon('mail') + ' Send'; }
  });
}

function ecInsertLink() {
  var url = prompt('Enter URL:');
  if (!url) return;
  if (url.indexOf('http') !== 0) url = 'https://' + url;
  document.execCommand('createLink', false, url);
}

function ecAddFiles(files) {
  if (!window._ecFiles) window._ecFiles = [];
  var container = document.getElementById('ec_attachments');
  if (!container) return;
  for (var i = 0; i < files.length; i++) {
    (function(f) {
      window._ecFiles.push(f);
      var idx = window._ecFiles.length - 1;
      var chip = document.createElement('div');
      chip.style.cssText = 'display:inline-flex;align-items:center;gap:6px;padding:3px 10px;background:var(--muted2);border:1px solid var(--border2);border-radius:var(--rfull);font-size:12px;color:var(--text)';
      chip.innerHTML = esc(f.name) + ' <button onclick="ecRemoveFile(' + idx + ',this.parentNode)" style="border:none;background:none;color:var(--text3);cursor:pointer;font-size:14px;line-height:1;padding:0">&times;</button>';
      container.appendChild(chip);
    })(files[i]);
  }
  document.getElementById('ec_file').value = '';
}

function ecRemoveFile(idx, chip) {
  if (window._ecFiles) window._ecFiles[idx] = null;
  if (chip) chip.parentNode.removeChild(chip);
}

function ecGetSender() {
  var sel = document.getElementById('ec_from');
  var idx = sel ? parseInt(sel.value) : 0;
  var senders = EMAIL_SENDERS[co] || EMAIL_SENDERS.rl;
  return senders[idx] || senders[0];
}

function ecSend(accentHex, pub, toName) {
  var to = (document.getElementById('ec_to')||{}).value || '';
  var subj = (document.getElementById('ec_subj')||{}).value || '';
  if (!to) { toast('Recipient email is required','err'); return; }
  if (!subj) { toast('Subject is required','err'); return; }
  // Build plain text for mailto fallback
  var body = document.getElementById('ec_body');
  var plainText = body ? body.innerText : '';
  var sender = ecGetSender();
  var href = 'mailto:' + encodeURIComponent(to)
    + '?from=' + encodeURIComponent(sender.email)
    + '&subject=' + encodeURIComponent(subj)
    + '&body=' + encodeURIComponent(plainText);
  window.open(href, '_blank');
  closeModal();
  toast('Opening in Mail app...','ok');
}

