// ── API config ────────────────────────────────────────────────
const API_BASE = window.location.hostname === 'localhost'
  ? 'http://localhost:3001'
  : 'https://proxy.myrealtyline.com';  // caxton-proxy via Cloudflare tunnel
const CRM_SECRET = 'eaf67915a0294ea7789c5e776e46107b193c649835eeffe369a1057458786954';
function crmFetch(url, opts) {
  opts = opts || {};
  opts.headers = Object.assign({}, opts.headers || {}, { 'x-crm-secret': CRM_SECRET });
  return fetch(url, opts);
}

// ── Fetch with timeout (ms) — rejects with Error('timeout') if exceeded ──
function fetchWithTimeout(url, opts, ms) {
  ms = ms || 30000;
  var controller = new AbortController();
  var timer = setTimeout(function() { controller.abort(); }, ms);
  opts = Object.assign({}, opts, { signal: controller.signal });
  return fetch(url, opts).then(function(r) { clearTimeout(timer); return r; }).catch(function(err) {
    clearTimeout(timer);
    if (err && err.name === 'AbortError') throw new Error('timeout');
    throw err;
  });
}

// ── Sanitize raw API/proxy error messages before showing to users ──────────
// Converts cryptic upstream errors (Anthropic tool limits, server stack traces,
// model overload messages, etc.) into clean user-facing strings.
function sanitizeApiError(msg) {
  if (!msg) return 'An unexpected error occurred. Please try again.';
  var s = String(msg);
  // Anthropic tool-use / model errors
  if (/tool.use limit/i.test(s))         return 'AI service is busy — please try again in a moment.';
  if (/overloaded/i.test(s))             return 'AI service is temporarily overloaded — please try again shortly.';
  if (/timed? ?out|AbortError/i.test(s)) return 'Request timed out — please try again.';
  if (/rate.?limit/i.test(s))            return 'Too many requests — please wait a moment and try again.';
  if (/context.?length|too many tokens/i.test(s)) return 'Request too large — please try a shorter query.';
  if (/invalid.?api.?key|auth/i.test(s)) return 'Service configuration error — please contact support.';
  if (/network|failed to fetch|load failed/i.test(s)) return 'Network error — check your connection and try again.';
  if (/500|internal server/i.test(s))    return 'Server error — please try again in a moment.';
  // Stack traces / verbose internal errors — strip them
  if (s.length > 200 || /\n.*at /.test(s)) return 'An unexpected error occurred. Please try again.';
  return s;
}


