// ── Google Places Address Autocomplete ───────────────────────
// Based on official sample: places-autocomplete-addressform
// Uses google.maps.places.Autocomplete bound directly to each input.
// Script tag: callback=initMapsPlaces&libraries=places&v=weekly

// Called by Maps API when ready
function initMapsPlaces() {
  window._mapsPlacesReady = true;
  // Prevent modal-body from swallowing pac-container clicks
  // pac-container is appended to <body> by Google after first keystroke
  document.addEventListener('mousedown', function(e) {
    var pac = document.querySelector('.pac-container');
    if (pac && pac.contains(e.target)) {
      e.stopImmediatePropagation();
    }
  }, true); // capture phase — fires before modal handlers
  attachPlacesACAll();
}

// fillMap: { city: 'fieldId', state: 'fieldId', zip: 'fieldId' }
function initPlacesAC(streetInputId, fillMap) {
  var inp = document.getElementById(streetInputId);
  if (!inp || inp._pacDone) return;

  function attach() {
    var el = document.getElementById(streetInputId);
    if (!el || el._pacDone) return;
    el._pacDone = true;

    var ac = new google.maps.places.Autocomplete(el, {
      componentRestrictions: { country: ['us'] },
      fields: ['address_components', 'formatted_address'],
      types: ['address'],
      strictBounds: false,
    });

    // Prevent Enter key from submitting any parent form
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter') e.preventDefault();
    });

    // When user selects an address, populate form fields
    ac.addListener('place_changed', function() {
      var place = ac.getPlace();
      var postcode = '';

      if (!place.address_components) return;

      for (var i = 0; i < place.address_components.length; i++) {
        var component = place.address_components[i];
        var componentType = component.types[0];
        switch (componentType) {
          case 'postal_code':
            postcode = component.long_name + postcode;
            break;
          case 'postal_code_suffix':
            postcode = postcode + '-' + component.long_name;
            break;
        }
      }

      // Fill street with full formatted address
      var streetEl = document.getElementById(streetInputId);
      if (streetEl) {
        streetEl.value = place.formatted_address || '';
        streetEl.dispatchEvent(new Event('input',  {bubbles:true}));
        streetEl.dispatchEvent(new Event('change', {bubbles:true}));
        streetEl.blur();
      }

      // Fill zip only
      if (fillMap && fillMap.zip) {
        var zipEl = document.getElementById(fillMap.zip);
        if (zipEl) { zipEl.value = postcode; zipEl.dispatchEvent(new Event('input', {bubbles:true})); }
      }

      // Remove dropdown
      document.querySelectorAll('.pac-container').forEach(function(p) { p.remove(); });
    });
  }

  if (window._mapsPlacesReady) {
    attach();
  } else {
    var t = setInterval(function() {
      if (window._mapsPlacesReady) { clearInterval(t); attach(); }
    }, 200);
  }
}

function attachPlacesACAll() {
  setTimeout(function() {
    // Static IDs
    initPlacesAC('ev_address', { city:'ev_city',      state:'ev_state',      zip:'ev_zip' });
    initPlacesAC('ev_loc',     {});
    initPlacesAC('cf_addr',    { city:'cf_city',      state:'cf_state',      zip:'cf_zip' });
    initPlacesAC('agf_addr',   { city:'agf_city',     state:'agf_state',     zip:'agf_zip' });
    initPlacesAC('agf_cardaddr',{ city:'agf_cardcity',state:'agf_cardstate', zip:'agf_cardzip' });
    initPlacesAC('mlcf_addr',  { city:'mlcf_city',    state:'mlcf_state',    zip:'mlcf_zip' });
    initPlacesAC('agm_addr',   { city:'agm_city',     state:'agm_state',     zip:'agm_zip' });
    initPlacesAC('af_loc',     { city:'af_city',      state:'af_state',      zip:'af_zip' });
    initPlacesAC('pcl_addr',   { city:'pcl_city',     state:'pcl_state',     zip:'pcl_zip' });
    initPlacesAC('pcb_addr',   { city:'pcb_city',     state:'pcb_state',     zip:'pcb_zip' });
    initPlacesAC('sc_addr',    { city:'sc_city',      state:'sc_state',      zip:'sc_zip' });
    initPlacesAC('rnf_addr',   { city:'rnf_city',     state:'rnf_state',     zip:'rnf_zip' });
    initPlacesAC('rnf_cardaddr',{ city:'rnf_cardcity',state:'rnf_cardstate', zip:'rnf_cardzip' });
    initPlacesAC('evloc_new_addr',{ city:'evloc_new_city',state:'evloc_new_state',zip:'evloc_new_zip' });
    // Dynamic IDs
    document.querySelectorAll('input[id^="evloc_addr_"]').forEach(function(el) {
      var i = el.id.replace('evloc_addr_','');
      initPlacesAC(el.id, { city:'evloc_city_'+i, state:'evloc_state_'+i, zip:'evloc_zip_'+i });
    });
    document.querySelectorAll('input[id^="pbl_addr_"]').forEach(function(el) {
      var c = el.id.replace('pbl_addr_','');
      initPlacesAC(el.id, { city:'pbl_city_'+c, state:'pbl_state_'+c, zip:'pbl_zip_'+c });
    });
    document.querySelectorAll('input[id^="pbb_addr_"]').forEach(function(el) {
      var c = el.id.replace('pbb_addr_','');
      initPlacesAC(el.id, { city:'pbb_city_'+c, state:'pbb_state_'+c, zip:'pbb_zip_'+c });
    });
  }, 300);
}




// ── Auto-backup (throttled, called after every persist) ────────
var _backupThrottle = {};
function autoBackup(co2, type, arr) {
  if (!arr) return;
  if (!Array.isArray(arr) && typeof arr !== 'object') return;
  var key = co2 + '_' + type;
  var now = Date.now();
  if (_backupThrottle[key] && now - _backupThrottle[key] < 60000) return;
  _backupThrottle[key] = now;
  crmFetch(API_BASE + '/api/crm/' + co2 + '/backup', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ data_type: type, payload: Array.isArray(arr) ? arr : [arr], label: 'Auto-save' })
  }).catch(function() {});
}

// ── Save to DB (async, fire-and-forget with localStorage fallback) ──
function persistAll() {
  // Push all local data up to DB
  var types = ['clients','mailing','holding','appointments','agreements','forms','recurringEmails','prospects','bookingPages'];
  var PROTECTED = ['mailing','holding'];
  ['rl','nl'].forEach(function(c) {
    types.forEach(function(type) {
      var arr = DATA[c][type];
      if (arr && Array.isArray(arr)) {
        if (PROTECTED.indexOf(type) !== -1 && arr.length === 0) {
          console.warn('[persistAll] Skipping empty '+c+'/'+type+' — safety lock active');
          return;
        }
        crmFetch(API_BASE + '/api/crm/' + c + '/' + type, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(arr)
        }).catch(function(){});
      }
    });
  });
}

function persist() {
  try {
    localStorage.setItem('crm_data',   JSON.stringify(DATA));
    localStorage.setItem('crm_events', JSON.stringify(eventsData));
  } catch(e) {}
  // Push only the CURRENT company to DB — writing both companies risks
  // overwriting the inactive company with stale in-memory data
  var PROTECTED = ['mailing','holding'];
  var arr, type;
  ['clients','mailing','holding','appointments','agreements','forms','recurringEmails','renewalReminders','prospects','bookingPages'].forEach(function(t) {
    type = t;
    arr = DATA[co][type]||[];
    if (PROTECTED.indexOf(type) !== -1 && arr.length === 0) {
      console.warn('[persist] Skipping empty '+co+'/'+type+' — safety lock active');
      return;
    }
    crmFetch(API_BASE+'/api/crm/'+co+'/'+type, {
      method:'PUT', headers:{'Content-Type':'application/json'},
      body:JSON.stringify(arr)
    }).catch(function(){});
    autoBackup(co, type, arr);
  });
  crmFetch(API_BASE+'/api/crm/'+co+'/events', {
    method:'PUT', headers:{'Content-Type':'application/json'},
    body:JSON.stringify(eventsData[co]||[])
  }).catch(function(){});
}

async function loadFromDb() {
  try {
    for (const c2 of ['rl','nl']) {
      const res = await crmFetch(API_BASE+'/api/crm/'+c2);
      if (!res.ok) throw new Error('DB fetch failed');
      const remote = await res.json();
      ['clients','mailing','holding','appointments','agreements','forms','recurringEmails','prospects','bookingPages'].forEach(function(type) {
        if (remote[type] === undefined) return;
        const raw = remote[type];
        const dbArr    = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.data) ? raw.data : []);
        const localArr = DATA[c2][type] || [];
        // Always use DB data — it is the source of truth
        DATA[c2][type] = dbArr;
      });
      if (remote.tracking !== undefined) {
        const raw = remote.tracking;
        DATA[c2].tracking = (raw && raw.sends) ? raw
          : Array.isArray(raw) ? {sends:raw,reminders:[]}
          : {sends:[],reminders:[]};
      }
      if (remote.events !== undefined) {
        const raw = remote.events;
        const dbEvts    = Array.isArray(raw) ? raw : (raw && Array.isArray(raw.data) ? raw.data : []);
        const localEvts = eventsData[c2] || [];
        eventsData[c2] = dbEvts;
      }
    }
    console.log('[CRM] Loaded from database ✓');
    purgeExpiredEvents();
    return true;
  } catch(e) {
    console.warn('[CRM] DB unavailable, using localStorage:', e.message);
    return false;
  }
}

function ensureArrays() {
  ['rl','nl'].forEach(function(c) {
    ['clients','mailing','holding','appointments','agreements','forms','recurringEmails','prospects','bookingPages'].forEach(function(k) {
      if (DATA[c][k] && !Array.isArray(DATA[c][k])) DATA[c][k] = Object.values(DATA[c][k]);
      if (!DATA[c][k]) DATA[c][k] = [];
    });
    if (DATA[c].tracking && !Array.isArray(DATA[c].tracking.sends)) DATA[c].tracking = {sends:[],reminders:[]};
  });
  if (!Array.isArray(eventsData.rl)) eventsData.rl = Object.values(eventsData.rl||{});
  if (!Array.isArray(eventsData.nl)) eventsData.nl = Object.values(eventsData.nl||{});
}

function loadPersistedData() {
  // Load from localStorage immediately (so app renders fast)
  try {
    const d = localStorage.getItem('crm_data');
    if (d) {
      const p = JSON.parse(d);
      ['rl','nl'].forEach(function(c) {
        if (p[c]) {
          ['clients','mailing','holding','appointments','agreements','forms','recurringEmails','prospects','bookingPages'].forEach(function(k) {
            if (p[c][k] !== undefined) DATA[c][k] = p[c][k];
          });
          if (p[c].tracking) DATA[c].tracking = p[c].tracking;
        }
      });
    }
    const e = localStorage.getItem('crm_events');
    if (e) {
      const pe = JSON.parse(e);
      ['rl','nl'].forEach(function(c) { if (Array.isArray(pe[c])) eventsData[c] = pe[c]; });
    }
  } catch(e) { console.warn('loadPersistedData failed:', e.message); }
}

