// ═══════════ UTILS ═══════════
function fmt$(v) {
  if (v === undefined || v === null || v === '') return '';
  var n = parseFloat(v);
  if (isNaN(n)) return '';
  return new Intl.NumberFormat('en-US', {style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
}

function fmtDate(s) { if(!s) return '—'; try{ const d=new Date(s); return d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}); }catch{return s;} }
function fmtDT(s) { if(!s) return '—'; try{ const d=new Date(s); return d.toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}); }catch{return s;} }
function fmt12(t) { if(!t) return ''; try{ var p=t.toString().split(':'); var h=parseInt(p[0],10); var m=p[1]||'00'; var ampm=h>=12?'PM':'AM'; h=h%12||12; return h+':'+m+' '+ampm; }catch(e){return t;} }
function getDaysUntil(s) { if(!s) return null; const t=new Date(); t.setHours(0,0,0,0); const e=new Date(s.slice(0,10)); e.setHours(0,0,0,0); return Math.round((e-t)/(86400000)); }
function fmtPhone(s) { if(!s) return ''; const d=s.replace(/\D/g,'').slice(0,10); if(!d) return ''; if(d.length<=3) return d; if(d.length<=6) return d.slice(0,3)+'-'+d.slice(3); return d.slice(0,3)+'-'+d.slice(3,6)+'-'+d.slice(6); }

// Live phone formatting — called oninput on every phone field
function fmtPhoneInput(el) {
  var pos  = el.selectionStart;
  var prev = el.value;
  var fmt  = fmtPhone(el.value);
  el.value = fmt;
  // Restore cursor: if user typed in the middle, keep position; if at end, stay at end
  var diff = fmt.length - prev.length;
  try { el.setSelectionRange(Math.max(0, pos + diff), Math.max(0, pos + diff)); } catch(e) {}
}

// Event delegation — catches phone fields in modals/sheets rendered after page load
document.addEventListener('input', function(e) {
  var el = e.target;
  if (el.tagName !== 'INPUT') return;
  if (el.classList.contains('phone-fmt') || el.dataset.phoneFmt) {
    fmtPhoneInput(el);
  }
});
function esc(s) { if(!s) return ''; return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

function daysBadge(d) {
  if(d==null) return '—';
  if(d<0) return `<span class="badge badge-overdue">${Math.abs(d)}d overdue</span>`;
  if(d<=14) return `<span class="badge badge-expiring">${d}d left</span>`;
  return `<span class="badge badge-ok">${d}d left</span>`;
}

// ═══════════ SIDEBAR INIT ═══════════
function buildNav() {
  const nav = document.getElementById('sidenav');

  function allDescendantIds(node) {
    var ids = [];
    if (node.children) node.children.forEach(function(c) {
      ids.push(c.id);
      ids = ids.concat(allDescendantIds(c));
    });
    return ids;
  }

  nav.innerHTML = NAV.map(function(n) {
    if (!n.children) {
      var active = currentPage === n.id;
      return '<a class="nav-item'+(active?' active':'')+'" onclick="goTo(\''+n.id+'\',this)" data-page="'+n.id+'">'+icon(n.icon)+' '+n.label+'</a>';
    }
    // Parent group — open if currentPage is this node or any descendant
    var groupIds = [n.id].concat(allDescendantIds(n));
    var groupOpen = groupIds.indexOf(currentPage) !== -1;
    var parentActive = currentPage === n.id;

    var childHtml = n.children.map(function(c) {
      var cActive = currentPage === c.id;
      var grandHtml = '';
      if (c.children) {
        grandHtml = '<div style="display:'+(groupOpen?'block':'none')+'">'
          + c.children.map(function(g){
              var gActive = currentPage===g.id;
              return '<a class="nav-item nav-sub-item'+(gActive?' active':'')+'" onclick="event.stopPropagation();goTo(\''+g.id+'\',this)" data-page="'+g.id+'" style="padding-left:48px;font-size:12px">'
                +icon(g.icon)+' '+g.label+'</a>';
            }).join('')
          + '</div>';
      }
      return '<a class="nav-item nav-sub-item'+(cActive?' active':'')+'" onclick="event.stopPropagation();goTo(\''+c.id+'\',this)" data-page="'+c.id+'" style="padding-left:32px;font-size:12.5px">'
        +icon(c.icon)+' '+c.label+'</a>'
        + grandHtml;
    }).join('');

    return '<a class="nav-item'+(parentActive?' active':'')+'" onclick="goTo(\''+n.id+'\',this)" data-page="'+n.id+'">'
      +icon(n.icon)+' '+n.label+'</a>'
      +'<div class="nav-sub-group" style="display:'+(groupOpen?'block':'none')+'">'+childHtml+'</div>';
  }).join('');

  // ── Populate mobile More menu with all non-bottom-nav pages ──
  var bottomNavPages = ['dashboard','clients','agreements','mailing'];
  var accent = ACCENT[co];
  var more = document.getElementById('moreMenu');
  if (more) {
    more.innerHTML = NAV.filter(function(n){ return bottomNavPages.indexOf(n.id) === -1; })
      .map(function(n){
        var active = currentPage === n.id;
        return '<a onclick="goTo(\''+n.id+'\');closeMoreMenu()" style="display:flex;align-items:center;gap:12px;padding:12px 20px;font-size:14px;color:'+(active?accent:'var(--text)')+';font-weight:'+(active?'600':'400')+';cursor:pointer;text-decoration:none;border-bottom:1px solid var(--border)" onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">'
          + icon(n.icon) + ' ' + n.label + '</a>';
      }).join('');
  }
}

function goTo(page, el) {
  if (page === 'booking')    { currentPage = 'booking'; }
  currentPage = page;
  localStorage.setItem('crm_page', page);
  if (page === 'portal') portalClientId = null;
  renderPage();
  buildNav();
  updateBottomNav(page);
  closeSidebar();
  closeMoreMenu();
}

function toggleSidebar() { sidebarOpen=!sidebarOpen; document.getElementById('sidebar').classList.toggle('open',sidebarOpen); document.getElementById('mobOverlay').classList.toggle('open',sidebarOpen); }

// ══════════════════════════════════════════════════════════════
// DATA PROTECTION — Delete Lock
// All destructive operations route through requireDeleteAuth().
// Flip DELETE_LOCK_ENABLED = false to disable during development.
// ══════════════════════════════════════════════════════════════
var DELETE_LOCK_ENABLED = true;
var DELETE_PIN          = localStorage.getItem('crm_delete_pin') || '7391';  // override via localStorage.setItem('crm_delete_pin','yourpin')
var _deletePinVerified  = false;
var _pendingDeleteFn    = null;

function requireDeleteAuth(actionFn, label) {
  if (!DELETE_LOCK_ENABLED) { actionFn(); return; }
  if (_deletePinVerified)   { actionFn(); return; }
  _pendingDeleteFn = actionFn;
  openModal(
    '<div class="modal-title">' + icon('lock') + ' Confirm Delete</div>',
    '<div style="padding:4px 0 8px">'
    + '<p style="color:var(--text2);margin:0 0 16px;font-size:13.5px">Enter your admin PIN to ' + (label||'delete this item') + '.</p>'
    + '<input id="del_pin_input" type="password" maxlength="8" placeholder="PIN" '
    + 'style="width:100%;padding:10px 12px;border:1.5px solid var(--border2);border-radius:var(--r);font-size:15px;letter-spacing:.2em;font-family:inherit;background:var(--surface2);color:var(--text);outline:none" '
    + 'onkeydown="if(event.key===\'Enter\')confirmDeletePin()" autofocus>'
    + '<div id="del_pin_err" style="color:#DB1924;font-size:12px;margin-top:6px;min-height:16px"></div>'
    + '</div>',
    '<button class="btn btn-default" onclick="closeModal();window._pendingDeleteFn=null">Cancel</button>'
    + '<button class="btn btn-destructive" onclick="confirmDeletePin()">Confirm</button>'
  );
  setTimeout(function(){ var el=document.getElementById('del_pin_input'); if(el) el.focus(); }, 80);
}

function confirmDeletePin() {
  var input = document.getElementById('del_pin_input');
  if (!input) return;
  if (input.value === DELETE_PIN) {
    _deletePinVerified = true;
    closeModal();
    if (_pendingDeleteFn) { var fn = _pendingDeleteFn; _pendingDeleteFn = null; fn(); }
  } else {
    var err = document.getElementById('del_pin_err');
    if (err) err.textContent = 'Incorrect PIN. Please try again.';
    input.value = '';
    input.focus();
  }
}

function lockDeletes() {
  _deletePinVerified = false;
  toast('Delete lock re-enabled', 'ok');
}



// ── Theme ─────────────────────────────────────────────────────
function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  localStorage.setItem('crm_theme', theme);
  var btn   = document.getElementById('themeToggleBtn');
  var icon  = document.getElementById('themeIcon');
  var label = document.getElementById('themeLabel');
  if (icon)  icon.textContent  = theme === 'dark' ? '🌙' : '☀️';
  if (label) label.textContent = theme === 'dark' ? 'Light' : 'Dark';
  if (btn)   btn.title = theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode';
}
function toggleTheme() {
  var current = document.documentElement.getAttribute('data-theme') || 'dark';
  applyTheme(current === 'dark' ? 'light' : 'dark');
}

// ── Font Size ─────────────────────────────────────────────────
function applyFontSize(fs) {
  document.documentElement.setAttribute('data-fs', fs);
  localStorage.setItem('crm_fs', fs);
  ['sm','md','lg','xl'].forEach(function(s) {
    var btn = document.getElementById('fs_'+s);
    if (!btn) return;
    var active = s === fs;
    btn.style.background    = active ? 'rgba(255,255,255,.25)' : 'rgba(255,255,255,.07)';
    btn.style.color         = active ? '#fff' : '#9aa5b4';
    btn.style.borderColor   = active ? 'rgba(255,255,255,.4)' : 'rgba(255,255,255,.12)';
    btn.style.fontWeight    = active ? '700' : '400';
  });
}
function setFontSize(fs) { applyFontSize(fs); }
function closeSidebar() { sidebarOpen=false; document.getElementById('sidebar').classList.remove('open'); document.getElementById('mobOverlay').classList.remove('open'); }

// ── BOTTOM NAV ──
const BOT_NAV_PAGES = ['dashboard','clients','agreements','mailing'];
function updateBottomNav(page) {
  document.querySelectorAll('.bn-item').forEach(b=>b.classList.remove('active'));
  const mapped = BOT_NAV_PAGES.includes(page)?page:'more';
  const el=document.getElementById('bn-'+mapped);
  if(el) el.classList.add('active');
  else { const moreEl=document.getElementById('bn-more'); if(moreEl) moreEl.classList.add('active'); }
}
function toggleMoreMenu() {
  const m=document.getElementById('moreMenu');
  const o=document.getElementById('moreOverlay');
  const open=m.classList.toggle('open');
  if(o) o.style.display=open?'block':'none';
}
function closeMoreMenu() {
  document.getElementById('moreMenu').classList.remove('open');
  const o=document.getElementById('moreOverlay'); if(o) o.style.display='none';
}

// Close any open ev-day dropdowns and user menu on outside click
document.addEventListener('click', function() {
  document.querySelectorAll('[id^="evdrop_"]').forEach(function(d){ d.style.display='none'; });
  var um = document.getElementById('userMenu'); if(um) um.style.display='none';
});

