function portalEditLocation(cid, idx) {
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var editKey = 'loc_' + cid + '_' + idx;
  var d = getPortalBlock(cid, 'location');
  var office = d.offices && d.offices[idx];
  if (!office) return;

  var prevName = office.name; // capture before overwrite for ML match

  office.name     = g('ple_name_'+editKey);
  office.address  = g('ple_addr_'+editKey);
  office.address2 = g('ple_addr2_'+editKey);
  office.city     = g('ple_city_'+editKey) || office.city;
  office.state    = g('ple_state_'+editKey) || office.state;
  office.zip      = g('ple_zip_'+editKey)  || office.zip;
  office.phone    = fmtPhone(g('ple_phone_'+editKey));

  savePortalBlock(cid, 'location', d);

  // Sync changes to matching mailing list entry
  var client = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
  portalUpdateMailingEntry(
    { name: prevName, company: client.company || client.name || '' },
    { name:     office.name,
      address:  office.address  || '',
      address2: office.address2 || '',
      city:     office.city    || '',
      state:    office.state   || '',
      zip:      office.zip     || '',
      phone:    office.phone   || '',
      company:  client.company || client.name || '' }
  );

  // Propagate updated address to all staff members linked to this office
  portalPropagateOfficeToStaff(cid, office, prevName);

  delete portalLocEditing[editKey];
  toast((office.name || 'Location') + ' updated', 'ok');
  renderPortal();
}

// ── Propagate office address changes to linked staff + their ML entries ──
function portalPropagateOfficeToStaff(cid, office, prevOfficeName) {
  var staffBlock = getPortalBlock(cid, 'staff');
  var members    = staffBlock.members || [];
  var client     = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
  var matchName  = prevOfficeName || office.name; // match by old name if renamed
  var changed    = false;

  members.forEach(function(member, idx) {
    // Only update members linked to this specific office by name
    if (!member.locationName || member.locationName !== matchName) return;

    var prevAddr  = member.address;
    var prevEmail = member.email;

    // Update member's location name and address fields from the office
    member.locationName = office.name;
    member.address      = office.address  || '';
    member.address2     = office.address2 || '';
    member.city         = office.city     || '';
    member.state        = office.state    || '';
    member.zip          = office.zip      || '';
    member.updatedAt    = new Date().toISOString();
    changed = true;

    // Re-sync the mailing list entry with the updated address (triggers re-verify)
    if (member.mlAdded) {
      portalUpdateMailingEntry(
        { email: prevEmail, name: member.name, company: client.company || client.name || '' },
        { name:      member.name,
          firstName: member.firstName,
          lastName:  member.lastName,
          email:     member.email,
          phone:     member.phone,
          title:     member.title,
          address:   member.address,
          address2:  member.address2,
          city:      member.city,
          state:     member.state,
          zip:       member.zip,
          company:   client.company || client.name || '',
          tags:      'portal-staff,' + co,
          source:    'Client Portal — Staff (' + office.name + ')' }
      );
    }
  });

  if (changed) savePortalBlock(cid, 'staff', staffBlock);
}

function portalAddLocation(cid) {
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var addr = g('pbl_addr_'+cid);
  if (!addr) { toast('Enter an address','err'); return; }
  var d = getPortalBlock(cid, 'location');
  if (!d.offices) d.offices = [];
  var office = { name:g('pbl_name_'+cid), address:addr, address2:g('pbl_addr2_'+cid), city:g('pbl_city_'+cid), state:g('pbl_state_'+cid), zip:g('pbl_zip_'+cid), phone:fmtPhone(g('pbl_phone_'+cid)) };
  d.offices.push(office);
  savePortalBlock(cid, 'location', d);
  // Auto-sync: add location as mailing list entry if it has a name
  if (office.name) {
    var client = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
    portalSyncToMailing({
      name:    office.name,
      company: client.company || client.name || '',
      address:  office.address  || '',
      address2: office.address2 || '',
      city:     office.city    || '',
      state:    office.state   || '',
      zip:      office.zip     || '',
      phone:    office.phone   || '',
      tags:     'portal-location,' + co,
      source:   'Client Portal — Location',
    });
    // Propagate address to any staff already linked to this office name
    portalPropagateOfficeToStaff(cid, office, office.name);
  }
  toast('Location added','ok');
  renderPortal();
}
function portalDeleteLocation(cid, idx) {
  var d = getPortalBlock(cid, 'location');
  if (d.offices) d.offices.splice(idx, 1);
  savePortalBlock(cid, 'location', d);
  toast('Removed','ok');
  renderPortal();
}

// ── Mailing list auto-sync helper ──────────────────────────────
// Adds a portal entry to the mailing list (deduplicates by email then name)
// ── ML Verify Error Log ────────────────────────────────────────
function mlLogVerifyError(entry, type, reason) {
  if (!DATA[co].mlVerifyErrors) DATA[co].mlVerifyErrors = [];
  DATA[co].mlVerifyErrors.unshift({
    id:      Date.now() + '_' + Math.random().toString(36).slice(2,5),
    co:      co,
    name:    entry.name || ((entry.firstName||'')+' '+(entry.lastName||'')).trim() || 'Unknown',
    company: entry.company || '',
    email:   entry.email   || '',
    address: [entry.address, entry.city, entry.state, entry.zip].filter(Boolean).join(', '),
    type:    type,
    reason:  reason,
    ts:      new Date().toISOString(),
  });
  if (DATA[co].mlVerifyErrors.length > 200) DATA[co].mlVerifyErrors.length = 200;
  persist();
}

function mlSendVerifyErrorNotification(errors) {
  if (!errors || !errors.length) return;
  var notifyTo = co === 'nl' ? 'tawanna@newslinesa.com' : 'tawanna@myrealtyline.com';
  var brand    = BRAND_CONFIGS[co];
  var rows = errors.map(function(e) {
    return '<tr>'
      + '<td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:13px">' + esc(e.name)    + '</td>'
      + '<td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:13px">' + esc(e.company) + '</td>'
      + '<td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:13px">' + esc(e.type)    + '</td>'
      + '<td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:13px">' + esc(e.reason)  + '</td>'
      + '<td style="padding:7px 10px;border-bottom:1px solid #eee;font-size:12px;color:#666">' + esc(e.email || e.address || '') + '</td>'
      + '</tr>';
  }).join('');
  var html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f4f4;font-family:Arial,sans-serif">'
    + '<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:32px 16px">'
    + '<table width="640" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:6px">'
    + '<tr><td style="background:' + brand.brandColor + ';padding:24px 32px">'
    + '<h2 style="margin:0;color:#fff;font-size:20px">' + brand.brandName + ' \u2014 Mailing List Verify Errors</h2></td></tr>'
    + '<tr><td style="padding:28px 32px">'
    + '<p style="margin:0 0 16px;font-size:14px;color:var(--text)">'
    + errors.length + ' contact' + (errors.length!==1?'s':'') + ' could not be fully verified and '
    + 'were added to the mailing list pending review. Please investigate and correct any invalid entries.</p>'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #eee;border-radius:4px">'
    + '<thead><tr style="background:var(--muted)">'
    + '<th style="padding:8px 10px;text-align:left;font-size:12px;color:#666">Name</th>'
    + '<th style="padding:8px 10px;text-align:left;font-size:12px;color:#666">Company</th>'
    + '<th style="padding:8px 10px;text-align:left;font-size:12px;color:#666">Type</th>'
    + '<th style="padding:8px 10px;text-align:left;font-size:12px;color:#666">Reason</th>'
    + '<th style="padding:8px 10px;text-align:left;font-size:12px;color:#666">Value</th>'
    + '</tr></thead><tbody>' + rows + '</tbody></table>'
    + '<p style="margin:20px 0 0;font-size:12px;color:#999">Logged in PressBook CRM \u2192 Mailing List \u2192 Verify Errors tab.</p>'
    + '</td></tr></table></td></tr></table></body></html>';
  fetch('https://email.myrealtyline.com/send-email', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({
      to:      notifyTo,
      subject: '[' + brand.brandName + '] ' + errors.length + ' Mailing List Verify Error' + (errors.length!==1?'s':'') + ' \u2014 Action Required',
      html:    html,
      from:    brand.brandName + ' CRM <' + notifyTo + '>'
    })
  }).catch(function(){});
}

// Internal commit: adds fields to list without re-verifying (called after verify chain completes)
function _mlCommitEntry(fields) {
  if (!DATA[co].mailing) DATA[co].mailing = [];
  var list = DATA[co].mailing;
  var exists = false;
  if (fields.email) {
    exists = list.some(function(m){ return m.email && m.email.toLowerCase() === fields.email.toLowerCase(); });
  }
  if (!exists && fields.name) {
    exists = list.some(function(m){
      return m.name && m.name.toLowerCase() === fields.name.toLowerCase()
        && (m.company||'').toLowerCase() === (fields.company||'').toLowerCase();
    });
  }
  if (exists) return false;
  var parts = (fields.name||'').split(' ');
  var entry = Object.assign({
    id:        'ml_portal_' + Date.now() + '_' + Math.random().toString(36).slice(2,7),
    firstName: fields.firstName || parts[0] || '',
    lastName:  fields.lastName  || parts.slice(1).join(' ') || '',
    updatedAt: new Date().toISOString(),
    createdAt: new Date().toISOString(),
  }, fields);
  list.unshift(entry);
  persist();
  crmFetch(API_BASE + '/api/crm/' + co + '/mailing', {
    method:'PUT', headers:{'Content-Type':'application/json'},
    body: JSON.stringify(list)
  }).catch(function(){});
  return true;
}

// Verify address + email before adding to mailing list. Logs errors and notifies Tawanna.
function portalSyncToMailing(fields) {
  var errors  = [];
  var hasAddr  = !!(fields.address && (fields.city || fields.state));
  var hasEmail = !!fields.email;

  function finish() {
    if (errors.length) {
      errors.forEach(function(e){ mlLogVerifyError(fields, e.type, e.reason); });
      mlSendVerifyErrorNotification(errors);
      fields.addrStatus  = fields.addrStatus  || (hasAddr  ? 'Pending' : undefined);
      fields.emailStatus = fields.emailStatus || (hasEmail ? 'Pending' : undefined);
    }
    var added = _mlCommitEntry(fields);
    if (added) {
      toast('"' + (fields.name||'Contact') + '" added to Mailing List'
        + (errors.length ? ' \u2014 verify errors logged' : ''), errors.length ? '' : 'ok');
    }
  }

  function verifyEmail() {
    if (!hasEmail) { finish(); return; }
    fetch(USPS_PROXY + '/api/verify-email', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ email: fields.email })
    })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      if (data && (data.valid || data.status==='valid' || data.result==='deliverable')) {
        fields.emailVerifiedAt = new Date().toISOString();
        fields.emailStatus     = 'Valid';
      } else {
        errors.push({ type:'email', reason: (data&&data.reason) ? data.reason : 'Undeliverable or invalid' });
        fields.emailStatus = 'Invalid';
      }
      finish();
    })
    .catch(function(){ finish(); });
  }

  function verifyAddr() {
    // Parse concatenated address if city/state missing
    if (fields.address && (!fields.city || !fields.state)) {
      var m = fields.address.match(/^(.+?),\s*([A-Za-z][A-Za-z\s]+?),\s*([A-Z]{2})\s+([\d]{5}(?:-[\d]{4})?)/);
      if (m) { fields.address=m[1].trim(); fields.city=m[2].trim(); fields.state=m[3].trim(); fields.zip=m[4].trim(); hasAddr=true; }
    }
    if (!hasAddr || !fields.address || !fields.city || !fields.state) { verifyEmail(); return; }
    fetch(USPS_PROXY + '/api/usps/verify-address', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ streetAddress:fields.address, secondaryAddress:fields.address2||'', city:fields.city, state:fields.state, ZIPCode:fields.zip||'' })
    })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      if (data && !data.error && data.verified !== false) {
        if (data.streetAddress) fields.address  = data.streetAddress;
        if (data.city)          fields.city     = data.city;
        if (data.state)         fields.state    = data.state;
        if (data.ZIPCode)       fields.zip      = data.ZIPCode;
        fields.addrStatus     = 'Valid';
        fields.addrVerifiedAt = new Date().toISOString();
      } else {
        errors.push({ type:'address', reason: (data&&data.error) ? data.error : 'USPS could not verify' });
        fields.addrStatus = 'Invalid';
      }
      verifyEmail();
    })
    .catch(function(){ verifyEmail(); });
  }

  verifyAddr();
}

// Update or insert a mailing list entry (upsert) with re-verification of changed fields.
function portalUpdateMailingEntry(matchFields, updateFields) {
  if (!DATA[co].mailing) DATA[co].mailing = [];
  var list  = DATA[co].mailing;
  var entry = null;

  if (matchFields.email) {
    entry = list.find(function(m){ return m.email && m.email.toLowerCase() === matchFields.email.toLowerCase(); });
  }
  if (!entry && matchFields.name) {
    entry = list.find(function(m){
      return m.name && m.name.toLowerCase() === matchFields.name.toLowerCase()
        && (m.company||'').toLowerCase() === (matchFields.company||'').toLowerCase();
    });
  }

  if (!entry) {
    portalSyncToMailing(Object.assign({}, matchFields, updateFields));
    return;
  }

  var errors       = [];
  var addrChanged  = updateFields.address && updateFields.address !== entry.address;
  var emailChanged = updateFields.email   && updateFields.email   !== entry.email;

  function commitUpdate() {
    Object.assign(entry, updateFields, { updatedAt: new Date().toISOString() });
    if (updateFields.name) {
      var parts = updateFields.name.split(' ');
      entry.firstName = updateFields.firstName || parts[0] || '';
      entry.lastName  = updateFields.lastName  || parts.slice(1).join(' ') || '';
    }
    if (errors.length) {
      errors.forEach(function(e){ mlLogVerifyError(Object.assign({},matchFields,updateFields), e.type, e.reason); });
      mlSendVerifyErrorNotification(errors);
    }
    persist();
    crmFetch(API_BASE + '/api/crm/' + co + '/mailing', {
      method:'PUT', headers:{'Content-Type':'application/json'},
      body: JSON.stringify(list)
    }).catch(function(){});
  }

  function recheckEmail() {
    if (!emailChanged || !updateFields.email) { commitUpdate(); return; }
    fetch(USPS_PROXY + '/api/verify-email', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ email: updateFields.email })
    })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      if (data && (data.valid || data.status==='valid' || data.result==='deliverable')) {
        updateFields.emailVerifiedAt = new Date().toISOString();
        updateFields.emailStatus     = 'Valid';
      } else {
        errors.push({ type:'email', reason: (data&&data.reason) ? data.reason : 'Undeliverable or invalid' });
        updateFields.emailStatus = 'Invalid';
      }
      commitUpdate();
    })
    .catch(function(){ commitUpdate(); });
  }

  function recheckAddr() {
    if (!addrChanged || !updateFields.address) { recheckEmail(); return; }
    var city  = updateFields.city  || entry.city  || '';
    var state = updateFields.state || entry.state || '';
    if (!city || !state) { recheckEmail(); return; }
    fetch(USPS_PROXY + '/api/usps/verify-address', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ streetAddress:updateFields.address, secondaryAddress:updateFields.address2||entry.address2||'', city:city, state:state, ZIPCode:updateFields.zip||entry.zip||'' })
    })
    .then(function(r){ return r.json(); })
    .then(function(data) {
      if (data && !data.error && data.verified !== false) {
        if (data.streetAddress) updateFields.address  = data.streetAddress;
        if (data.city)          updateFields.city     = data.city;
        if (data.state)         updateFields.state    = data.state;
        if (data.ZIPCode)       updateFields.zip      = data.ZIPCode;
        updateFields.addrStatus     = 'Valid';
        updateFields.addrVerifiedAt = new Date().toISOString();
      } else {
        errors.push({ type:'address', reason: (data&&data.error) ? data.error : 'USPS could not verify' });
        updateFields.addrStatus = 'Invalid';
      }
      recheckEmail();
    })
    .catch(function(){ recheckEmail(); });
  }

  recheckAddr();
}



// ── Bulk sync: sweep all clients' staff blocks → mailing list ──
function portalSyncAllStaffToMailing() {
  var clients = DATA[co].clients || [];
  var added = 0;
  clients.forEach(function(client) {
    var cid     = client.id;
    var locData = getPortalBlock(cid, 'location');
    var offices = locData.offices || [];
    var d       = getPortalBlock(cid, 'staff');
    var members = d.members || [];
    var changed = false;
    members.forEach(function(member, idx) {
      // Refresh address from linked office before syncing
      if (member.locationName) {
        var off = null;
        for (var oi=0;oi<offices.length;oi++){ if((offices[oi].name||'')===member.locationName){off=offices[oi];break;} }
        if (off) {
          member.address  = off.address  || member.address  || '';
          member.address2 = off.address2 || member.address2 || '';
          member.city     = off.city     || member.city     || '';
          member.state    = off.state    || member.state    || '';
          member.zip      = off.zip      || member.zip      || '';
          changed = true;
        }
      }
      if (!member.mlAdded && (member.email || member.name)) {
        portalSyncToMailing({
          name:      member.name,
          firstName: member.firstName,
          lastName:  member.lastName,
          email:     member.email,
          phone:     member.phone,
          company:   client.company || client.name || '',
          title:     member.title,
          address:   member.address  || '',
          address2:  member.address2 || '',
          city:      member.city     || '',
          state:     member.state    || '',
          zip:       member.zip      || '',
          tags:      'portal-staff,' + co,
          source:    'Client Portal — Staff' + (member.locationName ? ' (' + member.locationName + ')' : ''),
        });
        members[idx].mlAdded = true;
        changed = true;
        added++;
      }
    });
    if (changed) savePortalBlock(cid, 'staff', d);
  });
  return added;
}

// ── Bulk sweep: all portal location blocks → mailing list + propagate to staff ─
function portalSyncAllLocationsToMailing() {
  var clients = DATA[co].clients || [];
  clients.forEach(function(client) {
    var cid     = client.id;
    var d       = getPortalBlock(cid, 'location');
    var offices = d.offices || [];
    offices.forEach(function(office) {
      if (!office.name) return;
      portalUpdateMailingEntry(
        { name: office.name, company: client.company || client.name || '' },
        { name:     office.name,
          address:  office.address  || '',
          address2: office.address2 || '',
          city:     office.city    || '',
          state:    office.state   || '',
          zip:      office.zip     || '',
          phone:    office.phone   || '',
          company:  client.company || client.name || '',
          tags:     'portal-location,' + co,
          source:   'Client Portal — Location' }
      );
      // Propagate office address to all staff linked to this office
      portalPropagateOfficeToStaff(cid, office, office.name);
    });
  });
}

var portalStaffSort = {}; // keyed by cid
var portalStaffOpenLocs = {}; // keyed by 'sl_cid_locKey', default open
var portalStaffEditing = {}; // keyed by 'cid_idx'

function sortStaff(arr, key) {
  return arr.slice().sort(function(a, b) {
    switch (key) {
      case 'name-az':
        return ((a.firstName||'')+(a.lastName||'')).toLowerCase() < ((b.firstName||'')+(b.lastName||'')).toLowerCase() ? -1 : 1;
      case 'name-za':
        return ((a.firstName||'')+(a.lastName||'')).toLowerCase() > ((b.firstName||'')+(b.lastName||'')).toLowerCase() ? -1 : 1;
      case 'title':
        return (a.title||'').toLowerCase() < (b.title||'').toLowerCase() ? -1 : 1;
      case 'location':
        return (a.locationName||a.address||'').toLowerCase() < (b.locationName||b.address||'').toLowerCase() ? -1 : 1;
      case 'oldest':
        return new Date(a.addedAt||0) - new Date(b.addedAt||0);
      case 'newest':
      default:
        return new Date(b.addedAt||0) - new Date(a.addedAt||0);
    }
  });
}

function portalStaffBlock(cid, accent) {
  var raw    = getPortalBlock(cid, 'staff').members || [];
  var client = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
  var offices = getPortalBlock(cid, 'location').offices || [];
  var sortKey = portalStaffSort[cid] || 'newest';
  var staff   = sortStaff(raw, sortKey);

  var sortOpts = [['newest','Added ↓'],['oldest','Added ↑'],['name-az','Name A→Z'],['name-za','Name Z→A'],['title','Title A→Z'],['location','Location A→Z']];
  var sortBar = raw.length > 1
    ? '<div style="display:flex;align-items:center;gap:8px;margin-bottom:10px">'
      + '<span style="font-size:11.5px;color:var(--text3)">Sort:</span>'
      + '<select onchange="portalStaffSort[\'' + cid + '\']=this.value;renderPortal()" '
      + 'style="padding:4px 8px;background:var(--muted);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:12px;font-family:inherit;cursor:pointer">'
      + sortOpts.map(function(o){ return '<option value="'+o[0]+'"'+(sortKey===o[0]?' selected':'')+'>'+o[1]+'</option>'; }).join('')
      + '</select>'
      + '<span style="font-size:11.5px;color:var(--text3)">'+raw.length+' member'+(raw.length!==1?'s':'')+'</span>'
      + '</div>'
    : '';


  // ── Group staff by location ──────────────────────────────────
  var locGroups = {};
  staff.forEach(function(s) {
    var key   = s.locationName || (s.address ? '__addr__' + s.address : '__none__');
    var label = s.locationName || (s.address ? s.address : 'No Office / Unassigned');
    if (!locGroups[key]) locGroups[key] = { label: label, members: [] };
    locGroups[key].members.push(s);
  });

  // Group order: named offices first (preserve office order), then others
  var groupOrder = [];
  offices.forEach(function(o) {
    var k = o.name || '';
    if (k && locGroups[k] && groupOrder.indexOf(k) === -1) groupOrder.push(k);
  });
  Object.keys(locGroups).forEach(function(k) {
    if (groupOrder.indexOf(k) === -1) groupOrder.push(k);
  });

  function renderStaffCard(s) {
    var origIdx  = raw.indexOf(s);
    var editKey  = cid + '_' + origIdx;
    var isEditing = !!portalStaffEditing[editKey];
    var initials = ((s.firstName||'').charAt(0) + (s.lastName||'').charAt(0)).toUpperCase() || (s.name||'?').charAt(0).toUpperCase();
    if (isEditing) {
      var locOpts = '<option value="">— Select office location —</option>';
      offices.forEach(function(o, oi) {
        var oAddr = [o.address, o.city, o.state, o.zip].filter(Boolean).join(', ');
        var sel = (s.locationName && s.locationName === (o.name||'')) ? ' selected' : '';
        locOpts += '<option value="'+oi+'"'+sel+'>'+esc(o.name||('Office '+(oi+1)))+(oAddr?' \xb7 '+oAddr:'')+'</option>';
      });
      var manualSel = (!s.locationName && s.address) ? ' selected' : '';
      locOpts += '<option value="other"'+manualSel+'>Other / Home address...</option>';
      var showManual = (!s.locationName && s.address) ? '' : 'none';
      return '<div style="background:var(--muted);border:1px solid '+accent+';border-radius:var(--r);padding:12px;margin-bottom:6px">'
        + '<div style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:'+accent+';margin-bottom:10px">Editing: '+esc((s.firstName||'')+' '+(s.lastName||''))+'</div>'
        + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">'
        +   '<div class="fg"><label>First Name</label><input id="pbe_first_'+editKey+'" value="'+esc(s.firstName||'')+'"></div>'
        +   '<div class="fg"><label>Last Name</label><input id="pbe_last_'+editKey+'" value="'+esc(s.lastName||'')+'"></div>'
        + '</div>'
        + '<div class="fg full" style="margin-bottom:8px"><label>Title / Role</label><input id="pbe_title_'+editKey+'" value="'+esc(s.title||'')+'" placeholder="Marketing Director, Agent, etc."></div>'
        + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">'
        +   '<div class="fg"><label>Email</label><input id="pbe_email_'+editKey+'" type="email" value="'+esc(s.email||'')+'"></div>'
        +   '<div class="fg"><label>Phone</label><input id="pbe_phone_'+editKey+'" value="'+esc(s.phone||'')+'" placeholder="000-000-0000" data-phone-fmt="1"></div>'
        + '</div>'
        + '<div class="fg full" style="margin-bottom:8px"><label>Office Location</label>'
        +   '<select id="pbe_loc_'+editKey+'" class="input" onchange="var v=this.value;var w=document.getElementById(\'pbe_addr_wrap_'+editKey+'\');if(v===\'other\'){w.style.display=\'\';}else{w.style.display=\'none\';}">'+locOpts+'</select></div>'
        + '<div id="pbe_addr_wrap_'+editKey+'" style="display:'+showManual+';margin-bottom:8px">'
        +   '<div class="fg full"><label>Manual Address</label><input id="pbe_addr_'+editKey+'" value="'+esc(s.address||'')+'" placeholder="Street address, city, state, ZIP"></div>'
        + '</div>'
        + '<div style="display:flex;gap:8px;margin-top:4px">'
        +   '<button class="btn btn-sm" style="background:'+accent+';color:#fff;font-weight:600;gap:5px" onclick="portalEditStaff(\''+cid+'\','+origIdx+')">'+icon('check')+' Save</button>'
        +   '<button class="btn btn-default btn-sm" onclick="delete portalStaffEditing[\''+editKey+'\'];renderPortal()">Cancel</button>'
        + '</div>'
        + '</div>';
    }
    return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);margin-bottom:6px">'
      + '<div style="width:36px;height:36px;border-radius:50%;background:color-mix(in srgb,'+accent+' 18%,transparent);color:'+accent+';display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px;flex-shrink:0">'+initials+'</div>'
      + '<div style="flex:1;min-width:0">'
      +   '<div style="font-size:13.5px;font-weight:600;color:var(--text)">'+esc((s.firstName||'')+' '+(s.lastName||''))+'</div>'
      +   (s.title ? '<div style="font-size:12px;color:var(--text2)">'+esc(s.title)+'</div>' : '')
      +   '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:3px">'
      +     (s.email ? '<a href="mailto:'+esc(s.email)+'" style="font-size:11.5px;color:'+accent+';text-decoration:none">'+esc(s.email)+'</a>' : '')
      +     (s.phone ? '<span style="font-size:11.5px;color:var(--text3)">'+esc(s.phone)+'</span>' : '')
      +   '</div>'
      + '</div>'
      + '<div style="display:flex;gap:4px;flex-shrink:0">'
      +   (s.mlAdded
            ? '<span style="font-size:11.5px;font-weight:600;padding:2px 7px;border-radius:99px;background:rgba(13,148,136,.12);color:#0d9488" title="On mailing list">'+icon('mail')+'</span>'
            : '<button class="btn btn-ghost btn-icon-sm" style="color:#0d9488" title="Add to Mailing List" onclick="portalStaffAddToML(\''+cid+'\','+origIdx+')">'+icon('mail')+'</button>')
      +   '<button class="btn btn-ghost btn-icon-sm" title="Edit" onclick="portalStaffEditing[\''+editKey+'\']=true;renderPortal()">'+icon('edit')+'</button>'
      +   '<button class="btn btn-ghost btn-icon-sm" style="color:#DB1924" onclick="portalDeleteStaff(\''+cid+'\','+origIdx+')">'+icon('trash')+'</button>'
      + '</div>'
      + '</div>';
  }

  var rows;
  if (staff.length === 0) {
    rows = '<div style="font-size:13px;color:var(--text3);padding:4px 0 10px">No staff added yet.</div>';
  } else {
    rows = groupOrder.map(function(key) {
      var grp     = locGroups[key];
      var openKey = 'sl_' + cid + '_' + key;
      var isOpen  = portalStaffOpenLocs[openKey] !== false; // default open
      var count   = grp.members.length;
      var matchedOffice = offices.find ? offices.find(function(o){ return (o.name||'') === grp.label; })
                        : (function(){ for(var i=0;i<offices.length;i++){ if((offices[i].name||'')=== grp.label) return offices[i]; } return null; })();
      var subAddr = matchedOffice ? [matchedOffice.address, matchedOffice.city, matchedOffice.state, matchedOffice.zip].filter(Boolean).join(', ') : '';
      return '<div style="border:1px solid var(--border);border-radius:var(--r);overflow:hidden;margin-bottom:8px">'
        + '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--muted);cursor:pointer;user-select:none" '
        +   'onclick="portalStaffOpenLocs[\''+openKey+'\']='+(!isOpen)+';renderPortal()">'
        + '<span style="color:'+accent+';flex-shrink:0">'+icon('map-pin')+'</span>'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-size:13px;font-weight:700;color:var(--text)">'+esc(grp.label)+'</div>'
        +   (subAddr ? '<div style="font-size:11.5px;color:var(--text3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+esc(subAddr)+'</div>' : '')
        + '</div>'
        + '<span style="font-size:11.5px;font-weight:600;padding:2px 8px;border-radius:99px;background:color-mix(in srgb,'+accent+' 12%,transparent);color:'+accent+';flex-shrink:0">'
        +   count+' member'+(count!==1?'s':'')
        + '</span>'
        + '<span style="color:var(--text3);transition:transform .2s;transform:'+(isOpen?'rotate(180deg)':'rotate(0deg)')+'">'
        +   icon('chevron-down')
        + '</span>'
        + '</div>'
        + (isOpen ? '<div style="padding:10px 10px 4px">'+grp.members.map(renderStaffCard).join('')+'</div>' : '')
        + '</div>';
    }).join('');
  }

  // Build location options for dropdown
  var locOptions = '<option value="">— Select office location —</option>';
  offices.forEach(function(o, i) {
    var label = o.name || ('Office ' + (i+1));
    var addr  = [o.address, o.city, o.state, o.zip].filter(Boolean).join(', ');
    locOptions += '<option value="'+i+'" data-addr="'+esc(addr)+'">'+esc(label)+(addr?' · '+addr:'')+'</option>';
  });
  locOptions += '<option value="other">Other / Home address...</option>';

  // Show "no offices" hint if none saved
  var locHint = offices.length === 0
    ? '<div style="font-size:11.5px;color:var(--text3);margin-bottom:8px">No offices saved yet — add one in Location / Offices first, or enter a manual address below.</div>'
    : '';

  var manualAddrId = 'pbs_addr_'+cid;
  var locSelId     = 'pbs_loc_'+cid;

  return '<div>'   // left: staff list
    + '<div style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3);margin-bottom:10px">Staff Members</div>'
    + sortBar
    + rows
    + '</div>'
    + '<div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:14px">'
    + '<div style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3);margin-bottom:10px">Add Staff Member</div>'

    // Name row
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">'
    + '<div class="fg"><label>First Name</label><input id="pbs_first_'+cid+'" placeholder="First"></div>'
    + '<div class="fg"><label>Last Name</label><input id="pbs_last_'+cid+'" placeholder="Last"></div>'
    + '</div>'

    // Title
    + '<div class="fg full" style="margin-bottom:8px"><label>Title / Role</label>'
    + '<input id="pbs_title_'+cid+'" placeholder="Marketing Director, Agent, etc."></div>'

    // Email + Phone
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">'
    + '<div class="fg"><label>Email</label><input id="pbs_email_'+cid+'" type="email" placeholder="email@company.com"></div>'
    + '<div class="fg"><label>Phone</label><input id="pbs_phone_'+cid+'" placeholder="000-000-0000" data-phone-fmt="1"></div>'
    + '</div>'

    // Location selector
    + '<div class="fg full" style="margin-bottom:8px"><label>Office Location</label>'
    + locHint
    + '<select id="'+locSelId+'" class="input" onchange="'
    +   'var v=this.value;'
    +   'var m=document.getElementById(\''+manualAddrId+'\');'
    +   'var wrap=document.getElementById(\'pbs_addr_wrap_'+cid+'\');'
    +   'if(v===\'other\'){wrap.style.display=\'\';m.focus();}'
    +   'else{wrap.style.display=\'none\';m.value=\'\';}'
    + '">'
    + locOptions
    + '</select>'
    + '</div>'

    // Manual address (hidden unless "other" selected)
    + '<div id="pbs_addr_wrap_'+cid+'" style="display:none;margin-bottom:8px">'
    + '<div class="fg full"><label>Manual Address</label>'
    + '<input id="'+manualAddrId+'" placeholder="Street address, city, state, ZIP">'
    + '</div></div>'

    // Mailing list note
    + '<div style="font-size:11.5px;color:var(--text3);margin-bottom:12px;display:flex;align-items:center;gap:5px">'
    + '<span style="color:#0d9488">'+icon('mail')+'</span> Staff members are automatically added to the Mailing List.'
    + '</div>'

    + '<button class="btn btn-sm" style="background:'+accent+';color:#fff;font-weight:600;gap:5px" onclick="portalAddStaff(\''+cid+'\')">'+icon('plus')+' Add Staff Member</button>'
    + '</div>';
}

function portalAddStaff(cid) {
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var firstName = g('pbs_first_'+cid);
  var lastName  = g('pbs_last_'+cid);
  if (!firstName && !lastName) { toast('Enter a name','err'); return; }

  var client  = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};

  // Resolve address: office location OR manual entry
  var locSel   = document.getElementById('pbs_loc_'+cid);
  var locVal   = locSel ? locSel.value : '';
  var offices  = getPortalBlock(cid, 'location').offices || [];
  var locationName = '';
  var address      = '';
  var officeCity    = '';
  var officeState   = '';
  var officeZip     = '';
  var officeAddress2 = '';

  if (locVal === 'other') {
    // Manual address typed
    address      = g('pbs_addr_'+cid);
    locationName = '';
  } else if (locVal !== '') {
    // Saved office selected
    var office   = offices[parseInt(locVal, 10)];
    if (office) {
      locationName = office.name || '';
      address      = [office.address, office.city, office.state, office.zip].filter(Boolean).join(', ');
      officeCity    = office.city     || '';
      officeState   = office.state    || '';
      officeZip     = office.zip      || '';
      officeAddress2 = office.address2 || '';
    }
  }

  var member = {
    firstName:    firstName,
    lastName:     lastName,
    name:         (firstName+' '+lastName).trim(),
    title:        g('pbs_title_'+cid),
    email:        g('pbs_email_'+cid),
    phone:        fmtPhone(g('pbs_phone_'+cid)),
    locationName: locationName,
    address:      address,
    address2:     officeAddress2,
    city:         officeCity,
    state:        officeState,
    zip:          officeZip,
    mlAdded:      false,
    addedAt:      new Date().toISOString(),
  };

  var d = getPortalBlock(cid, 'staff');
  if (!d.members) d.members = [];
  d.members.push(member);

  // Always add to mailing list
  if (member.email || member.name) {
    portalSyncToMailing({
      name:      member.name,
      firstName: member.firstName,
      lastName:  member.lastName,
      email:     member.email,
      phone:     member.phone,
      company:   client.company || client.name || '',
      title:     member.title,
      address:   address,
      address2:  officeAddress2,
      city:      officeCity,
      state:     officeState,
      zip:       officeZip,
      tags:      'portal-staff,' + co,
      source:    'Client Portal — Staff' + (locationName ? ' (' + locationName + ')' : ''),
    });
    member.mlAdded = true;
    d.members[d.members.length - 1] = member;
  }

  savePortalBlock(cid, 'staff', d);
  toast(member.name + ' added', 'ok');
  renderPortal();
}

function portalDeleteStaff(cid, idx) {
  var d = getPortalBlock(cid, 'staff');
  if (d.members) d.members.splice(idx, 1);
  savePortalBlock(cid, 'staff', d);
  toast('Removed', 'ok');
  renderPortal();
}

function portalEditStaff(cid, idx) {
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var editKey  = cid + '_' + idx;
  var d        = getPortalBlock(cid, 'staff');
  var member   = d.members && d.members[idx];
  if (!member) return;

  var locSel  = document.getElementById('pbe_loc_'+editKey);
  var locVal  = locSel ? locSel.value : '';
  var offices = getPortalBlock(cid, 'location').offices || [];
  var locationName = '';
  var address      = '';
  var officeCity    = '';
  var officeState   = '';
  var officeZip     = '';
  var officeAddress2 = '';

  if (locVal === 'other') {
    address      = g('pbe_addr_'+editKey);
    locationName = '';
  } else if (locVal !== '') {
    var office = offices[parseInt(locVal, 10)];
    if (office) {
      locationName = office.name || '';
      address      = [office.address, office.city, office.state, office.zip].filter(Boolean).join(', ');
      officeCity    = office.city     || '';
      officeState   = office.state    || '';
      officeZip     = office.zip      || '';
      officeAddress2 = office.address2 || '';
    }
  }

  var firstName = g('pbe_first_'+editKey);
  var lastName  = g('pbe_last_'+editKey);

  var prevName  = member.name;  // capture before overwrite for ML match
  var prevEmail = member.email;

  member.firstName    = firstName;
  member.lastName     = lastName;
  member.name         = (firstName+' '+lastName).trim();
  member.title        = g('pbe_title_'+editKey);
  member.email        = g('pbe_email_'+editKey);
  member.phone        = fmtPhone(g('pbe_phone_'+editKey));
  member.locationName = locationName;
  member.address      = address;
  member.address2     = officeAddress2;
  member.city         = officeCity;
  member.state        = officeState;
  member.zip          = officeZip;
  member.updatedAt    = new Date().toISOString();

  savePortalBlock(cid, 'staff', d);

  // Sync changes to matching mailing list entry
  var client = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
  portalUpdateMailingEntry(
    { email: prevEmail, name: prevName, company: client.company || client.name || '' },
    { name:      member.name,
      firstName: member.firstName,
      lastName:  member.lastName,
      email:     member.email,
      phone:     member.phone,
      title:     member.title,
      address:   address,
      address2:  officeAddress2,
      city:      officeCity,
      state:     officeState,
      zip:       officeZip,
      company:   client.company || client.name || '' }
  );

  delete portalStaffEditing[editKey];
  toast(member.name + ' updated', 'ok');
  renderPortal();
}

function portalStaffAddToML(cid, idx) {
  var d = getPortalBlock(cid, 'staff');
  var member = d.members && d.members[idx];
  if (!member) return;
  var client = DATA[co].clients.find(function(x){ return x.id===cid; }) || {};
  portalSyncToMailing({
    name:      member.name,
    firstName: member.firstName,
    lastName:  member.lastName,
    email:     member.email,
    phone:     member.phone,
    company:   client.company || client.name || '',
    title:     member.title,
    address:   member.address  || '',
    address2:  member.address2 || '',
    city:      member.city     || '',
    state:     member.state    || '',
    zip:       member.zip      || '',
    tags:      'portal-staff,' + co,
    source:    'Client Portal — Staff' + (member.locationName ? ' (' + member.locationName + ')' : ''),
  });
  member.mlAdded = true;
  savePortalBlock(cid, 'staff', d);
  renderPortal();
}

// ── Billing block ──────────────────────────────────────────────
function portalBillingBlock(cid, accent) {
  var d = getPortalBlock(cid, 'billing');
  return '<div style="display:flex;flex-direction:column;gap:10px">'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">'
    + '<div class="fg"><label>Billing Contact Name</label><input id="pbb_name_'+cid+'" value="'+esc(d.name||'')+'" placeholder="Full name"></div>'
    + '<div class="fg"><label>Billing Email</label><input id="pbb_email_'+cid+'" value="'+esc(d.email||'')+'" placeholder="billing@company.com"></div>'
    + '<div class="fg"><label>Billing Phone</label><input id="pbb_phone_'+cid+'" value="'+esc(d.phone||'')+'" placeholder="000-000-0000" data-phone-fmt="1"></div>'
    + '<div class="fg"><label>Payment Method</label>'
    + '<select id="pbb_method_'+cid+'" class="input">'
    + ['','Check','ACH','Credit Card','Wire Transfer','Other'].map(function(m){ return '<option'+(d.method===m?' selected':'')+'>'+m+'</option>'; }).join('')
    + '</select></div>'
    + '</div>'
    + '<div class="fg full"><label>Billing Address</label><input id="pbb_addr_'+cid+'" value="'+esc(d.address||'')+'" placeholder="Billing street address"></div>'
    + '<div class="fg full"><label>Address 2</label><input id="pbb_addr2_'+cid+'" value="'+esc(d.address2||'')+'" placeholder="Suite, Apt, Unit, etc."></div>'
    + '<div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px">'
    + '<input type="hidden" id="pbb_city_'+cid+'" value="'+esc(d.city||'')+'">'
    + '<input type="hidden" id="pbb_state_'+cid+'" value="'+esc(d.state||'')+'">'
    + '<input type="hidden" id="pbb_zip_'+cid+'" value="'+esc(d.zip||'')+'">'
    + '</div>'
    + '<div class="fg full"><label>Notes / PO Number / Terms</label><textarea id="pbb_notes_'+cid+'" rows="2" style="width:100%;resize:vertical;font-family:inherit">'+esc(d.notes||'')+'</textarea></div>'
    + '<div><button class="btn btn-sm" style="background:'+accent+';color:#fff;font-weight:600" onclick="portalSaveBilling(\''+cid+'\')">Save Billing Details</button></div>'
    + '</div>';
}

function portalSaveBilling(cid) {
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  savePortalBlock(cid, 'billing', {
    name:    g('pbb_name_'+cid),
    email:   g('pbb_email_'+cid),
    phone:   g('pbb_phone_'+cid),
    method:  g('pbb_method_'+cid),
    address: g('pbb_addr_'+cid),
    address2: g('pbb_addr2_'+cid),
    city:    g('pbb_city_'+cid),
    state:   g('pbb_state_'+cid),
    zip:     g('pbb_zip_'+cid),
    notes:   g('pbb_notes_'+cid),
  });
  toast('Billing details saved','ok');
}

function clientSendPortalInvite(clientId) {
  var c = DATA[co].clients.find(function(x){ return x.id === clientId; });
  if (!c) return;
  var email = c.portalEmail || c.email || '';
  if (!email) { toast('No email on file for this client','err'); return; }
  var wasInvited = !!c.portalInvitedAt;
  toast((wasInvited ? 'Resending' : 'Sending') + ' portal invite to ' + email + '...', '');
  fetch(USPS_PROXY + '/api/portal/request-access', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({
      email: email,
      co: co,
      clients: DATA[co].clients  // send full client list so proxy can find the record
    })
  })
  .then(function(r){ return r.json(); })
  .then(function(data) {
    if (data.error) { toast('Error: ' + sanitizeApiError(data.error), 'err'); return; }
    c.portalInvitedAt = new Date().toISOString();
    persist();
    toast('Portal invite sent to ' + email, 'ok');
    if (currentPage === 'clients') renderClients();
  })
  .catch(function(e){ toast('Error: ' + sanitizeApiError(e.message), 'err'); });
}

// Keep old name as alias for Portal page button
function portalSendLoginLink(clientId) { clientSendPortalInvite(clientId); }

