// Apply a saved location to the event modal fields
function evApplySavedLocation(idx) {
  var locs = getEvLocations();
  var loc = locs[idx];
  if (!loc) return;
  var set = function(id, val){ var el=document.getElementById(id); if(el) el.value=val||''; };
  set('ev_loc',     loc.name);
  set('ev_address', loc.address);
  set('ev_city',    loc.city);
  set('ev_state',   loc.state);
  set('ev_zip',     loc.zip);
  toast('Location applied','ok');
}

function getEvents() { return eventsData[co]; }

function purgeExpiredEvents() {
  var now = new Date();
  now.setHours(0,0,0,0); // midnight today — keep today's events
  ['rl','nl'].forEach(function(c) {
    if (!Array.isArray(eventsData[c])) return;
    var removed = [];
    eventsData[c] = eventsData[c].filter(function(ev) {
      // Use endDateTime if set, otherwise startDateTime
      var dateStr = ev.endDateTime || ev.startDateTime;
      if (!dateStr) return true; // no date — keep
      var evDate = new Date(dateStr);
      evDate.setHours(0,0,0,0);
      var expired = evDate < now;
      if (expired && ev.syncedApptId) removed.push(ev.syncedApptId);
      return !expired;
    });
    // Remove synced team calendar appointments for expired events
    if (removed.length) {
      DATA[c].appointments = (DATA[c].appointments||[]).filter(function(a) {
        return removed.indexOf(a.id) === -1;
      });
    }
  });
}

// ── RENDER PAGE ───────────────────────────────────────────────
function renderEvents() {
  purgeExpiredEvents();
  persist();
  var coName = co === 'rl' ? 'RealtyLine' : 'Newsline';
  const allEvs = getEvents().filter(function(e){ return (e.title||'').trim() !== ''; });
  var totalPagesEv = Math.max(1, Math.ceil(allEvs.length / EV_PAGE_SIZE));
  evPage = Math.max(1, Math.min(evPage, totalPagesEv));
  var evStartIdx = (evPage-1)*EV_PAGE_SIZE;
  const evs = allEvs.slice(evStartIdx, evStartIdx+EV_PAGE_SIZE);
  const accent = ACCENT[co];

  function viewBtn(m, svgPath, label) {
    const active = evViewMode === m;
    return '<button title="' + label + '" onclick="evSetView(\'' + m + '\')"'
      + ' style="width:36px;height:36px;display:flex;align-items:center;justify-content:center;'
      + 'border:none;cursor:pointer;transition:all .15s;'
      + 'background:' + (active ? accent : 'transparent') + ';'
      + 'color:' + (active ? '#fff' : 'var(--text2)') + '">'
      + '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">' + svgPath + '</svg>'
      + '</button>';
  }

  const selectedIds = Object.keys(_evSelected).filter(function(id){ return _evSelected[id]; });
  const selCount    = selectedIds.length;
  const allCount    = evs.length;

  document.getElementById('pageArea').innerHTML =
    '<div class="page-header">'
    +   '<div style="display:flex;align-items:center;gap:10px">'
    +     '<label style="display:flex;align-items:center;gap:7px;cursor:pointer;user-select:none" title="Select all events">'
    +       '<input type="checkbox" id="ev_select_all" '+(selCount===allCount&&allCount>0?'checked':'')+' '+(selCount>0&&selCount<allCount?'style="accent-color:'+accent+';opacity:.6"':'style="accent-color:'+accent+'"')+' onchange="evToggleSelectAll(this.checked)" style="width:16px;height:16px;accent-color:'+accent+';cursor:pointer">'
    +     '</label>'
    +     '<div>'
    +       '<div class="page-title">'+coName+' Industry Events</div>'
    +       '<div class="page-subtitle">' + (selCount > 0 ? selCount + ' selected of ' + allCount : allCount + ' event' + (allCount !== 1 ? 's' : '') + ' scheduled') + '</div>'
    +     '</div>'
    +   '</div>'
    +   '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
    +   (selCount > 0
      ? '<button class="btn btn-sm" onclick="evDeleteSelected()" style="background:#DB1924;color:#fff;font-weight:600;gap:6px">' + icon('trash') + ' Delete ' + selCount + ' Event' + (selCount !== 1 ? 's' : '') + '</button>'
        + '<button class="btn btn-default btn-sm" onclick="evClearSelection()" style="gap:5px">Clear</button>'
      : '')
    +     '<div style="display:flex;border:1px solid var(--border);border-radius:var(--r);overflow:hidden">'
    +       viewBtn('calendar','<rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/>','Calendar')
    +       viewBtn('list','<line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/>','List')
    +       viewBtn('cards','<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>','Cards')
    +     '</div>'
    +     '<div style="position:relative">'
    +       '<button class="btn btn-default btn-sm" onclick="toggleEvExport()" id="evExportTrigger">'
    +         icon('download') + ' Export</button>'
    +       '<div id="evExportMenu" style="display:none;position:absolute;right:0;top:calc(100% + 4px);'
    +         'background:var(--surface);border:1px solid var(--border2);border-radius:var(--r);'
    +         'box-shadow:var(--shadow-md);z-index:60;min-width:170px;overflow:hidden">'
    +         '<div onclick="exportEvCsv()" style="padding:10px 14px;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:8px;color:var(--text)" onmouseover="this.style.background=\'var(--muted)\'" onmouseout="this.style.background=\'\'">' + icon('file-text') + ' Export as CSV</div>'
    +         '<div onclick="exportEvIcs()" style="padding:10px 14px;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:8px;color:var(--text)" onmouseover="this.style.background=\'var(--muted)\'" onmouseout="this.style.background=\'\'">' + icon('calendar') + ' Export as ICS</div>'
    +       '</div>'
    +     '</div>'
    +     '<button class="btn btn-default btn-sm" onclick="openEvImport()">' + icon('upload') + ' Import</button>'
    +     '<button class="btn btn-default btn-sm" onclick="openEvManage()">' + icon('settings') + ' Manage</button>'
    +     '<button class="btn btn-accent btn-sm" onclick="openEvModal()" style="background:' + accent + ';color:#fff;font-weight:600">' + icon('plus') + ' New Event</button>'
    +   '</div>'
    + '</div>'
    + '<div class="page-content">'
    + (evs.length === 0 ? evEmptyState(accent) : evContent(evs, accent))
    + '</div>';
}

function evSetView(m) { evViewMode = m; renderEvents(); }

// ── Bulk selection ────────────────────────────────────────────
function evToggleSelect(id, checked) {
  if (checked) _evSelected[id] = true;
  else delete _evSelected[id];
  renderEvents();
}

function evToggleSelectAll(checked) {
  const evs = getEvents().filter(function(e){ return (e.title||'').trim() !== ''; });
  if (checked) {
    evs.forEach(function(ev){ _evSelected[ev.id] = true; });
  } else {
    _evSelected = {};
  }
  renderEvents();
}

function evClearSelection() {
  _evSelected = {};
  renderEvents();
}

function evDeleteSelected() {
  const ids = Object.keys(_evSelected).filter(function(id){ return _evSelected[id]; });
  if (!ids.length) return;
  openModal(
    '<div class="modal-title" style="color:#DB1924">' + icon('trash') + ' Delete ' + ids.length + ' Event' + (ids.length !== 1 ? 's' : '') + '</div>',
    '<p style="color:var(--text2)">Are you sure you want to delete <strong>' + ids.length + '</strong> event' + (ids.length !== 1 ? 's' : '') + '? This cannot be undone.</p>',
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-sm" onclick="evConfirmDeleteSelected()" style="background:#DB1924;color:#fff;font-weight:600">' + icon('trash') + ' Delete All</button>'
  );
}

function evConfirmDeleteSelected() {
  requireDeleteAuth(function(){
    const ids = Object.keys(_evSelected).filter(function(id){ return _evSelected[id]; });
    ids.forEach(function(id) {
      var ev = eventsData[co] && eventsData[co].find(function(e){ return e.id === id; });
      if (ev && ev.syncedApptId) {
        DATA[co].appointments = DATA[co].appointments.filter(function(a){ return a.id !== ev.syncedApptId; });
      }
    });
    eventsData[co] = eventsData[co].filter(function(e){ return !_evSelected[e.id]; });
    _evSelected = {};
    persist(); closeModal(); renderEvents();
    toast('Deleted ' + ids.length + ' event' + (ids.length !== 1 ? 's' : ''), 'ok');
  }, 'delete selected events');
}

function evEmptyState(accent) {
  return '<div class="empty">'
    + '<div class="empty-icon-wrap"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="1.5"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/><line x1="8" y1="14" x2="16" y2="14"/></svg></div>'
    + '<div class="empty-title">No events scheduled</div>'
    + '<div class="empty-sub">Create your first event or import from a CSV or ICS file.</div>'
    + '<div style="display:flex;gap:8px">'
    + '<button class="btn btn-default btn-sm" onclick="openEvImport()">' + icon('upload') + ' Import</button>'
    + '<button class="btn btn-accent btn-sm" onclick="openEvModal()" style="background:' + accent + ';color:#fff">' + icon('plus') + ' New Event</button>'
    + '</div></div>';
}

function evContent(evs, accent) {
  if (evViewMode === 'calendar') return evCalendarView(evs, accent);
  if (evViewMode === 'list')     return evListView(evs, accent);
  return evCardsView(evs, accent);
}

// ── CALENDAR VIEW ─────────────────────────────────────────────
function evCalendarView(evs, accent) {
  const firstDay    = new Date(evCalYear, evCalMonth, 1).getDay();
  const daysInMonth = new Date(evCalYear, evCalMonth + 1, 0).getDate();
  const today       = new Date();
  const isThisMonth = today.getMonth() === evCalMonth && today.getFullYear() === evCalYear;

  const byDay = {};
  evs.forEach(function(ev) {
    if (!ev.startDateTime) return;
    const d = new Date(ev.startDateTime);
    if (d.getFullYear() === evCalYear && d.getMonth() === evCalMonth) {
      const day = d.getDate();
      if (!byDay[day]) byDay[day] = [];
      byDay[day].push(ev);
    }
    (ev.additionalDates || []).forEach(function(dt) {
      const d2 = new Date(dt.date);
      if (d2.getFullYear() === evCalYear && d2.getMonth() === evCalMonth) {
        const day2 = d2.getDate();
        if (!byDay[day2]) byDay[day2] = [];
        if (!byDay[day2].find(function(x){return x.id===ev.id;})) byDay[day2].push(ev);
      }
    });
  });

  const MAX_PILLS = 5;

  let cells = '';
  // Empty leading cells
  for (let i = 0; i < firstDay; i++) {
    cells += '<div style="height:130px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--muted);opacity:.35;box-sizing:border-box"></div>';
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const isToday   = isThisMonth && today.getDate() === d;
    const dow       = (firstDay + d - 1) % 7;
    const isWeekend = dow === 0 || dow === 6;
    const dayEvs    = byDay[d] || [];
    const dateStr   = evCalYear + '-' + String(evCalMonth+1).padStart(2,'0') + '-' + String(d).padStart(2,'0');
    const cellBg    = isToday ? 'var(--ev-today)' : isWeekend ? 'var(--muted)' : 'var(--surface)';
    const overflow  = dayEvs.length > MAX_PILLS ? dayEvs.length - MAX_PILLS : 0;
    const dropId    = 'evdrop_' + evCalYear + '_' + evCalMonth + '_' + d;

    let pills = '';
    dayEvs.slice(0, MAX_PILLS).forEach(function(ev) {
      const c = ev.eventColor || accent;
      const t = fmtEvTime(ev.startDateTime);
      pills += '<div onclick="event.stopPropagation();openEvSummary(\'' + ev.id + '\')"'
        + ' style="font-size:11px;padding:2px 5px;border-radius:3px;background:' + c + ';color:#fff;'
        + 'white-space:nowrap;overflow:hidden;text-overflow:ellipsis;cursor:pointer;line-height:1.4;flex-shrink:0"'
        + ' title="' + esc(ev.title||'Event') + '">'
        + (ev.isAllDay || !t ? '' : '<span style="opacity:.8">' + t + ' </span>')
        + esc(ev.title||'Event') + '</div>';
    });

    // +N more pill → toggles dropdown
    if (overflow > 0) {
      // Build dropdown items for ALL events on this day
      var dropItems = dayEvs.map(function(ev) {
        const c = ev.eventColor || accent;
        const t = fmtEvTime(ev.startDateTime);
        return '<div onclick="event.stopPropagation();document.getElementById(\'' + dropId + '\').style.display=\'none\';openEvSummary(\'' + ev.id + '\')"'
          + ' style="display:flex;align-items:center;gap:7px;padding:7px 12px;cursor:pointer;font-size:12px;color:var(--text)"'
          + ' onmouseover="this.style.background=\'var(--muted2)\'" onmouseout="this.style.background=\'transparent\'">'
          + '<span style="width:8px;height:8px;border-radius:50%;background:' + c + ';flex-shrink:0"></span>'
          + '<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'
          + (ev.isAllDay || !t ? '' : '<span style="color:var(--text3);margin-right:4px">' + t + '</span>')
          + esc(ev.title||'Event') + '</span></div>';
      }).join('');

      pills += '<div onclick="event.stopPropagation();var d=document.getElementById(\'' + dropId + '\');d.style.display=d.style.display===\'none\'?\'block\':\'none\'"'
        + ' style="font-size:11px;padding:2px 6px;border-radius:3px;background:var(--muted2);color:var(--text2);cursor:pointer;line-height:1.6;border:1px solid var(--border2);text-align:center;flex-shrink:0">'
        + '+' + overflow + ' more</div>'
        + '<div id="' + dropId + '" style="display:none;position:absolute;top:100%;left:0;min-width:200px;max-width:280px;background:var(--surface2);border:1px solid var(--border2);border-radius:var(--r);box-shadow:var(--shadow-md);z-index:400;max-height:220px;overflow-y:auto">'
        + '<div style="padding:8px 12px 6px;font-size:11.5px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.05em;border-bottom:1px solid var(--border)">'
        + EV_MONTHS[evCalMonth] + ' ' + d + ' — ' + dayEvs.length + ' events</div>'
        + dropItems
        + '</div>';
    }

    const dot = dayEvs.length > 0 ? '<div style="width:5px;height:5px;border-radius:50%;background:' + accent + ';margin:2px auto 0"></div>' : '';

    cells += '<div onclick="openEvModal(null,\'' + dateStr + '\')"'
      + ' style="height:130px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);'
      + 'padding:4px;cursor:pointer;transition:background .1s;background:' + cellBg + ';position:relative;'
      + 'display:flex;flex-direction:column;box-sizing:border-box"'
      + ' onmouseover="this.style.background=\'var(--muted)\'"'
      + ' onmouseout="this.style.background=\'' + cellBg + '\'">'
      // Date number — fixed height row
      + '<div style="display:flex;justify-content:flex-end;height:24px;flex-shrink:0;margin-bottom:2px">'
      + '<span style="font-size:11px;font-weight:' + (isToday?'700':'500') + ';width:20px;height:20px;'
      + 'display:flex;align-items:center;justify-content:center;border-radius:50%;flex-shrink:0;'
      + (isToday ? 'background:' + accent + ';color:#fff' : 'color:var(--text)') + '">' + d + '</span>'
      + '</div>'
      // Pills area — takes remaining space, clips overflow
      + '<div class="ev-pills" style="flex:1;overflow:hidden;display:flex;flex-direction:column;gap:2px;position:relative">'
      + pills
      + '</div>'
      + '<div class="ev-dot">' + dot + '</div>'
      + '</div>';
  }

  // Trailing empty cells
  const total = firstDay + daysInMonth;
  const rem   = total % 7 === 0 ? 0 : 7 - (total % 7);
  for (let i = 0; i < rem; i++) {
    cells += '<div style="height:130px;border-right:1px solid var(--border);border-bottom:1px solid var(--border);background:var(--muted);opacity:.35;box-sizing:border-box"></div>';
  }

  return '<style>'
    + ':root{--ev-today:color-mix(in srgb,' + accent + ' 10%,var(--surface));}'
    + '.ev-dot{display:none}.ev-pills{display:flex}'
    + '.ev-cal-grid>div{box-sizing:border-box}'
    + '@media(max-width:600px){.ev-pills{display:none}.ev-dot{display:block}}'
    + '.ev-nav-btn{padding:6px 8px;border:none;background:none;cursor:pointer;border-radius:var(--r);color:var(--text);transition:background .12s}'
    + '.ev-nav-btn:hover{background:var(--border)}'
    + '@media(max-width:480px){.ev-day-lg{display:none!important}.ev-day-sm{display:inline!important}}'
    + '</style>'
    + '<div class="card" style="overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--border);background:var(--muted)">'
    + '<button onclick="evCalNav(-1)" class="ev-nav-btn"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg></button>'
    + '<div style="display:flex;align-items:center;gap:12px">'
    + '<span style="font-size:15px;font-weight:600">' + EV_MONTHS[evCalMonth] + ' ' + evCalYear + '</span>'
    + '<button onclick="evGoToday()" style="font-size:11.5px;padding:3px 10px;border:1px solid var(--border2);border-radius:var(--rfull);background:var(--surface);color:var(--text2);cursor:pointer">Today</button>'
    + '</div>'
    + '<button onclick="evCalNav(1)" class="ev-nav-btn"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg></button>'
    + '</div>'
    + '<div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));width:100%;background:var(--muted);border-bottom:1px solid var(--border);border-left:1px solid var(--border)">'
    + EV_DAYS.map(function(d,i) {
        return '<div style="padding:8px 0;text-align:center;font-size:11.5px;font-weight:600;color:' + (i===0||i===6?'var(--text3)':'var(--text2)') + ';border-right:1px solid var(--border);box-sizing:border-box">'
          + '<span class="ev-day-lg">' + d + '</span><span class="ev-day-sm" style="display:none">' + d[0] + '</span></div>';
      }).join('')
    + '</div>'
    + '<div class="ev-cal-grid" style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));width:100%;border-left:1px solid var(--border)">' + cells + '</div>'
    + '</div>';
}

function evCalNav(dir) {
  evCalMonth += dir;
  if (evCalMonth > 11) { evCalMonth = 0; evCalYear++; }
  if (evCalMonth < 0)  { evCalMonth = 11; evCalYear--; }
  renderEvents();
}
function evGoToday() { evCalYear = new Date().getFullYear(); evCalMonth = new Date().getMonth(); renderEvents(); }

function fmtEvTime(s) {
  if (!s) return '';
  try { const d=new Date(s); if(isNaN(d.getTime())) return ''; const h=d.getHours(),m=d.getMinutes(),ap=h>=12?'PM':'AM'; return (h%12||12)+':'+(m<10?'0'+m:m)+' '+ap; } catch { return ''; }
}
function fmtEvRange(ev) {
  if (!ev.startDateTime) return '—';
  try {
    const s = new Date(ev.startDateTime);
    if (isNaN(s.getTime())) return '—';
    const opts = {month:'short',day:'numeric',year:'numeric'};
    if (ev.isAllDay) return s.toLocaleDateString('en-US',opts);
    const st = s.toLocaleString('en-US',Object.assign({},opts,{hour:'numeric',minute:'2-digit'}));
    if (!ev.endDateTime) return st;
    const e = new Date(ev.endDateTime);
    if (isNaN(e.getTime())) return st;
    if (e.toDateString()===s.toDateString()) return st + ' – ' + fmtEvTime(ev.endDateTime);
    return st + ' – ' + e.toLocaleString('en-US',Object.assign({},opts,{hour:'numeric',minute:'2-digit'}));
  } catch { return '—'; }
}

// ── LIST VIEW ─────────────────────────────────────────────────
function evListView(evs, accent) {
  const sorted = evs.slice().sort(function(a,b){
    return (a.startDateTime?new Date(a.startDateTime).getTime():0)-(b.startDateTime?new Date(b.startDateTime).getTime():0);
  });
  const groups = {};
  sorted.forEach(function(ev) {
    let key = 'No Date';
    if (ev.startDateTime) { try { const d=new Date(ev.startDateTime); if(!isNaN(d.getTime())) key=EV_MONTHS[d.getMonth()]+' '+d.getFullYear(); } catch{} }
    if (!groups[key]) groups[key] = [];
    groups[key].push(ev);
  });

  return Object.keys(groups).map(function(month) {
    const rows = groups[month].map(function(ev) {
      const color    = ev.eventColor || accent;
      const catColor = EV_CAT_COLORS[ev.category] || '#6B7280';
      const venue    = [ev.location, ev.city, ev.state].filter(Boolean).join(', ');
      const prices   = [];
      if (ev.memberPrice)    prices.push('Member: $' + ev.memberPrice);
      if (ev.nonMemberPrice) prices.push('Non-member: $' + ev.nonMemberPrice);
      const isSel = !!_evSelected[ev.id];

      return '<div style="display:flex;align-items:stretch;border-bottom:1px solid var(--border);'+(isSel?'background:color-mix(in srgb,'+accent+' 8%,var(--surface))':'')+'">'
        + '<div style="display:flex;align-items:center;padding:0 12px;flex-shrink:0" onclick="event.stopPropagation()">'
        + '<input type="checkbox" '+(isSel?'checked':'')+' style="width:15px;height:15px;accent-color:'+accent+';cursor:pointer" onchange="evToggleSelect(\''+ev.id+'\',this.checked)">'
        + '</div>'
        + '<button onclick="openEvSummary(\'' + ev.id + '\')"'
        + ' style="flex:1;text-align:left;display:flex;align-items:stretch;border:none;'
        + 'background:transparent;cursor:pointer;transition:background .1s;padding:0"'
        + ' onmouseover="this.style.background=\'var(--muted)\'" onmouseout="this.style.background=\'transparent\'">'
        + '<div style="width:4px;flex-shrink:0;background:' + color + '"></div>'
        + '<div style="flex:1;padding:11px 16px;min-width:0">'
        + '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:3px">'
        + '<span style="font-weight:600;font-size:13.5px;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(ev.title||'Untitled') + '</span>'
        + (ev.category ? '<span style="flex-shrink:0;font-size:11px;border-radius:var(--rfull);padding:2px 8px;color:#fff;background:' + catColor + '">' + esc(ev.category) + '</span>' : '')
        + '</div>'
        + '<div style="font-size:12px;color:var(--text2)">' + fmtEvRange(ev) + '</div>'
        + (venue ? '<div style="font-size:12px;color:var(--text2);margin-top:2px">📍 ' + esc(venue) + '</div>' : '')
        + (prices.length ? '<div style="font-size:11.5px;color:var(--text3);margin-top:2px">' + prices.join('  ·  ') + '</div>' : '')
        + (ev.organizer ? '<div style="font-size:11.5px;color:var(--text3);margin-top:1px">Organizer: ' + esc(ev.organizer) + '</div>' : '')
        + '</div></button></div>';
    }).join('');

    return '<div style="margin-bottom:24px">'
      + '<div style="font-size:11.5px;font-weight:700;color:var(--text2);text-transform:uppercase;letter-spacing:.08em;margin-bottom:8px;padding:0 2px">' + month + '</div>'
      + '<div class="card" style="overflow:hidden;padding:0">' + rows + '</div>'
      + '</div>';
  }).join('');
}

// ── CARDS VIEW ────────────────────────────────────────────────
function evCardsView(evs, accent) {
  const sorted = evs.slice().sort(function(a,b){
    return (a.startDateTime?new Date(a.startDateTime).getTime():0)-(b.startDateTime?new Date(b.startDateTime).getTime():0);
  });
  const cards = sorted.map(function(ev) {
    const color    = ev.eventColor || accent;
    const catColor = EV_CAT_COLORS[ev.category] || '#6B7280';
    const venue    = [ev.location, ev.city, ev.state].filter(Boolean).join(', ');
    const hasPrices = ev.memberPrice || ev.nonMemberPrice;
    const isSel    = !!_evSelected[ev.id];

    return '<div onclick="openEvSummary(\'' + ev.id + '\')"'
      + ' class="card" style="cursor:pointer;display:flex;flex-direction:column;padding:0;overflow:hidden;transition:transform .15s,box-shadow .15s;'+(isSel?'outline:2px solid '+accent+';outline-offset:-1px':'') + '"'
      + ' onmouseover="this.style.transform=\'translateY(-2px)\';this.style.boxShadow=\'var(--shadow-md)\'"'
      + ' onmouseout="this.style.transform=\'\';this.style.boxShadow=\'\'">'
      + '<div style="height:4px;background:' + color + ';flex-shrink:0"></div>'
      + '<div style="flex:1;padding:14px;display:flex;flex-direction:column;gap:7px">'
      + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:6px">'
      + (ev.category ? '<span style="display:inline-block;font-size:11px;border-radius:var(--rfull);padding:2px 8px;color:#fff;background:' + catColor + ';font-weight:500">' + esc(ev.category) + '</span>' : '<span></span>')
      + '<div onclick="event.stopPropagation()">'
      + '<input type="checkbox" '+(isSel?'checked':'')+' style="width:15px;height:15px;accent-color:'+accent+';cursor:pointer" onchange="evToggleSelect(\''+ev.id+'\',this.checked)">'
      + '</div></div>'
      + '<div style="font-weight:600;font-size:13.5px;color:var(--text);line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden">' + esc(ev.title||'Untitled') + '</div>'
      + '<div style="font-size:12px;color:var(--text2)">' + fmtEvRange(ev) + '</div>'
      + (venue ? '<div style="font-size:12px;color:var(--text2)">📍 ' + esc(venue) + '</div>' : '')
      + (hasPrices ? '<div style="font-size:11.5px;color:var(--text3)">'
          + (ev.memberPrice ? 'Member $' + ev.memberPrice : '')
          + (ev.memberPrice && ev.nonMemberPrice ? '  ·  ' : '')
          + (ev.nonMemberPrice ? 'Non-member $' + ev.nonMemberPrice : '')
          + '</div>' : '')
      + (ev.organizer ? '<div style="font-size:11.5px;color:var(--text3)">' + esc(ev.organizer) + '</div>' : '')
      + '</div>'
      + '<div style="border-top:1px solid var(--border);padding:7px 10px;background:var(--muted);display:flex;justify-content:flex-end;gap:4px" onclick="event.stopPropagation()">'
      + '<button onclick="openEvModal(\'' + ev.id + '\')" class="btn btn-ghost btn-icon-sm" title="Edit">' + icon('edit') + '</button>'
      + '<button onclick="deleteEv(\'' + ev.id + '\')" class="btn btn-ghost btn-icon-sm" title="Delete" style="color:#DB1924">' + icon('trash') + '</button>'
      + '</div></div>';
  }).join('');

  return '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:14px">' + cards + '</div>';
}

// ── EVENT MODAL ───────────────────────────────────────────────
function openEvSummary(id) {
  var ev     = id ? getEvents().find(function(e){ return e.id === id; }) : null;
  if (!ev) { openEvModal(id); return; }
  var accent = ev.eventColor || ACCENT[co];

  function row(ico, label, val) {
    if (!val) return '';
    return '<div style="display:flex;align-items:flex-start;gap:10px;padding:9px 0;border-bottom:1px solid var(--border)">'
      + '<span style="color:'+accent+';flex-shrink:0;margin-top:1px">'+ico+'</span>'
      + '<div style="flex:1;min-width:0">'
      + '<div style="font-size:11px;font-weight:600;color:var(--text3);text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px">'+label+'</div>'
      + '<div style="font-size:13.5px;color:var(--text);line-height:1.5">'+esc(val)+'</div>'
      + '</div></div>';
  }

  // Date/time
  var dateStr;
  if (ev.isAllDay) {
    var s = ev.startDateTime ? fmtDate(ev.startDateTime) : '';
    var e = ev.endDateTime   ? fmtDate(ev.endDateTime)   : '';
    dateStr = s + (e && e !== s ? ' – ' + e : '');
  } else {
    var startDT = ev.startDateTime ? fmtDT(ev.startDateTime) : '';
    var endDT   = ev.endDateTime   ? fmtDT(ev.endDateTime)   : '';
    dateStr = startDT + (endDT ? ' – ' + endDT : '');
  }

  // Pricing
  var pricing = '';
  if (ev.memberPrice && ev.nonMemberPrice) pricing = 'Member: $'+ev.memberPrice+' · Non-member: $'+ev.nonMemberPrice;
  else if (ev.memberPrice)    pricing = 'Member: $'+ev.memberPrice;
  else if (ev.nonMemberPrice) pricing = '$'+ev.nonMemberPrice;

  // Category badge
  var catBadge = ev.category ? '<span style="font-size:11px;font-weight:600;padding:2px 8px;border-radius:3px;background:'+accent+'22;color:'+accent+'">'+esc(ev.category)+'</span>' : '';

  var body = '<div style="padding:4px 0">'
    + (catBadge ? '<div style="margin-bottom:14px">'+catBadge+'</div>' : '')
    + row(icon('clock'),      'Date & Time',  dateStr)
    + row(icon('map-pin'),    'Location',     ev.location || ev.address)
    + row(icon('file-text'),  'Description',  ev.description)
    + row(icon('user'),       'Organizer',    ev.organizer)
    + row(icon('dollar-sign'),'Pricing',      pricing)
    + (ev.registrationUrl ? '<div style="margin-top:12px"><a href="'+esc(ev.registrationUrl)+'" target="_blank" style="font-size:13px;color:'+accent+';font-weight:600;text-decoration:none">Register →</a></div>' : '')
    + '</div>';

  openModal(
    '<div class="modal-title">'+icon('cal-range')+' '+esc(ev.title||'Event')+'</div>',
    body,
    '<button class="btn btn-default" onclick="closeModal()">Close</button>'
    + '<button class="btn btn-default" onclick="closeModal();openEvModal(\'' + id + '\')" style="gap:5px">'+icon('edit')+' Edit</button>'
  );
}

function openEvModal(id, prefilled) {
  evEditingId     = id || null;
  evPrefilledDate = prefilled || '';
  const ev     = id ? getEvents().find(function(e){return e.id===id;}) : null;
  const accent = ACCENT[co];
  const isEdit = !!ev;

  // Category options
  const catOpts = getAllCategories().map(function(c){
    return '<option value="' + esc(c) + '"' + ((ev&&ev.category===c)||(!ev&&c==='Meeting')?' selected':'') + '>' + esc(c) + '</option>';
  }).join('');

  // Organizer datalist
  const organizers = getEvOrganizers();
  const orgList = organizers.map(function(o){ return '<option value="' + esc(o) + '">'; }).join('');

  // Color swatches
  const swatches = [accent].concat(EV_PRESET_COLORS).map(function(c) {
    const sel = (ev ? ev.eventColor : accent) === c;
    return '<button onclick="setEvColor(\'' + c + '\',this)"'
      + ' style="width:26px;height:26px;border-radius:50%;background:' + c + ';cursor:pointer;'
      + 'border:2px solid ' + (sel?'#334155':'transparent') + ';'
      + 'box-shadow:' + (sel?'0 0 0 2px ' + c + '55':'') + ';transition:all .12s" title="' + c + '"></button>';
  }).join('');

  // Additional dates (stored as [{date, startTime, endTime}])
  const addDates = (ev && ev.additionalDates) ? ev.additionalDates : [];
  let addDatesHtml = '<div id="ev_add_dates">';
  addDates.forEach(function(dt, i) {
    addDatesHtml += evAddDateRow(i, dt.date, dt.startTime, dt.endTime);
  });
  addDatesHtml += '</div>'
    + '<button type="button" class="btn btn-default btn-sm" onclick="evAddDateRow_()" style="margin-top:6px;font-size:12px">'
    + icon('plus') + ' Add Another Date/Time</button>';

  var teamCalChecked = isEdit ? (ev&&ev.syncedApptId ? ' checked' : '') : '';
  var teamCalHint = isEdit
    ? (ev&&ev.syncedApptId ? '\u2713 Currently synced \u2014 uncheck to remove from Team Calendar' : 'Check to add this event to the Team Calendar for scheduling')
    : 'Check to automatically add this event to the Team Calendar for scheduling';

  const body = '<div class="form-grid" style="gap:10px">'
    // ── Section: Event Details
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px">Event Details</div>'
    + '<div class="fg full"><label>Title <span style="color:#DB1924">*</span></label>'
    +   '<input id="ev_title" value="' + esc(ev?ev.title:'') + '" placeholder="Event title"></div>'
    + '<div class="fg full"><label>Details / Description</label>'
    +   '<textarea id="ev_desc" rows="3" style="resize:vertical;font-family:inherit;font-size:13.5px;width:100%" placeholder="Full event description, agenda, notes...">' + esc(ev?ev.description||'':'') + '</textarea></div>'

    // ── Section: Date & Time
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px;margin-top:4px">Date &amp; Time</div>'
    + '<div class="fg full" style="display:flex;align-items:center;gap:10px;padding:2px 0">'
    +   '<input type="checkbox" id="ev_allday" ' + (ev&&ev.isAllDay?'checked':'') + ' onchange="evToggleAllDay(this.checked)" style="width:15px;height:15px;cursor:pointer;accent-color:' + accent + '">'
    +   '<label for="ev_allday" style="font-size:13.5px;cursor:pointer;user-select:none">All Day Event</label>'
    + '</div>'
    + '<div class="fg"><label>Start Date</label>'
    +   '<input id="ev_start_date" type="date"'
    +   ' value="' + esc(ev&&ev.startDateTime ? ev.startDateTime.substring(0,10) : (evPrefilledDate||'')) + '"'
    +   ' oninput="evCombineDateTime(\'ev_start\',\'ev_start_date\',\'ev_start_time\')"></div>'
    + '<div class="fg ev-time-field" style="' + (ev&&ev.isAllDay?'display:none':'') + '"><label>Start Time</label>'
    +   '<input id="ev_start_time" type="time"'
    +   ' value="' + esc(ev&&ev.startDateTime&&!ev.isAllDay ? ev.startDateTime.substring(11,16) : '') + '"'
    +   ' oninput="evCombineDateTime(\'ev_start\',\'ev_start_date\',\'ev_start_time\')"></div>'
    + '<input type="hidden" id="ev_start" value="' + esc(ev&&ev.startDateTime ? ev.startDateTime.substring(0,ev.isAllDay?10:16) : (evPrefilledDate||'')) + '">'
    + '<div class="fg"><label>End Date</label>'
    +   '<input id="ev_end_date" type="date"'
    +   ' value="' + esc(ev&&ev.endDateTime ? ev.endDateTime.substring(0,10) : (evPrefilledDate||'')) + '"'
    +   ' oninput="evCombineDateTime(\'ev_end\',\'ev_end_date\',\'ev_end_time\')"></div>'
    + '<div class="fg ev-time-field" style="' + (ev&&ev.isAllDay?'display:none':'') + '"><label>End Time</label>'
    +   '<input id="ev_end_time" type="time"'
    +   ' value="' + esc(ev&&ev.endDateTime&&!ev.isAllDay ? ev.endDateTime.substring(11,16) : '') + '"'
    +   ' oninput="evCombineDateTime(\'ev_end\',\'ev_end_date\',\'ev_end_time\')"></div>'
    + '<input type="hidden" id="ev_end" value="' + esc(ev&&ev.endDateTime ? ev.endDateTime.substring(0,ev.isAllDay?10:16) : (evPrefilledDate||'')) + '">'
    + '<div class="fg full">' + addDatesHtml + '</div>'

    // ── Section: Location
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px;margin-top:4px">Location</div>'
    + (function(){
        var locs = getEvLocations();
        if (!locs.length) return '';
        var opts = '<option value="">— Pick a saved location —</option>'
          + locs.map(function(l,i){ return '<option value="' + i + '">' + esc(l.name) + (l.city?', '+esc(l.city):'') + '</option>'; }).join('');
        return '<div class="fg full"><label>Saved Location</label>'
          + '<select class="input" onchange="if(this.value!==\'\')evApplySavedLocation(parseInt(this.value));this.value=\'\'">' + opts + '</select></div>';
      })()
    + '<div class="fg full"><label>Venue / Location Name</label>'
    +   '<input id="ev_loc" value="' + esc(ev?ev.location||'':'') + '" placeholder="Convention center, hotel, Zoom, etc."></div>'
    + '<div class="fg full"><label>Address</label>'
    +   '<input id="ev_address" value="' + esc(ev?ev.address||'':'') + '" placeholder="Street address"></div>'
    + '<input type="hidden" id="ev_city" value="' + esc(ev?ev.city||'':'') + '">'
    + '<input type="hidden" id="ev_state" value="' + esc(ev?ev.state||'TX':'TX') + '">'
    + '<input type="hidden" id="ev_zip" value="' + esc(ev?ev.zip||'':'') + '">'
    + '<div class="fg full" style="display:flex;gap:8px">'
    + '<button type="button" class="btn btn-default btn-sm" style="gap:5px;color:#0d9488;border-color:#99f6e4" onclick="verifyAddressFields(\'ev_address\',\'ev_loc\',\'ev_city\',\'ev_state\',\'ev_zip\',function(a){var s=document.getElementById(\'ev_address\');if(s)s.value=a.streetAddress||s.value;var c=document.getElementById(\'ev_city\');if(c)c.value=a.city||c.value;var st=document.getElementById(\'ev_state\');if(st)st.value=a.state||st.value;var z=document.getElementById(\'ev_zip\');if(z)z.value=a.ZIPCode||z.value;})">' + icon('map-pin') + ' Verify Address</button>'
    + '<button type="button" class="btn btn-default btn-sm" style="gap:5px" onclick="lookupZip(\'ev_address\',\'ev_city\',\'ev_state\',\'ev_zip\')">' + icon('search') + ' ZIP Lookup</button>'
    + '</div>'

    // ── Section: Registration & Pricing
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px;margin-top:4px">Registration &amp; Pricing</div>'
    + '<div class="fg full"><label>Website / Registration URL</label>'
    +   '<input id="ev_regurl" type="url" value="' + esc(ev?ev.registrationUrl||'':'') + '" placeholder="https://..."></div>'
    + '<div class="fg"><label>Member / Subscriber Price</label>'
    +   '<input id="ev_mprice" type="number" min="0" step="0.01" value="' + esc(ev&&ev.memberPrice!=null?ev.memberPrice:'') + '" placeholder="0.00"></div>'
    + '<div class="fg"><label>Non-Member Price</label>'
    +   '<input id="ev_nmprice" type="number" min="0" step="0.01" value="' + esc(ev&&ev.nonMemberPrice!=null?ev.nonMemberPrice:'') + '" placeholder="0.00"></div>'
    + '<div class="fg"><label>Course Number</label>'
    +   '<input id="ev_course" value="' + esc(ev?ev.courseNumber||'':'') + '" placeholder="Course #"></div>'
    + '<div class="fg"><label>TREC License Number</label>'
    +   '<input id="ev_trec" value="' + esc(ev?ev.trecLicense||'':'') + '" placeholder="TREC #"></div>'

    // ── Section: Classification
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px;margin-top:4px">Classification</div>'
    + '<div class="fg"><label>Category</label>'
    +   '<select id="ev_cat" class="input"><option value="">— None —</option>' + catOpts + '</select>'
    +   '<input id="ev_cat_new" placeholder="Or type new category..." style="margin-top:5px;font-size:12.5px" oninput="if(this.value)document.getElementById(\'ev_cat\').value=\'\'"></div>'
    + '<div class="fg"><label>Organizer</label>'
    +   '<datalist id="ev_org_list">' + orgList + '</datalist>'
    +   '<input id="ev_org" value="' + esc(ev?ev.organizer||'':'') + '" list="ev_org_list" placeholder="Organizer name"></div>'
    + '<div class="fg full"><label>Tags <span style="font-size:11px;font-weight:400;color:var(--text3)">(comma-separated)</span></label>'
    +   '<input id="ev_tags" value="' + esc(ev?ev.tags||'':'') + '" placeholder="e.g. CE Course, Networking, Open House">'
    + '</div>'
    + '<div class="fg full" style="display:flex;align-items:center;gap:10px;padding:4px 0;background:rgba(2,29,64,.07);border:1px solid rgba(2,29,64,.2);border-radius:var(--r);padding:8px 12px;margin-top:2px">'
    +   '<input type="checkbox" id="ev_team_cal" style="width:16px;height:16px;cursor:pointer;accent-color:' + accent + ';flex-shrink:0"'
    +   teamCalChecked
    +   '>'
    +   '<div style="line-height:1.35">'
    +   '<label for="ev_team_cal" style="font-size:13.5px;font-weight:600;cursor:pointer;user-select:none;color:var(--text)">Push to Team Calendar</label>'
    +   '<div style="font-size:11.5px;color:var(--text2);margin-top:1px">'
    +   teamCalHint
    +   '</div>'
    +   '</div>'
    + '</div>'

    // ── Section: Appearance
    + '<div class="fg full" style="font-size:11.5px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:4px;margin-top:4px">Appearance</div>'
    + '<div class="fg full"><label>Event Color</label>'
    +   '<div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:4px">'
    +   swatches
    +   '<input id="ev_hex" type="text" value="' + esc(ev?ev.eventColor||accent:accent) + '" placeholder="#hex" maxlength="7"'
    +     ' style="width:80px;height:28px;padding:4px 8px;font-size:12px;border:1px solid var(--border2);border-radius:var(--r);font-family:monospace" oninput="evHexChanged(this.value)">'
    +   '<div id="ev_color_preview" style="width:26px;height:26px;border-radius:50%;border:1px solid var(--border);background:' + esc(ev?ev.eventColor||accent:accent) + '"></div>'
    +   '</div>'
    +   '<input type="hidden" id="ev_color" value="' + esc(ev?ev.eventColor||accent:accent) + '">'
    + '</div>'

    // ── Delete (edit mode)
    + (isEdit ? '<div class="fg full" style="border-top:1px solid var(--border);padding-top:10px;margin-top:4px">'
      + '<div id="ev_delete_wrap"><button class="btn btn-sm" onclick="evConfirmDelete()"'
      + ' style="background:color-mix(in srgb,var(--destructive) 10%,transparent);color:#DB1924;border:1px solid color-mix(in srgb,var(--destructive) 30%,transparent)">'
      + icon('trash') + ' Delete Event</button></div>'
      + '<div id="ev_confirm_del" style="display:none;align-items:center;gap:8px">'
      + '<span style="font-size:12.5px;color:#DB1924;font-weight:600">Confirm delete?</span>'
      + '<button class="btn btn-destructive btn-sm" onclick="confirmDeleteEv(\'' + (ev?ev.id:'') + '\')">Yes, Delete</button>'
      + '<button class="btn btn-default btn-sm" onclick="evCancelDelete()">Cancel</button>'
      + '</div></div>' : '')
    + '</div>';

  openModal(
    '<div class="modal-title">' + icon('calendar') + ' ' + (isEdit ? 'Edit Event' : 'New Event') + '</div>',
    body,
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-accent" onclick="saveEv(\'' + (ev?ev.id:'') + '\')" style="background:' + accent + ';color:#fff;font-weight:600">'
    + (isEdit ? 'Save Changes' : 'Create Event') + '</button>',
    true
  );
}

// ── Additional date rows ──────────────────────────────────────
function evAddDateRow(idx, date, startTime, endTime) {
  return '<div id="ev_adr_' + idx + '" style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap">'
    + '<input type="date" id="ev_adr_date_' + idx + '" value="' + esc(date||'') + '" style="flex:2;min-width:120px">'
    + '<input type="time" id="ev_adr_st_' + idx + '"   value="' + esc(startTime||'') + '" style="flex:1;min-width:90px" placeholder="Start">'
    + '<input type="time" id="ev_adr_et_' + idx + '"   value="' + esc(endTime||'') + '" style="flex:1;min-width:90px" placeholder="End">'
    + '<button type="button" onclick="evRemoveDateRow(' + idx + ')" class="btn btn-ghost btn-icon-sm" style="color:#DB1924">' + icon('trash') + '</button>'
    + '</div>';
}

let _evAdrCount = 0;
function evAddDateRow_() {
  const container = document.getElementById('ev_add_dates');
  if (!container) return;
  _evAdrCount++;
  const idx = Date.now();
  const div = document.createElement('div');
  div.innerHTML = evAddDateRow('x' + idx, '', '', '');
  container.appendChild(div.firstChild);
}
function evRemoveDateRow(idx) {
  const el = document.getElementById('ev_adr_' + idx);
  if (el) el.remove();
}

// ── Collect additional dates from DOM ──────────────────────────
function collectAddDates() {
  const rows = [];
  document.querySelectorAll('[id^="ev_adr_date_"]').forEach(function(el) {
    const suffix = el.id.replace('ev_adr_date_','');
    const date   = el.value;
    const st     = (document.getElementById('ev_adr_st_' + suffix)||{}).value || '';
    const et     = (document.getElementById('ev_adr_et_' + suffix)||{}).value || '';
    if (date) rows.push({date:date, startTime:st, endTime:et});
  });
  return rows;
}

function evToggleAllDay(checked) {
  // Show/hide time fields
  document.querySelectorAll('.ev-time-field').forEach(function(el) {
    el.style.display = checked ? 'none' : '';
  });
  // If switching to all-day, strip time portion from hidden inputs
  if (checked) {
    var s = document.getElementById('ev_start_date');
    var e = document.getElementById('ev_end_date');
    if (s) document.getElementById('ev_start').value = s.value;
    if (e) document.getElementById('ev_end').value   = e.value;
  } else {
    evCombineDateTime('ev_start','ev_start_date','ev_start_time');
    evCombineDateTime('ev_end','ev_end_date','ev_end_time');
  }
}

function evCombineDateTime(hiddenId, dateId, timeId) {
  var dateEl = document.getElementById(dateId);
  var timeEl = document.getElementById(timeId);
  var hidEl  = document.getElementById(hiddenId);
  if (!dateEl || !hidEl) return;
  var d = dateEl.value;
  var t = timeEl ? timeEl.value : '';
  hidEl.value = d ? (t ? d + 'T' + t : d) : '';
}

function setEvColor(c, btn) {
  document.getElementById('ev_color').value = c;
  document.getElementById('ev_hex').value   = c;
  document.getElementById('ev_color_preview').style.background = c;
  document.querySelectorAll('[onclick^="setEvColor"]').forEach(function(b) {
    b.style.borderColor = 'transparent'; b.style.boxShadow = '';
  });
  btn.style.borderColor = '#334155';
  btn.style.boxShadow   = '0 0 0 2px ' + c + '55';
}
function evHexChanged(v) {
  document.getElementById('ev_color').value = v;
  if (/^#[0-9A-Fa-f]{6}$/.test(v)) document.getElementById('ev_color_preview').style.background = v;
}
function evConfirmDelete() {
  document.getElementById('ev_delete_wrap').style.display = 'none';
  document.getElementById('ev_confirm_del').style.display = 'flex';
}
function evCancelDelete() {
  document.getElementById('ev_confirm_del').style.display = 'none';
  document.getElementById('ev_delete_wrap').style.display = 'block';
}

// ── Save ──────────────────────────────────────────────────────
function saveEv(id) {
  const g = function(eid){ const el=document.getElementById(eid); return el ? el.value.trim() : ''; };
  const title = g('ev_title');
  if (!title) { toast('Title is required','err'); return; }

  const allDay = document.getElementById('ev_allday') && document.getElementById('ev_allday').checked;
  const toISO  = function(v) {
    if (!v) return '';
    if (allDay) return v.length===10 ? v+'T00:00:00' : v;
    return v.length===16 ? v+':00' : v;
  };

  // Category: prefer new text field, fall back to select
  const catNew = g('ev_cat_new');
  const cat    = catNew || g('ev_cat');
  if (catNew) saveEvCategory(catNew);

  // Organizer
  const org = g('ev_org');
  if (org) saveEvOrganizer(org);

  // Tags
  const tags = g('ev_tags');

  // Team Calendar checkbox
  var teamCalCb = document.getElementById('ev_team_cal');
  var syncToTeam = teamCalCb ? teamCalCb.checked : false;

  const data = {
    title:           title,
    description:     g('ev_desc'),
    isAllDay:        !!allDay,
    startDateTime:   toISO(g('ev_start')),
    endDateTime:     toISO(g('ev_end')),
    additionalDates: collectAddDates(),
    location:        g('ev_loc'),
    address:         g('ev_address'),
    city:            g('ev_city'),
    state:           g('ev_state'),
    zip:             g('ev_zip'),
    registrationUrl: g('ev_regurl'),
    memberPrice:     g('ev_mprice'),
    nonMemberPrice:  g('ev_nmprice'),
    courseNumber:    g('ev_course'),
    trecLicense:     g('ev_trec'),
    category:        cat,
    organizer:       org,
    tags:            tags,
    eventColor:      g('ev_color') || ACCENT[co],
  };

  var savedEv;
  if (id) {
    const ev = getEvents().find(function(e){return e.id===id;});
    if (ev) {
      // Preserve existing syncedApptId if re-saving
      if (ev.syncedApptId) data.syncedApptId = ev.syncedApptId;
      Object.assign(ev, data, {updatedAt: new Date().toISOString()});
      savedEv = ev;
    }
    toast('Event updated','ok');
  } else {
    // Check for duplicate (same title + same date)
    var dupEv = getEvents().find(function(e) {
      var titleMatch = (e.title||'').toLowerCase().trim() === (data.title||'').toLowerCase().trim();
      var dateMatch  = data.startDateTime && e.startDateTime &&
                       data.startDateTime.slice(0,10) === e.startDateTime.slice(0,10);
      return titleMatch && dateMatch;
    });
    if (dupEv && !confirm('Duplicate: ' + dupEv.title + ' (' + (dupEv.startDateTime||'').slice(0,10) + ') already exists. Add anyway?')) return;
    var newEv = Object.assign({id: Date.now().toString()+Math.random().toString(36).slice(2), createdAt: new Date().toISOString()}, data);
    getEvents().push(newEv);
    savedEv = newEv;
    toast('Event created','ok');
  }

  // ── Sync to Team Calendar (appointments) ──────────────────
  if (savedEv) {
    if (syncToTeam) {
      evSyncToTeamCalendar(savedEv);
    } else if (savedEv.syncedApptId) {
      // Tag removed — remove from Team Calendar too
      DATA[co].appointments = DATA[co].appointments.filter(function(a){ return a.id !== savedEv.syncedApptId; });
      delete savedEv.syncedApptId;
      toast('Removed from Team Calendar','ok');
    }
  }

  persist(); closeModal(); renderEvents();
  if (currentPage === 'calendarly') renderCalendarly();
}
function evSyncToTeamCalendar(ev, silent) {
  if (!DATA[co].appointments) DATA[co].appointments = [];
  var apptData = {
    title:      ev.title,
    client:     ev.organizer || '',
    agentEmail: '',
    dt:         ev.startDateTime || '',
    endDt:      ev.endDateTime   || '',
    location:   [ev.location, ev.address, ev.city, ev.state].filter(Boolean).join(', '),
    notes:      ev.description || '',
    sourceEventId: ev.id,
    updatedAt:  new Date().toISOString(),
  };

  if (ev.syncedApptId) {
    var existing = DATA[co].appointments.find(function(a){ return a.id === ev.syncedApptId; });
    if (existing) {
      Object.assign(existing, apptData);
      if (!silent) toast('Team Calendar synced ✓','ok');
      return;
    }
  }

  // Create new appointment
  apptData.id        = 'ev_sync_' + ev.id;
  apptData.createdAt = new Date().toISOString();
  ev.syncedApptId    = apptData.id;
  DATA[co].appointments.unshift(apptData);
  if (!silent) toast('Added to Team Calendar ✓','ok');
}

function deleteEv(id) {
  openModal(
    '<div class="modal-title">' + icon('trash') + ' Delete Event</div>',
    '<p style="color:var(--text2)">Delete this event? This cannot be undone.</p>',
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-destructive" onclick="confirmDeleteEv(\'' + id + '\')">Delete</button>'
  );
}
function confirmDeleteEv(id) {
  requireDeleteAuth(function(){
    if (!id) { closeModal(); return; }
    var ev = eventsData[co] && eventsData[co].find(function(e){return e.id===id;});
    if (ev && ev.syncedApptId) {
      DATA[co].appointments = DATA[co].appointments.filter(function(a){ return a.id !== ev.syncedApptId; });
    }
    eventsData[co] = eventsData[co].filter(function(e){return e.id!==id;});
    persist(); closeModal(); renderEvents(); toast('Event deleted','ok');
  }, 'delete this event');
}

// ── EXPORT ───────────────────────────────────────────────────
function toggleEvExport() {
  const m = document.getElementById('evExportMenu');
  if (m) m.style.display = m.style.display==='none' ? 'block' : 'none';
}
document.addEventListener('click', function(e) {
  if (!e.target.closest('#evExportTrigger')) {
    const m = document.getElementById('evExportMenu');
    if (m) m.style.display = 'none';
  }
});

function exportEvCsv() {
  const evs = getEvents();
  if (!evs.length) { toast('No events to export','err'); return; }
  function q(v) { const s=(v==null)?'':String(v); return (s.includes(',')||s.includes('"')||s.includes('\n'))?'"'+s.replace(/"/g,'""')+'"':s; }
  const hdr = ['title','description','startDateTime','endDateTime','location','address','city','state','zip','memberPrice','nonMemberPrice','courseNumber','trecLicense','category','organizer','isAllDay','eventColor'];
  const rows = evs.map(function(e){
    return [e.title,e.description,e.startDateTime,e.endDateTime,e.location,e.address,e.city,e.state,e.zip,
      e.memberPrice,e.nonMemberPrice,e.courseNumber,e.trecLicense,e.category,e.organizer,
      e.isAllDay?'true':'false',e.eventColor].map(q).join(',');
  });
  const a = document.createElement('a');
  a.href     = 'data:text/csv;charset=utf-8,' + encodeURIComponent([hdr.join(',')].concat(rows).join('\n'));
  a.download = 'events-' + co + '-' + new Date().toISOString().split('T')[0] + '.csv';
  a.click();
  toast('Exported ' + evs.length + ' events as CSV','ok');
  toggleEvExport();
}

function exportEvIcs() {
  const evs = getEvents();
  if (!evs.length) { toast('No events to export','err'); return; }
  function icsEsc(v) { return (v||'').replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\n/g,'\\n'); }
  function icsDate(s, allDay) {
    if (!s) return '';
    try {
      const d = new Date(s);
      if (allDay) return ''+d.getFullYear()+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0');
      return ''+d.getUTCFullYear()+String(d.getUTCMonth()+1).padStart(2,'0')+String(d.getUTCDate()).padStart(2,'0')
        +'T'+String(d.getUTCHours()).padStart(2,'0')+String(d.getUTCMinutes()).padStart(2,'0')+String(d.getUTCSeconds()).padStart(2,'0')+'Z';
    } catch { return ''; }
  }
  function fold(line) {
    if (line.length<=75) return line;
    let out=line.slice(0,75); let i=75;
    while(i<line.length){out+='\r\n '+line.slice(i,i+74);i+=74;}
    return out;
  }
  const lines = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//PressBook CRM//Events//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH'];
  evs.forEach(function(ev, idx) {
    const allDay = !!ev.isAllDay;
    lines.push('BEGIN:VEVENT');
    lines.push(fold('UID:ev-'+idx+'-'+Date.now()+'@pressbook'));
    const ds = icsDate(ev.startDateTime,allDay); if(ds) lines.push(fold(allDay?'DTSTART;VALUE=DATE:'+ds:'DTSTART:'+ds));
    const de = icsDate(ev.endDateTime,allDay);   if(de) lines.push(fold(allDay?'DTEND;VALUE=DATE:'+de:'DTEND:'+de));
    lines.push(fold('SUMMARY:'+icsEsc(ev.title||'')));
    if(ev.description) lines.push(fold('DESCRIPTION:'+icsEsc(ev.description)));
    const loc = [ev.location,ev.address,ev.city,ev.state,ev.zip].filter(Boolean).join(', ');
    if(loc) lines.push(fold('LOCATION:'+icsEsc(loc)));
    if(ev.category) lines.push(fold('CATEGORIES:'+icsEsc(ev.category)));
    if(ev.organizer) lines.push(fold('ORGANIZER;CN="'+icsEsc(ev.organizer)+'":MAILTO:noreply@pressbook'));
    if(ev.courseNumber) lines.push(fold('X-COURSE-NUMBER:'+icsEsc(ev.courseNumber)));
    if(ev.trecLicense)  lines.push(fold('X-TREC-LICENSE:'+icsEsc(ev.trecLicense)));
    if(ev.memberPrice)    lines.push(fold('X-MEMBER-PRICE:'+ev.memberPrice));
    if(ev.nonMemberPrice) lines.push(fold('X-NONMEMBER-PRICE:'+ev.nonMemberPrice));
    lines.push('END:VEVENT');
  });
  lines.push('END:VCALENDAR');
  const a = document.createElement('a');
  a.href     = 'data:text/calendar;charset=utf-8,' + encodeURIComponent(lines.join('\r\n'));
  a.download = 'events-' + co + '-' + new Date().toISOString().split('T')[0] + '.ics';
  a.click();
  toast('Exported ' + evs.length + ' events as ICS','ok');
  toggleEvExport();
}

// ── IMPORT WIZARD (3-step) ────────────────────────────────────
function openEvImport() {
  window._imp = {step:1, tab:'csv', parsed:[], headers:[], colMap:{}, mode:'add', fileName:''};
  openModal('<div class="modal-title">' + icon('upload') + ' Import Events</div>', impStep1Html(), impStep1Foot(), true);
  requestAnimationFrame(function(){ requestAnimationFrame(impWireDrop); });
}

function impStepBar(active) {
  const accent = ACCENT[co];
  return '<div style="display:flex;align-items:center;">'
    + ['Upload','Map Columns','Options'].map(function(l,i){
        const done=i<active, cur=i===active;
        return '<div style="display:flex;align-items:center;flex:1;min-width:0">'
          + '<div style="display:flex;flex-direction:column;align-items:center;gap:3px;flex:1">'
          + '<div style="width:26px;height:26px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:700;flex-shrink:0;background:'+(done||cur?accent:'var(--border2)')+';color:'+(done||cur?'#fff':'var(--text3)')+'">'+(done?'✓':i+1)+'</div>'
          + '<div style="font-size:11px;font-weight:'+(cur?700:400)+';color:'+(cur?'var(--text)':done?'var(--text2)':'var(--text3)')+';white-space:nowrap">'+l+'</div></div>'
          + (i<2?'<div style="height:2px;background:'+(done?accent:'var(--border2)')+';flex:1;margin-bottom:16px;min-width:8px"></div>':'')
          + '</div>';
      }).join('')
    + '</div>';
}

function impStep1Html() {
  const accent = ACCENT[co];
  return impStepBar(0)
    + '<div style="display:flex;border:1px solid var(--border);border-radius:var(--r);overflow:hidden;margin-bottom:14px">'
    + '<button id="imp_tab_csv" onclick="impSwitchTab(\'csv\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:13px;font-weight:600;background:'+accent+';color:#fff;display:flex;align-items:center;justify-content:center;gap:5px">'+icon('file-text')+' CSV</button>'
    + '<button id="imp_tab_ics" onclick="impSwitchTab(\'ics\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:13px;font-weight:600;background:var(--muted);color:var(--text2);display:flex;align-items:center;justify-content:center;gap:5px">'+icon('calendar')+' ICS</button>'
    + '<button id="imp_tab_paste" onclick="impSwitchTab(\'paste\')" style="flex:1;padding:8px;border:none;cursor:pointer;font-size:13px;font-weight:600;background:var(--muted);color:var(--text2);display:flex;align-items:center;justify-content:center;gap:5px">'+icon('clipboard')+' Paste</button>'
    + '</div>'
    + '<div id="imp_csv_hint" style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">'
    + '<p style="font-size:13px;color:var(--text2)">Upload CSV. Required column: <strong>title</strong>.</p>'
    + '<button class="btn btn-ghost btn-sm" onclick="impDownloadTemplate()">↓ Template</button></div>'
    + '<div id="imp_ics_hint" style="display:none;margin-bottom:10px"><p style="font-size:13px;color:var(--text2)">Upload ICS from Google Calendar, Outlook, or Apple Calendar.</p></div>'
    + '<div id="imp_paste_hint" style="display:none;margin-bottom:10px"><p style="font-size:13px;color:var(--text2)">Paste CSV text directly. First row must be headers including <strong>title</strong>.</p></div>'
    + '<div id="imp_paste_area" style="display:none;margin-bottom:10px">'
    + '<textarea id="imp_paste_input" rows="8" placeholder="title,startDate,endDate,location,category&#10;Event Name,2025-01-15,2025-01-15,Austin TX,Real Estate" style="width:100%;padding:10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:12.5px;font-family:monospace;resize:vertical;box-sizing:border-box" oninput="impPasteProcess(this.value)"></textarea>'
    + '</div>'
    + '<div id="imp_drop_zone" style="border:2px dashed var(--border2);border-radius:var(--r);padding:40px 20px;text-align:center;cursor:pointer;transition:all .15s">'
    + '<svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="var(--text3)" stroke-width="1.5" style="margin:0 auto 10px;display:block;pointer-events:none"><polyline points="16 16 12 12 8 16"/><line x1="12" y1="12" x2="12" y2="21"/><path d="M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.29"/></svg>'
    + '<div id="imp_drop_label" style="font-size:14px;font-weight:600;color:var(--text);pointer-events:none">Drag &amp; drop your file here</div>'
    + '<div style="font-size:12px;color:var(--text3);margin-top:5px;pointer-events:none">or <span style="color:'+accent+';font-weight:600;text-decoration:underline" id="imp_browse_link">click to browse</span></div>'
    + '</div>'
    + '<input type="file" id="imp_file_input" accept=".csv,.ics" style="position:absolute;width:1px;height:1px;opacity:0;pointer-events:none" tabindex="-1">'
    + '<div id="imp_file_status" style="display:none;margin-top:10px;align-items:center;gap:8px;font-size:13px">'
    + '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#16a34a" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg>'
    + '<span id="imp_file_name" style="font-weight:600;color:var(--text)"></span>'
    + '<span id="imp_file_count" style="color:'+accent+'"></span>'
    + '<button onclick="impClearFile()" style="background:none;border:none;cursor:pointer;color:var(--text3);font-size:11px;margin-left:4px">✕ Clear</button></div>'
    + '<div id="imp_file_err" style="display:none;margin-top:8px;font-size:13px;color:#DB1924;font-weight:500"></div>';
}
function impStep1Foot() {
  return '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-accent" id="imp_next1" onclick="impGoStep2()" disabled style="background:var(--accent);color:#fff;font-weight:600">Next: Map Columns →</button>';
}
function impWireDrop() {
  const zone=document.getElementById('imp_drop_zone'), browse=document.getElementById('imp_browse_link'), input=document.getElementById('imp_file_input');
  if(!zone||!input) return;
  if(browse) browse.addEventListener('click',function(e){e.stopPropagation();input.click();});
  zone.addEventListener('click',function(e){e.stopPropagation();input.click();});
  zone.addEventListener('dragenter',function(e){e.preventDefault();e.stopPropagation();impDropHover(true);});
  zone.addEventListener('dragover', function(e){e.preventDefault();e.stopPropagation();impDropHover(true);});
  zone.addEventListener('dragleave',function(e){e.preventDefault();e.stopPropagation();impDropHover(false);});
  zone.addEventListener('drop',function(e){e.preventDefault();e.stopPropagation();impDropHover(false);var f=e.dataTransfer&&e.dataTransfer.files&&e.dataTransfer.files[0];if(f)impProcessFile(f);});
  input.addEventListener('change',function(){if(input.files[0])impProcessFile(input.files[0]);input.value='';});
}
function impDropHover(on) {
  const zone=document.getElementById('imp_drop_zone'); if(!zone) return;
  zone.style.borderColor=on?ACCENT[co]:'var(--border2)';
  zone.style.background=on?'color-mix(in srgb,'+ACCENT[co]+' 5%,transparent)':'';
}
function impSwitchTab(tab) {
  const imp=window._imp; imp.tab=tab; imp.parsed=[]; imp.headers=[]; impClearFile();
  const accent=ACCENT[co];
  const base='flex:1;padding:8px;border:none;cursor:pointer;font-size:13px;font-weight:600;display:flex;align-items:center;justify-content:center;gap:5px';
  const cv=document.getElementById('imp_tab_csv'); if(cv) cv.style.cssText=base+';background:'+(tab==='csv'?accent:'var(--muted)')+';color:'+(tab==='csv'?'#fff':'var(--text2)');
  const iv=document.getElementById('imp_tab_ics'); if(iv) iv.style.cssText=base+';background:'+(tab==='ics'?accent:'var(--muted)')+';color:'+(tab==='ics'?'#fff':'var(--text2)');
  const ch=document.getElementById('imp_csv_hint'); if(ch) ch.style.display=tab==='csv'?'flex':'none';
  const ih=document.getElementById('imp_ics_hint'); if(ih) ih.style.display=tab==='ics'?'block':'none';
  const fi=document.getElementById('imp_file_input'); if(fi) fi.accept=tab==='csv'?'.csv':'.ics';
  const pv=document.getElementById('imp_tab_paste'); if(pv) pv.style.cssText=base+';background:'+(tab==='paste'?accent:'var(--muted)')+';color:'+(tab==='paste'?'#fff':'var(--text2)');
  const ph=document.getElementById('imp_paste_hint'); if(ph) ph.style.display=tab==='paste'?'block':'none';
  const pa=document.getElementById('imp_paste_area'); if(pa) pa.style.display=tab==='paste'?'block':'none';
  const dz=document.getElementById('imp_drop_zone'); if(dz) dz.style.display=tab==='paste'?'none':'';
  if(tab==='paste'){var pi=document.getElementById('imp_paste_input');if(pi)pi.value='';}
}
function impClearFile() {
  const imp=window._imp; imp.parsed=[]; imp.headers=[]; imp.fileName='';
  const st=document.getElementById('imp_file_status'); if(st) st.style.display='none';
  const er=document.getElementById('imp_file_err');   if(er) er.style.display='none';
  const btn=document.getElementById('imp_next1');     if(btn) btn.disabled=true;
  const lbl=document.getElementById('imp_drop_label'); if(lbl) lbl.textContent='Drag & drop your file here';
  impDropHover(false);
}
function impPasteProcess(text) {
  const imp = window._imp;
  if (!text.trim()) {
    imp.parsed = []; imp.headers = [];
    const btn = document.getElementById('imp_next1'); if(btn) btn.disabled = true;
    return;
  }
  try {
    const parsed = impParseCsv(text.trim());
    if (!parsed || !parsed.rows || !parsed.rows.length) {
      const btn = document.getElementById('imp_next1'); if(btn) btn.disabled = true;
      return;
    }
    imp.headers = parsed.headers;
    imp.parsed  = parsed.rows;
    imp.fileName = 'pasted-csv';
    const btn = document.getElementById('imp_next1');
    if (btn) { btn.disabled = false; }
    const st = document.getElementById('imp_file_status');
    if (st) {
      st.style.display = 'flex';
      const fn = document.getElementById('imp_file_name'); if(fn) fn.textContent = 'Pasted CSV';
      const fc = document.getElementById('imp_file_count'); if(fc) fc.textContent = '· ' + imp.parsed.length + ' row' + (imp.parsed.length !== 1 ? 's' : '') + ' ready';
    }
  } catch(e) {
    const btn = document.getElementById('imp_next1'); if(btn) btn.disabled = true;
  }
}

function impProcessFile(file) {
  const imp=window._imp; imp.fileName=file.name;
  const ext = file.name.split(".").pop().toLowerCase();
  if (imp.tab==="csv" && ext !== "csv") {
    const err=document.getElementById("imp_file_err"); if(err){err.textContent="Please upload a CSV file (.csv only)";err.style.display="block";} return;
  }
  if (imp.tab==="ics" && ext !== "ics") {
    const err=document.getElementById("imp_file_err"); if(err){err.textContent="Please upload an ICS file (.ics only)";err.style.display="block";} return;
  }
  const reader=new FileReader();
  reader.onload=function(ev){
    try {
      const text=ev.target.result; let rows,hdrs;
      if(imp.tab==='ics'){
        rows=impParseIcs(text);
        hdrs=['title','description','startDateTime','endDateTime','location','category','organizer'];
      } else {
        const parsed = impParseCsv(text);
        hdrs  = parsed.headers;
        rows  = parsed.rows;
      }
      imp.headers=hdrs; imp.parsed=rows;
      const err=document.getElementById('imp_file_err');
      if(!rows.length){if(err){err.textContent='No valid rows found.';err.style.display='block';}return;}
      if(err) err.style.display='none';
      const st=document.getElementById('imp_file_status'); if(st) st.style.display='flex';
      const fn=document.getElementById('imp_file_name');   if(fn) fn.textContent=file.name;
      const fc=document.getElementById('imp_file_count');  if(fc) fc.textContent='· '+rows.length+' row'+(rows.length!==1?'s':'')+' ready';
      const lbl=document.getElementById('imp_drop_label'); if(lbl) lbl.textContent=file.name;
      document.getElementById('imp_drop_zone').style.borderColor=ACCENT[co];
      const btn=document.getElementById('imp_next1'); if(btn) btn.disabled=false;
    } catch(ex) {
      const err=document.getElementById('imp_file_err');
      if(err){err.textContent='Failed to parse file: '+ex.message;err.style.display='block';}
    }
  };
  reader.readAsText(file);
}

// Full RFC 4180-compliant CSV parser — handles quoted fields with embedded newlines/commas
function impParseCsv(text) {
  // Normalize line endings
  const str = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  // Strip BOM if present
  const src = str.charCodeAt(0) === 0xFEFF ? str.slice(1) : str;

  const records = [];
  let i = 0, len = src.length;

  function parseField() {
    if (i >= len) return '';
    if (src[i] === '"') {
      // Quoted field
      i++; // skip opening quote
      let val = '';
      while (i < len) {
        if (src[i] === '"') {
          if (src[i+1] === '"') { val += '"'; i += 2; } // escaped quote
          else { i++; break; }                          // closing quote
        } else {
          val += src[i++];
        }
      }
      return val;
    } else {
      // Unquoted field — read until comma or newline
      let val = '';
      while (i < len && src[i] !== ',' && src[i] !== '\n') {
        val += src[i++];
      }
      return val.trim();
    }
  }

  function parseRecord() {
    const fields = [];
    while (i < len && src[i] !== '\n') {
      fields.push(parseField());
      if (i < len && src[i] === ',') i++; // skip comma
      else break;
    }
    if (i < len && src[i] === '\n') i++; // skip newline
    return fields;
  }

  // Parse header row
  const headerFields = parseRecord();
  if (!headerFields.length) return { headers: [], rows: [] };

  // Parse data rows
  while (i < len) {
    // Skip completely blank lines
    const lineStart = i;
    while (i < len && (src[i] === '\n' || src[i] === ' ')) i++;
    if (i >= len) break;
    if (src[i] === '\n') { i++; continue; }
    // Check if this is a blank line
    if (i > lineStart && i < len) { /* already advanced */ }

    const fields = parseRecord();
    if (!fields.length || fields.every(function(f){ return !f; })) continue;

    const obj = {};
    headerFields.forEach(function(h, idx) { obj[h] = fields[idx] || ''; });

    // Must have a non-empty title-equivalent column
    const titleCol = headerFields.find(function(h){
      const n = h.toLowerCase().replace(/[^a-z]/g,'');
      return n === 'title' || n === 'summary' || n === 'subject';
    });
    if (titleCol && !obj[titleCol]) continue;

    records.push(obj);
  }

  return { headers: headerFields, rows: records };
}

function impParseCsvLine(line) {
  const result=[]; let cur=''; let inQ=false;
  for(let i=0;i<line.length;i++){
    const ch=line[i];
    if(ch==='"'){if(inQ&&line[i+1]==='"'){cur+='"';i++;}else inQ=!inQ;}
    else if(ch===','&&!inQ){result.push(cur.trim());cur='';}
    else cur+=ch;
  }
  result.push(cur.trim()); return result;
}
function impParseIcs(text) {
  const unfolded=text.replace(/\r?\n[ \t]/g,'');
  const lines=unfolded.split(/\r?\n/);
  function unescIcs(v){return (v||'').replace(/\\n/g,'\n').replace(/\\,/g,',').replace(/\\;/g,';').replace(/\\\\/g,'\\');}
  function parseDT(val,isDate){
    if(isDate||val.length===8) return val.slice(0,4)+'-'+val.slice(4,6)+'-'+val.slice(6,8);
    try{const y=val.slice(0,4),mo=val.slice(4,6),d=val.slice(6,8),h=val.slice(9,11),mi=val.slice(11,13),s=val.slice(13,15);
      return new Date(y+'-'+mo+'-'+d+'T'+h+':'+mi+':'+s+(val.endsWith('Z')?'Z':'')).toISOString();}catch{return val;}
  }
  const results=[]; let inEvent=false; let cur={};
  lines.forEach(function(rawLine){
    const line=rawLine.trim();
    if(line==='BEGIN:VEVENT'){inEvent=true;cur={};return;}
    if(line==='END:VEVENT'){
      inEvent=false;
      if(cur.title) results.push({title:cur.title,description:cur.description,location:cur.location,
        category:cur.category||'Other',organizer:cur.organizer,isAllDay:!!cur._isDate,
        startDateTime:cur._dtStart?parseDT(cur._dtStart,cur._isDate):undefined,
        endDateTime:cur._dtEnd?parseDT(cur._dtEnd,cur._isEndDate):undefined});
      return;
    }
    if(!inEvent) return;
    const ci=line.indexOf(':'); if(ci===-1) return;
    const pf=line.slice(0,ci),val=line.slice(ci+1);
    const si=pf.indexOf(';');
    const pn=(si===-1?pf:pf.slice(0,si)).toUpperCase();
    const params=si===-1?'':pf.slice(si+1);
    switch(pn){
      case 'SUMMARY':     cur.title=unescIcs(val); break;
      case 'DESCRIPTION': cur.description=unescIcs(val); break;
      case 'LOCATION':    cur.location=unescIcs(val); break;
      case 'CATEGORIES':  cur.category=unescIcs(val.split(',')[0]||''); break;
      case 'ORGANIZER':   cur.organizer=unescIcs(val.replace(/^.*CN=/,'').replace(/^"/,'').replace(/"$/,'')); break;
      case 'DTSTART': cur._isDate=params.includes('VALUE=DATE')||val.length===8; cur._dtStart=val; break;
      case 'DTEND':   cur._isEndDate=params.includes('VALUE=DATE')||val.length===8; cur._dtEnd=val; break;
    }
  });
  return results;
}

const IMP_FIELDS = [
  {key:'title',          label:'Title',           required:true},
  {key:'startDate',      label:'Start Date',      required:false},
  {key:'startTime',      label:'Start Time',      required:false},
  {key:'endDate',        label:'End Date',        required:false},
  {key:'endTime',        label:'End Time',        required:false},
  {key:'description',    label:'Description',     required:false},
  {key:'address',        label:'Address',         required:false},
  {key:'tags',           label:'Tags',            required:false},
  {key:'memberPrice',    label:'Member Price',    required:false},
  {key:'nonMemberPrice', label:'Non-Member Price',required:false},
  {key:'courseNumber',   label:'Course Number',   required:false},
  {key:'trecLicense',    label:'TREC License',    required:false},
  {key:'category',       label:'Category',        required:false},
  {key:'organizer',      label:'Organizer',       required:false},
  {key:'isAllDay',       label:'All Day',         required:false},
  {key:'eventColor',     label:'Event Color',     required:false},
  {key:'registrationUrl', label:'Website / URL',   required:false},
];

function impAutoGuess(hdrs) {
  const norm=function(s){return s.toLowerCase().replace(/[^a-z0-9]/g,'');};
  const aliases = {
    title:       ['title','name','event','subject','summary'],
    startDate:   ['startdate','start date','date','eventdate','event date','begin date','begindate'],
    startTime:   ['starttime','start time','begin time','begintime','time'],
    endDate:     ['enddate','end date','finish date','finishdate'],
    endTime:     ['endtime','end time','finish time','finishtime'],
    description: ['description','details','notes','body','content'],
    address:     ['address','street','streetaddress','venue','place','street address'],
    tags:        ['tags','tag','labels','label','groups'],
    memberPrice:    ['memberprice','member price','price','cost','fee','member fee'],
    nonMemberPrice: ['nonmemberprice','non member price','nonmember','nonmemberfee','guest price','non-member price'],
    courseNumber:   ['coursenumber','course','course number','courseno','course no','course #'],
    trecLicense:    ['trec','treclicense','license','licenseno','trec license','trec#'],
    category:    ['category','cat','type','event type','categories','class type'],
    organizer:   ['organizer','host','presenter','org','organizer name'],
    isAllDay:    ['isallday','allday','all day','full day'],
    eventColor:  ['eventcolor','color','colour','event color'],
  };
  const map={};
  IMP_FIELDS.forEach(function(f){
    const alts = aliases[f.key] || [norm(f.key)];
    const match = hdrs.find(function(h){ return alts.indexOf(norm(h)) !== -1; });
    if (match) map[f.key] = match;
  });
  return map;
}
function impGoStep2() {
  const imp=window._imp; if(!imp.parsed.length){toast('Upload a file first','err');return;}
  imp.step=2;
  // Always re-run auto-guess so corrected aliases take effect
  imp.colMap = impAutoGuess(imp.headers);
  const accent=ACCENT[co];
  document.getElementById('modalHead').innerHTML='<div class="modal-title">'+icon('upload')+' Import Events</div>';
  document.getElementById('modalBody').innerHTML=impStep2Html(accent);
  document.getElementById('modalFoot').innerHTML='<button class="btn btn-default" onclick="impBackTo1()">← Back</button>'
    +'<button class="btn btn-accent" onclick="impGoStep3()" style="background:'+accent+';color:#fff;font-weight:600">Next: Options →</button>';
}
function impStep2Html(accent) {
  const imp=window._imp; const hdrs=imp.headers;
  function buildOpts(key){
    const mapped=imp.colMap[key]||'';
    return '<option value="">— Skip —</option>'+hdrs.map(function(h){return '<option value="'+esc(h)+'"'+(h===mapped?' selected':'')+'>'+esc(h)+'</option>';}).join('');
  }
  return impStepBar(1)+'<p style="font-size:13px;color:var(--text2);margin-bottom:16px">Match your file columns to event fields.</p>'
    +'<div class="form-grid">'+IMP_FIELDS.map(function(f){
      return '<div class="fg"><label>'+f.label+(f.required?' <span style="color:#DB1924">*</span>':'')+' </label>'
        +'<select id="imp_map_'+f.key+'" class="input" onchange="impSaveMapFromDom()">'+buildOpts(f.key)+'</select></div>';
    }).join('')+'</div>';
}
function impSaveMapFromDom() {
  const imp=window._imp; imp.colMap={}; const used=new Set();
  IMP_FIELDS.forEach(function(f){
    const el=document.getElementById('imp_map_'+f.key); const val=el?el.value:'';
    if(val&&!used.has(val)){imp.colMap[f.key]=val;used.add(val);}
  });
}
function impGoStep3() {
  impSaveMapFromDom();
  const imp=window._imp; if(!imp.colMap['title']){toast('Title column is required','err');return;}
  imp.step=3; const accent=ACCENT[co];
  const preview=imp.parsed.slice(0,5).map(function(row){
    const title=row[imp.colMap['title']]||row['title']||'—';
    const start=(row[imp.colMap['startDate']]||'') + (row[imp.colMap['startTime']] ? ' '+row[imp.colMap['startTime']] : '') || row[imp.colMap['startDateTime']]||row['startDateTime']||'';
    const cat=row[imp.colMap['category']]||row['category']||'';
    return '<tr><td style="padding:7px 10px;font-size:12.5px;font-weight:500">'+esc(title)+'</td>'
      +'<td style="padding:7px 10px;font-size:12px;color:var(--text2)">'+(start?new Date(start).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—')+'</td>'
      +'<td style="padding:7px 10px;font-size:12px;color:var(--text2)">'+esc(cat||'—')+'</td></tr>';
  }).join('');
  document.getElementById('modalBody').innerHTML=impStepBar(2)
    +'<p style="font-size:13px;color:var(--text2);margin-bottom:12px"><strong style="color:var(--text)">'+imp.parsed.length+' event'+(imp.parsed.length!==1?'s':'')+' ready.</strong></p>'
    +'<div class="card" style="overflow:hidden;padding:0;margin-bottom:16px">'
    +'<table style="width:100%;border-collapse:collapse"><thead><tr style="background:var(--muted);border-bottom:1px solid var(--border)">'
    +'<th style="padding:8px 10px;text-align:left;font-size:11.5px;color:var(--text2)">Title</th>'
    +'<th style="padding:8px 10px;text-align:left;font-size:11.5px;color:var(--text2)">Start</th>'
    +'<th style="padding:8px 10px;text-align:left;font-size:11.5px;color:var(--text2)">Category</th>'
    +'</tr></thead><tbody>'+preview+'</tbody></table></div>'
    +'<div><label style="font-size:13px;font-weight:500;margin-bottom:8px;display:block">Import Mode</label>'
    +'<div style="display:flex;flex-direction:column;gap:8px">'
    +'<label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-size:13px"><input type="radio" name="imp_mode" value="add" checked style="accent-color:'+accent+';margin-top:3px"> <span><strong>Upload as new events</strong><br><span style="font-size:12px;color:var(--text2)">Add all rows as new events — duplicates will be flagged</span></span></label>'
    +'<label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-size:13px"><input type="radio" name="imp_mode" value="update" style="accent-color:'+accent+';margin-top:3px"> <span><strong>Update existing events</strong><br><span style="font-size:12px;color:var(--text2)">Match by title + date and update fields — new events are added</span></span></label>'
    +'<label style="display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-size:13px"><input type="radio" name="imp_mode" value="replace" style="accent-color:'+accent+';margin-top:3px"> <span><strong>Replace all events</strong><br><span style="font-size:12px;color:var(--text2)">Wipe all existing events and import fresh</span></span></label>'
    +'</div></div>';
  document.getElementById('modalFoot').innerHTML='<button class="btn btn-default" onclick="impBackTo2()">← Back</button>'
    +'<button class="btn btn-accent" onclick="doEvImport()" style="background:'+accent+';color:#fff;font-weight:600">Import '+imp.parsed.length+' Event'+(imp.parsed.length!==1?'s':'')+'</button>';
}
function impBackTo1() {
  window._imp.step=1;
  document.getElementById('modalBody').innerHTML=impStep1Html();
  document.getElementById('modalFoot').innerHTML=impStep1Foot();
  requestAnimationFrame(function(){requestAnimationFrame(impWireDrop);});
}
function impBackTo2() {
  const accent=ACCENT[co]; window._imp.step=2;
  document.getElementById('modalBody').innerHTML=impStep2Html(accent);
  document.getElementById('modalFoot').innerHTML='<button class="btn btn-default" onclick="impBackTo1()">← Back</button>'
    +'<button class="btn btn-accent" onclick="impGoStep3()" style="background:'+accent+';color:#fff;font-weight:600">Next: Options →</button>';
}
function doEvImport() {
  const imp=window._imp;
  const mode=document.querySelector('input[name="imp_mode"]:checked') && document.querySelector('input[name="imp_mode"]:checked').value || 'add';
  const map=imp.colMap;

  // ── Normalizers ───────────────────────────────────────────────
  // Parse M/D/YY, M/D/YYYY, MM/DD/YY, MM/DD/YYYY → YYYY-MM-DD
  function normalizeDate(raw) {
    if (!raw) return '';
    raw = raw.trim();
    // Already ISO
    if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0,10);
    // M/D/YY or M/D/YYYY
    const m = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
    if (m) {
      let yr = parseInt(m[3]);
      if (yr < 100) yr += yr < 50 ? 2000 : 1900;
      return yr+'-'+String(m[1]).padStart(2,'0')+'-'+String(m[2]).padStart(2,'0');
    }
    return raw;
  }

  // Parse 10:00 AM, 10:00 PM, 10:00 → HH:MM (24-hour)
  function normalizeTime(raw) {
    if (!raw) return '';
    raw = raw.trim();
    // Already HH:MM 24h
    if (/^\d{2}:\d{2}$/.test(raw)) return raw;
    const m = raw.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
    if (m) {
      let h = parseInt(m[1]);
      const min = m[2];
      const ampm = (m[3]||'').toUpperCase();
      if (ampm==='PM' && h!==12) h+=12;
      if (ampm==='AM' && h===12) h=0;
      return String(h).padStart(2,'0')+':'+min;
    }
    return raw;
  }

  // Strip leading $, trailing spaces/dots, keep numeric
  function normalizePrice(raw) {
    if (!raw) return undefined;
    const s = raw.replace(/[$\s]/g,'').trim();
    if (s.toUpperCase()==='FREE'||s==='') return undefined;
    const n = parseFloat(s);
    return isNaN(n) ? undefined : String(n);
  }

  const newEvs=imp.parsed.map(function(row,i){
    const get=function(key){
      const col=map[key];
      return col ? (row[col]||'').trim() : '';
    };
    const ad=(get('isAllDay')||'').toLowerCase();

    // Combine Start Date + Start Time → startDateTime
    const sd = normalizeDate(get('startDate'));
    const st = normalizeTime(get('startTime'));
    const startDT = sd ? (st ? sd+'T'+st : sd+'T00:00:00') : undefined;

    // Combine End Date + End Time → endDateTime
    const ed = normalizeDate(get('endDate'));
    const et = normalizeTime(get('endTime'));
    const endDT = ed ? (et ? ed+'T'+et : ed+'T00:00:00') : undefined;

    const title = get('title');
    if (!title) return null;

    return {
      id:            Date.now().toString()+i+Math.random().toString(36).slice(2),
      title:         title,
      description:   get('description')||undefined,
      startDateTime: startDT,
      endDateTime:   endDT,
      address:       get('address')||undefined,
      tags:          get('tags')||undefined,
      memberPrice:    normalizePrice(get('memberPrice')),
      nonMemberPrice: normalizePrice(get('nonMemberPrice')),
      courseNumber:   get('courseNumber')||undefined,
      trecLicense:    get('trecLicense')||undefined,
      registrationUrl: get('registrationUrl')||undefined,
      category:      get('category')||'Other',
      organizer:     get('organizer')||undefined,
      isAllDay:      ad==='true'||ad==='1'||ad==='yes',
      eventColor:    get('eventColor')||undefined,
      createdAt:     new Date().toISOString()
    };
  }).filter(Boolean);
  // ── Duplicate detection helper ──────────────────────────────
  function evIsDup(incoming) {
    return eventsData[co].some(function(ex) {
      var titleMatch = (incoming.title||'').toLowerCase().trim() === (ex.title||'').toLowerCase().trim();
      var dateMatch  = incoming.startDateTime && ex.startDateTime &&
                       incoming.startDateTime.slice(0,10) === ex.startDateTime.slice(0,10);
      return titleMatch && dateMatch;
    });
  }

  if (mode==='replace') {
    var oldSyncedIds = eventsData[co]
      .filter(function(ev){ return ev.syncedApptId; })
      .map(function(ev){ return ev.syncedApptId; });
    if (oldSyncedIds.length) {
      DATA[co].appointments = (DATA[co].appointments||[]).filter(function(a){
        return oldSyncedIds.indexOf(a.id) === -1;
      });
    }
    eventsData[co] = newEvs;
  } else if (mode==='update') {
    var added=0, updated=0;
    newEvs.forEach(function(incoming) {
      var existing = eventsData[co].find(function(ex) {
        var titleMatch = (incoming.title||'').toLowerCase().trim() === (ex.title||'').toLowerCase().trim();
        var dateMatch  = incoming.startDateTime && ex.startDateTime &&
                         incoming.startDateTime.slice(0,10) === ex.startDateTime.slice(0,10);
        return titleMatch && dateMatch;
      });
      if (existing) {
        var oid = existing.id, ocat = existing.createdAt;
        Object.assign(existing, incoming, { id:oid, createdAt:ocat, updatedAt:new Date().toISOString() });
        updated++;
      } else {
        eventsData[co].push(incoming);
        added++;
      }
    });
    toast('Import complete — ' + added + ' added, ' + updated + ' updated', 'ok');
  } else {
    // add mode — check for duplicates
    var dups=[], unique=[];
    newEvs.forEach(function(ev) {
      if (evIsDup(ev)) dups.push(ev);
      else unique.push(ev);
    });
    eventsData[co] = eventsData[co].concat(unique);
    if (dups.length) {
      toast(unique.length + ' event' + (unique.length!==1?'s':'') + ' added, ' + dups.length + ' duplicate'+(dups.length!==1?'s':'')+' skipped', 'warn');
    }
  }

  // ── Sync any imported events tagged "Team Calendar" ──────────
  var synced = 0;
  eventsData[co].forEach(function(ev) {
    if (!ev.tags) return;
    var tagList = ev.tags.split(',').map(function(t){ return t.trim().toLowerCase(); });
    if (tagList.indexOf('team calendar') !== -1) {
      evSyncToTeamCalendar(ev, true); // silent — summary toast fires below
      synced++;
    }
  });

  persist(); closeModal(); renderEvents();
  var msg = 'Imported '+newEvs.length+' event'+(newEvs.length!==1?'s':'');
  if (synced) msg += ', '+synced+' synced to Team Calendar';
  toast(msg,'ok');
  if (currentPage === 'calendarly') renderCalendarly();
}
function impDownloadTemplate() {
  const hdr='title,description,startDate,startTime,endDate,endTime,address,tags,memberPrice,nonMemberPrice,courseNumber,trecLicense,category,organizer,isAllDay,eventColor';
  const ex='Annual Conference,Full day event,2026-09-15,09:00,2026-09-15,17:00,500 E Cesar Chavez St Austin TX,"CE Course,Team Calendar",150,225,CE-1234,9999999,CE Course,SABOR,false,#3B82F6';
  const a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(hdr+'\n'+ex);
  a.download='events-template.csv'; a.click();
  toast('Template downloaded','ok');
}

// ── clientEmail — opens full email composer for a client ──
function clientEmail(id) {
  var c = DATA[co].clients.find(function(x){ return x.id===id; });
  if (!c) return;
  var email = c.email || '';
  if (!email) { toast('No email on file for this client','err'); return; }
  var name = ((c.firstName||'') + ' ' + (c.lastName||'')).trim() || c.name || c.company || email;
  var pub = co==='rl' ? 'RealtyLine' : 'Newsline';
  openEmailComposer(email, name, 'Hello from ' + pub, ACCENT[co]);
}

// ── clientSendText — opens native SMS app with pre-filled message ──
function clientSendText(id) {
  var c = DATA[co].clients.find(function(x){ return x.id===id; });
  if (!c) return;
  var phone = c.phone || c.mobile || '';
  if (!phone) { toast('No phone number on file','err'); return; }
  var digits    = phone.replace(/[^0-9]/g,'');
  var pub       = co === 'rl' ? 'RealtyLine' : 'Newsline';
  var firstName = c.firstName || (c.name||'').split(' ')[0] || '';
  var msg       = 'Hi ' + (firstName || 'there') + ', this is ' + pub + '. ';
  window.open('sms:+1' + digits + '&body=' + encodeURIComponent(msg), '_blank');
}

