var STATE_NAME_MAP = {
  'alabama':'AL','alaska':'AK','arizona':'AZ','arkansas':'AR','california':'CA',
  'colorado':'CO','connecticut':'CT','delaware':'DE','florida':'FL','georgia':'GA',
  'hawaii':'HI','idaho':'ID','illinois':'IL','indiana':'IN','iowa':'IA',
  'kansas':'KS','kentucky':'KY','louisiana':'LA','maine':'ME','maryland':'MD',
  'massachusetts':'MA','michigan':'MI','minnesota':'MN','mississippi':'MS','missouri':'MO',
  'montana':'MT','nebraska':'NE','nevada':'NV','new hampshire':'NH','new jersey':'NJ',
  'new mexico':'NM','new york':'NY','north carolina':'NC','north dakota':'ND','ohio':'OH',
  'oklahoma':'OK','oregon':'OR','pennsylvania':'PA','rhode island':'RI','south carolina':'SC',
  'south dakota':'SD','tennessee':'TN','texas':'TX','utah':'UT','vermont':'VT',
  'virginia':'VA','washington':'WA','west virginia':'WV','wisconsin':'WI','wyoming':'WY',
  'district of columbia':'DC','washington dc':'DC','washington d.c.':'DC'
};
function normalizeState(s) {
  if (!s) return '';
  var trimmed = s.trim();
  if (trimmed.length === 2) return trimmed.toUpperCase();
  var lower = trimmed.toLowerCase();
  return STATE_NAME_MAP[lower] || trimmed.slice(0,2).toUpperCase();
}

function mlDoImport(){
  const ml=window._ml; const rows=ml.parsed;
  if(!rows.length)return;
  const map=ml.colMap; const mode=ml.mode;

  // Collect match keys from DOM (modal still open at this point)
  const matchKeys=['fullName','email','license'].filter(k=>{
    const el=document.getElementById('mlmk_'+k);
    return el ? el.checked : ml.matchKeys.includes(k);
  });
  ml.matchKeys=matchKeys;
  if(mode==='smart'&&!matchKeys.length){toast('Select at least one match field for Smart Merge','err');return;}

  function mapRow(raw){
    const get=f=>map[f]?(raw[map[f]]||'').trim():'';
    const firstName=get('firstName'),lastName=get('lastName'),contactName=get('name');
    const name=contactName||(firstName&&lastName?firstName+' '+lastName:firstName||lastName||'');
    var rawState = get('state');
    return {
      id:Date.now().toString()+Math.random().toString(36).slice(2),
      name,firstName,lastName,
      company:get('company'),email:(get('email')||'').toLowerCase(),
      mobile:fmtPhone(get('mobile')),phone:fmtPhone(get('phone')),
      title:get('title'),address:get('address'),address2:get('address2'),
      city:get('city'),state:normalizeState(rawState),zip:get('zip'),
      license:get('license'),tags:get('tags'),
      createdAt:new Date().toISOString(),
    };
  }

  const mapped=rows.map(mapRow).filter(r=>r.name||r.email||r.license);
  if(!mapped.length){toast('No valid rows after mapping','err');return;}

  const contacts=DATA[co].mailing;

  // Smart match: ALL selected keys must agree (when both sides have a value).
  // At least one key must have matched (both non-empty and equal).
  function matchContact(incoming,existing){
    let anyMatch=false;
    for(const k of matchKeys){
      let a='',b='';
      if(k==='fullName'){a=(incoming.name||'').trim().toLowerCase();b=(existing.name||'').trim().toLowerCase();}
      else if(k==='email'){a=(incoming.email||'').trim().toLowerCase();b=(existing.email||'').trim().toLowerCase();}
      else if(k==='license'){a=(incoming.license||'').replace(/\s/g,'').toLowerCase();b=(existing.license||'').replace(/\s/g,'').toLowerCase();}
      if(a&&b){if(a!==b)return false;anyMatch=true;}
    }
    return anyMatch;
  }

  if(mode==='add'){
    var addedCount=0, skippedCount=0;
    mapped.forEach(function(r){
      var isDup = contacts.find(function(x){
        if(r.email && x.email && r.email.toLowerCase()===x.email.toLowerCase()) return true;
        if(r.name  && x.name  && r.name.toLowerCase()===x.name.toLowerCase())   return true;
        if(r.license && x.license && r.license.trim() && r.license.trim().toLowerCase()===x.license.trim().toLowerCase()) return true;
        return false;
      });
      if(isDup){ skippedCount++; }
      else { contacts.push(r); addedCount++; }
    });
    persistAll();closeModal();renderMailing();
    var msg='Import complete — '+addedCount+' added';
    if(skippedCount) msg+=', '+skippedCount+' duplicate'+(skippedCount!==1?'s':'')+' skipped';
    toast(msg,'ok');
  }else if(mode==='replace'){
    DATA[co].mailing=mapped;
    persist();closeModal();renderMailing();
    toast('Replaced all — '+mapped.length+' imported','ok');
  }else{
    let added=0,updated=0;
    mapped.forEach(incoming=>{
      const existing=contacts.find(c=>matchContact(incoming,c));
      if(existing){const oid=existing.id,ocat=existing.createdAt;Object.assign(existing,incoming,{id:oid,createdAt:ocat,updatedAt:new Date().toISOString()});updated++;}
      else{contacts.push(incoming);added++;}
    });
    persist();closeModal();renderMailing();
    toast('Import complete — '+added+' added, '+updated+' updated','ok');
  }
}

function confirmDeleteAllMailing() {
  var count = DATA[co].mailing.length;
  if (!count) { toast('No contacts to delete', 'err'); return; }
  var coName = co === 'rl' ? 'RealtyLine' : 'Newsline';
  openModal(
    '<div class="modal-title" style="color:#DB1924">'+icon('trash')+' Delete All Contacts</div>',
    '<div style="display:flex;flex-direction:column;gap:14px">'
    + '<div style="padding:14px;background:color-mix(in srgb,var(--destructive) 8%,transparent);border:1px solid color-mix(in srgb,var(--destructive) 25%,transparent);border-radius:var(--r)">'
    + '<div style="font-weight:600;color:#DB1924;margin-bottom:4px">This cannot be undone.</div>'
    + '<div style="font-size:13.5px;color:var(--text2)">All <strong style="color:var(--text)">'+count+' contacts</strong> in the '+coName+' mailing list will be permanently deleted.</div>'
    + '</div>'
    + '<div style="font-size:13px;color:var(--text2)">Type <strong style="color:var(--text)">DELETE</strong> to confirm:</div>'
    + '<input id="delete_confirm_input" placeholder="Type DELETE" style="padding:8px 10px;background:var(--muted2);border:1px solid var(--border);border-radius:var(--r);color:var(--text);font-size:13.5px;font-family:inherit;outline:none;width:100%;box-sizing:border-box">'
    + '</div>',
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button id="delete_all_btn" class="btn btn-sm" disabled onclick="executeDeleteAllMailing()" style="background:#DB1924;color:#fff;font-weight:600;opacity:.5;cursor:not-allowed">Delete All '+count+' Contacts</button>'
  );
  // Enable button when input matches
  requestAnimationFrame(function(){ 
    var inp = document.getElementById('delete_confirm_input');
    var btn = document.getElementById('delete_all_btn');
    if (inp) inp.addEventListener('input', function(){
      var ok = this.value === 'DELETE';
      btn.disabled = !ok;
      btn.style.opacity = ok ? '1' : '.5';
      btn.style.cursor = ok ? 'pointer' : 'not-allowed';
    });
  });
}

