function scanSetDest(t) {
  window._scanTarget = t;
  var accent = ACCENT[co];
  document.querySelectorAll('.scan_dest_btn').forEach(function(b){
    var active = b.getAttribute('data-dest') === t;
    b.style.background   = active ? accent : 'var(--muted2)';
    b.style.color        = active ? '#fff'  : 'var(--text2)';
    b.style.borderColor  = active ? accent  : 'var(--border)';
  });
}

function scanHandleDrop(e) {
  var file = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  if (file) scanHandleFile(file);
}

function scanHandleFile(file) {
  if (!file) return;
  if (file.size > 50 * 1024 * 1024) { toast('File too large — max 50MB', 'err'); return; }

  // Show preview
  var reader = new FileReader();
  reader.onload = function(e) {
    var dataUrl = e.target.result;
    var img = document.getElementById('scan_img');
    var preview = document.getElementById('scan_preview');
    if (img) img.src = dataUrl;
    if (preview) preview.style.display = 'flex';
    setStatus('Analyzing card with Gemini Vision…', true);
    scanExtract(dataUrl, file.type);
  };
  reader.readAsDataURL(file);
}

function setStatus(msg, loading) {
  var el = document.getElementById('scan_status');
  if (!el) return;
  el.innerHTML = loading
    ? '<span style="display:inline-flex;align-items:center;gap:8px"><span style="display:inline-block;width:14px;height:14px;border:2px solid var(--border);border-top-color:#021D40;border-radius:50%;animation:spin 0.8s linear infinite"></span>' + msg + '</span>'
    : msg;
}

function scanExtract(dataUrl, mimeType) {
  var base64 = dataUrl.split(',')[1];
  var imgType = (mimeType || 'image/jpeg').replace('image/', '').toLowerCase();
  var mediaType = 'image/jpeg';
  if (imgType === 'png')  mediaType = 'image/png';
  if (imgType === 'webp') mediaType = 'image/webp';
  if (imgType === 'gif')  mediaType = 'image/gif';

  var prompt = 'This is a photo of a business card. Extract all contact information and return ONLY a valid JSON object with these exact keys (use empty string "" for any field not found):\n'
    + '{"firstName":"","lastName":"","company":"","title":"","phone":"","mobile":"","email":"","address":"","address2":"","city":"","state":"","zip":"","website":"","license":""}\n'
    + 'For phone numbers use format: 512-555-0000\n'
    + 'For state use 2-letter abbreviation.\n'
    + 'For license: look for TREC, license #, Lic #, or similar real estate license numbers.\n'
    + 'Return ONLY the JSON object, no explanation or markdown.';

  // Use Gemini via proxy endpoint
  var body = JSON.stringify({
    base64: base64,
    mimeType: mediaType,
    prompt: prompt
  });

  fetchWithTimeout(CAXTON_PROXY + '/api/gemini/vision', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: body
  }, 30000)
  .then(function(r) { return r.json(); })
  .then(function(data) {
    if (data.error) throw new Error(data.error);
    var text = data.text || '';
    text = text.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim();
    var parsed;
    try { parsed = JSON.parse(text); }
    catch(e) {
      var m = text.match(/\{[\s\S]*\}/);
      if (m) parsed = JSON.parse(m[0]);
      else throw new Error('Could not parse response');
    }
    scanPopulateFields(parsed);
    setStatus('&#10003; Contact extracted — review and save', false);
  })
  .catch(function(err) {
    console.error('Card scan error:', err);
    var msg = (err && err.message === 'timeout')
      ? '&#9888; Request timed out — enter details manually below.'
      : '&#9888; ' + sanitizeApiError(err && err.message) + ' Enter details manually below.';
    setStatus(msg, false);
    scanPopulateFields({});
  });
}

function scanPopulateFields(d) {
  var fields = { sc_first:'firstName', sc_last:'lastName', sc_company:'company',
    sc_title:'title', sc_license:'license', sc_phone:'phone', sc_mobile:'mobile',
    sc_email:'email', sc_addr:'address', sc_addr2:'address2',
    sc_city:'city', sc_state:'state', sc_zip:'zip', sc_website:'website' };
  Object.keys(fields).forEach(function(id) {
    var el = document.getElementById(id);
    if (el) el.value = d[fields[id]] || '';
  });
  var fieldsDiv = document.getElementById('scan_fields');
  var saveBtn   = document.getElementById('scan_save_btn');
  if (fieldsDiv) fieldsDiv.style.display = 'block';
  if (saveBtn)   saveBtn.style.display = 'inline-flex';
}

function scanSaveContact() {
  var g = function(id) { var el=document.getElementById(id); return el ? el.value.trim() : ''; };
  var first = g('sc_first'), last = g('sc_last');
  if (!first && !last && !g('sc_company')) { toast('Name or company required','err'); return; }
  var name = [first,last].filter(Boolean).join(' ') || g('sc_company');
  var now = new Date().toISOString();
  var target = window._scanTarget || 'clients';

  if (target === 'prospects') {
    // Save as prospect
    ensureProspects(co);
    var prospect = {
      id:          Date.now().toString(36)+Math.random().toString(36).slice(2),
      companyName: g('sc_company'),
      contactName: name,
      email:       g('sc_email'),
      phone:       g('sc_phone')||g('sc_mobile'),
      stage:       'New',
      value:       0,
      source:      'Business Card Scan',
      notes:       g('sc_notes'),
      createdAt:   now, updatedAt: now
    };
    DATA[co].prospects.unshift(prospect);
    persist();
    closeModal();
    clientsMainTab = 'prospects';
    renderClients();
    toast(name + ' added to Prospects', 'ok');
    return;
  }

  var contact = {
    id:         Date.now().toString() + Math.random().toString(36).slice(2),
    firstName:  first, lastName: last, name: name,
    company:    g('sc_company'),
    title:      g('sc_title'),
    license:    g('sc_license'),
    phone:      g('sc_phone'),
    mobile:     g('sc_mobile'),
    email:      g('sc_email'),
    address:    g('sc_addr'),
    address2:   g('sc_addr2'),
    city:       g('sc_city'),
    state:      g('sc_state') || 'TX',
    zip:        g('sc_zip'),
    website:    g('sc_website'),
    notes:      g('sc_notes'),
    tags:       '',
    status:     'Active',
    source:     'Business Card Scan',
    scannedCard: true,
    createdAt:  now,
  };

  if (target === 'mailing') {
    contact.addrStatus  = '';
    contact.emailStatus = '';
  }

  if (!DATA[co][target]) DATA[co][target] = [];
  DATA[co][target].unshift(contact);
  persist();
  closeModal();
  if (target === 'mailing') renderMailing(); else renderClients();
  toast(name + ' added to ' + (target==='mailing'?'Mailing List':'Clients'), 'ok');
}

