    + '<div class="fg"><label>Client Portal Email</label><input id="cf_portal_email" value="' + val('portalEmail') + '" placeholder="portal@example.com"><div style="font-size:11px;color:var(--text3);margin-top:3px">Used for client portal login</div></div>'
    + '</div>'

    + '<div class="form-row form-row-2">'
    + '<div class="fg"><label>Mobile</label><input id="cf_mobile" value="' + val('mobile') + '" placeholder="000-000-0000" data-phone-fmt="1"></div>'
    + '<div class="fg"><label>Office Phone</label><input id="cf_phone" value="' + val('phone') + '" placeholder="000-000-0000" data-phone-fmt="1"></div>'
    + '</div>'

    + '<div class="fg full"><label>Website</label><input id="cf_website" value="' + val('website') + '" placeholder="https://example.com"></div>'

    + '<div class="form-row form-row-2">'
