    + '<div class="fg"><label>Status</label>'
    + '<select id="cf_status"><option value="">— None —</option>'
    + ['Active','Prospect','Past','Lead','Inactive'].map(function(s){ return '<option value="'+s+'"'+(c&&c.status===s?' selected':'')+'>'+s+'</option>'; }).join('')
    + '</select></div>'
