      var fn  = document.getElementById('hc_file_name');   if(fn)  fn.textContent=window._hc.fileName;
      var fc  = document.getElementById('hc_file_count');  if(fc)  fc.textContent='· '+window._hc.parsed.length+' rows ready';
      var lbl = document.getElementById('hc_drop_label');  if(lbl) lbl.textContent=window._hc.fileName||'File loaded';
      var zone= document.getElementById('hc_drop_zone');   if(zone)zone.style.borderColor=ACCENT[co];
