    +'<button class="btn btn-default btn-sm" onclick="agFormSave(false)">Save as Draft</button>'
    +(isUp?''
      :'<button class="btn btn-sm" onclick="agFormSignLink()" style="background:#0d9488;color:#fff;font-weight:600;gap:5px">'+icon('link')+' Send Signing Link</button>'
       +'<button id="agf_signbtn" class="btn btn-sm" onclick="agFormSave(true)" style="background:'+accent+';color:#fff;font-weight:600;opacity:.5" disabled>Sign &amp; Save</button>')
    +'</div>';

  openModal(
    '<div class="modal-title">'+(ag?'Edit Agreement':'New Advertising Agreement')+'</div>'
    +'<div class="modal-subtitle">— '+(isNL?'Newsline':'RealtyLine')+' Advertising Agreement</div>',
    body2,foot,true
  );
