function saveRenewal(origId, locked){
  const exp=document.getElementById('rn_exp')?.value;
  if(!exp){toast('New expiration date required','err');return;}
  const rate=parseFloat(document.getElementById('rn_rate')?.value)||0;
  const orig=DATA[co].agreements.find(a=>a.id===origId);
  if(!orig) return;
  DATA[co].agreements.unshift({
    id:Date.now().toString(),companyName:orig.companyName,repName:orig.repName,email:orig.email,
    contactNumber:orig.contactNumber,mailingAddress:orig.mailingAddress,city:orig.city,state:orig.state,zip:orig.zip,
    billTo:orig.billTo,billingEmail:orig.billingEmail,billingContactName:orig.billingContactName,billingContactNumber:orig.billingContactNumber,
    paymentType:orig.paymentType,
    adSize:document.getElementById('rn_size')?.value||orig.adSize,
    frequency:document.getElementById('rn_freq')?.value||orig.frequency,
    adRate:rate,expDate:exp,notes:document.getElementById('rn_notes')?.value,
    status:'Draft',isRenewal:true,renewedFromId:origId,originalSignedRate:orig.adRate||0,
    createdAt:new Date().toISOString(),
    auditLog:[{event:'Renewal Created',timestamp:new Date().toISOString(),userEmail:'user@example.com',details:'Renewal from agreement '+origId+'. Rate: '+(locked?'Locked':'Open market')}]
  });
  persist();closeModal();renewals();toast('Renewal agreement created as Draft!','ok');
}

