// ── FAB action — context-aware quick add ──────────
function fabAction() {
  var actions = {
    clients:      function(){ openContactForm(); },
    mailing:      function(){ mlOpenAddContact(); },
    appointments: function(){ openApptForm(); },
    agreements:   function(){ goTo('agreements'); },
    events:       function(){ openEvModal(); },
    forms:        function(){ toast('Use the Forms page to create a new form',''); },
    dashboard:    function(){ openContactForm(); },
  };
  var fn = actions[currentPage] || function(){ openContactForm(); };
  fn();
}

(function init(){
  loadPersistedData();
  if (formsCheckPublicView()) return;
  if (checkPortalToken()) return;
  if (checkBookingUrl()) return;
  const saved=localStorage.getItem('crm_co');
  if(saved==='nl'||saved==='rl') co=saved;
  const savedUser = localStorage.getItem('crm_user');
  if(savedUser && ['tawanna','doren','caroline'].indexOf(savedUser)!==-1) CRM_USER=savedUser;
  const savedPage = localStorage.getItem('crm_page');
  if (savedPage && ['dashboard','clients','appointments','mailing','holding','agreements','renewals','forms','packages','portal','invoices','emails','events','booking','backups','scheduling','onboarding','calendarly'].includes(savedPage)) {
    currentPage = savedPage;
  }

  // ── Theme + Font Size init ─────────────────────────────────
  var savedTheme = localStorage.getItem('crm_theme') || 'dark';
  var savedFs    = localStorage.getItem('crm_fs')    || 'md';
  applyTheme(savedTheme);
  applyFontSize(savedFs);
  ensureArrays();
  switchCo(co);  // sets accent, updates buttons — calls renderPage internally
  buildNav();
  buildUserSwitcher();
  evSeedDefaults();
  startBackupScheduler();  // 15-min auto-backup, both companies
  startMlsSyncScheduler(); // Auto-sync from UnlockMLS
  loadFromDb().then(function(loaded) {
    ensureArrays();
    // NOTE: Do NOT call persistAll() here — loadFromDb already has the authoritative
    // DB data in memory. Calling persistAll would risk overwriting the DB with stale
    // localStorage data that was loaded before the DB fetch completed.
    // Sweep all portal staff and location blocks → mailing list (both publications)
    var _prevCo = co;
    ['rl','nl'].forEach(function(pub) {
      co = pub;
      // Fix any mailing entries that have city/state/zip concatenated into address
      var fixed = 0;
      (DATA[co].mailing || []).forEach(function(m) {
        if (m.address && (!m.city || !m.state)) {
          var match = m.address.match(/^(.+?),\s*([A-Za-z][A-Za-z\s]+?),\s*([A-Z]{2})\s+([\d]{5}(?:-[\d]{4})?)/);
          if (match) {
            m.address = match[1].trim();
            if (!m.city)  m.city  = match[2].trim();
            if (!m.state) m.state = match[3].trim();
            if (!m.zip)   m.zip   = match[4].trim();
            m.updatedAt = new Date().toISOString();
            fixed++;
          }
        }
      });
      if (fixed) {
        persist();
        crmFetch(API_BASE + '/api/crm/' + co + '/mailing', {
          method:'PUT', headers:{'Content-Type':'application/json'},
          body: JSON.stringify(DATA[co].mailing)
        }).catch(function(){});
      }
      portalSyncAllStaffToMailing();
      portalSyncAllLocationsToMailing();
    });
    co = _prevCo;
    var pageArea = document.getElementById('pageArea');
    if (pageArea) {
      var renders = { dashboard:renderDashboard, clients:renderClients,
        appointments:renderAppointments, mailing:renderMailing, holding:renderHolding, clientmailing:renderClientMailing,
        agreements:renderAgreements, forms:renderForms, packages:renderPackages,
        invoices:renderInvoices, portal:renderPortal, emails:renderEmails, events:renderEvents, backups:renderBackups, booking:renderBookingPage, calendarly:renderCalendarly, scheduling:renderSchedulingPage };
      var fn = renders[currentPage];
      if (fn) fn();
    }
  });
})();
