    + '<button onclick="navigator.clipboard.writeText(\''+esc(link)+'\').then(function(){toast(\'Poll link copied!\',\'ok\');})" class="btn btn-sm" style="background:'+accent+';color:#fff;font-weight:600;white-space:nowrap">'+icon('copy')+' Copy</button>'
