function schedSharePoll() {
  var title = (document.getElementById('pw_title')||{}).value || pollWizardData.title || 'Meeting';
  pollWizardData.title = title;
  if (!pollWizardData.location) pollWizardData.location = 'Phone call';
  pollWizardData.showVotes = pollWizardData.showVotes !== false;
  pollWizardStep = 3;
  renderPollWizard();
}

function pollToggleTime(dateStr, timeKey) {
  if (!pollWizardData.selTimes) pollWizardData.selTimes = {};
  var arr = pollWizardData.selTimes[dateStr] || [];
  var idx = arr.indexOf(timeKey);
  if (idx === -1) arr.push(timeKey);
  else arr.splice(idx, 1);
  if (arr.length) pollWizardData.selTimes[dateStr] = arr;
  else delete pollWizardData.selTimes[dateStr];
  renderPollWizard();
}

function pollAddTimes(dateStr) {
  if (!pollWizardData.selTimes) pollWizardData.selTimes = {};
  var host    = pollWizardData.host || (EMAIL_SENDERS[co]||[])[0] || {};
  var durMin2 = parseInt((pollWizardData.duration||'30').replace(/[^0-9]/g,''))||30;
  var slots   = getAvailSlots().filter(function(s){return s.name===host.name&&s.active!==false;});
  var DAY_NAMES_F = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var d = new Date(dateStr+'T12:00:00');
  var dayName = DAY_NAMES_F[d.getDay()];
  var matchSlots = slots.filter(function(s){return s.day===dayName;});
  var times = [];
  matchSlots.forEach(function(s){
    if (!s.startTime||!s.endTime) return;
    var sp = s.startTime.split(':'), ep = s.endTime.split(':');
    var cur = parseInt(sp[0])*60+parseInt(sp[1]||0), end = parseInt(ep[0])*60+parseInt(ep[1]||0);
    while(cur+durMin2<=end){var hh=String(Math.floor(cur/60)).padStart(2,'0'),mm=String(cur%60).padStart(2,'0');times.push(hh+':'+mm);cur+=durMin2;}
  });
  // Default: 9am–5pm if no slots configured
  if (!times.length) {
    var cur2 = 9*60, end2 = 17*60;
    while(cur2+durMin2<=end2){var hh2=String(Math.floor(cur2/60)).padStart(2,'0'),mm2=String(cur2%60).padStart(2,'0');times.push(hh2+':'+mm2);cur2+=durMin2;}
  }
  pollWizardData.selTimes[dateStr] = times;
  renderPollWizard();
}

// ── Poll vote tracking & auto-cleanup ────────────────────────
function schedTrackVotes(idx) {
  var accent  = ACCENT[co];
  var polls   = getMeetingPolls();
  var p       = polls[idx]; if (!p) return;
  var members = EMAIL_SENDERS[co] || [];
  var votes   = p.votes || {};
  var durMin2 = parseInt((p.duration||'30').replace(/[^0-9]/g,''))||30;

  // Build all slots list
  var allSlots = [];
  Object.keys(p.selTimes||{}).sort().forEach(function(ds){
    (p.selTimes[ds]||[]).sort().forEach(function(tk){
      allSlots.push(ds+'T'+tk+':00');
    });
  });


  function fmt(slotKey) {
    var d = new Date(slotKey);
    var h=d.getHours(),m=String(d.getMinutes()).padStart(2,'0'),ap=h>=12?'pm':'am';h=h%12||12;
    var endD=new Date(d.getTime()+durMin2*60000),eh=endD.getHours(),em=String(endD.getMinutes()).padStart(2,'0'),eap=eh>=12?'pm':'am';eh=eh%12||12;
    return DAYS_S[d.getDay()]+', '+MONTHS_S[d.getMonth()]+' '+d.getDate()+' \u2022 '+h+':'+m+ap+'\u2013'+eh+':'+em+eap;
  }

  var slotRows = allSlots.map(function(sl, si) {
    var slotVoters = votes[sl] || [];
    var votedAll   = slotVoters.length >= members.length;
    var memberChips = members.map(function(m) {
      var voted    = slotVoters.indexOf(m.email) !== -1;
      var initials = m.name.split(' ').map(function(w){return w[0]||'';}).join('').toUpperCase().slice(0,2);
      return '<span onclick="pollCastVote('+idx+',\''+esc(sl)+'\',\''+esc(m.email)+'\')" title="'+(voted?'Remove vote for ':'Vote for ')+esc(m.name)+'" style="display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;font-size:10px;font-weight:700;cursor:pointer;transition:all .15s;'+(voted?'background:'+accent+';color:#fff;':'background:var(--muted);color:var(--text3);border:1.5px dashed var(--border2);')+'">'
        + esc(initials)+'</span>';
    }).join('');

    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--border);background:'+(votedAll?'color-mix(in srgb,#22c55e 8%,transparent)':'var(--surface)')+';transition:background .2s">'
      + '<div style="font-size:13px;color:var(--text);flex:1">'
      + (votedAll ? '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#22c55e" stroke-width="2.5" style="vertical-align:middle;margin-right:5px"><path d="M20 6L9 17l-5-5"/></svg>' : '')
      + esc(fmt(sl))
      + '</div>'
      + '<div style="display:flex;align-items:center;gap:5px">'
      + memberChips
      + '<span style="font-size:11.5px;color:var(--text3);margin-left:6px">'+slotVoters.length+'/'+members.length+'</span>'
      + '</div>'
      + '</div>';
  }).join('');

  if (!slotRows) slotRows = '<div style="padding:20px;text-align:center;color:var(--text3);font-size:13px">No time slots in this poll.</div>';

  openModal(
    '<div class="modal-title"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3H14z"/><path d="M7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg> Track Votes \u2014 '+esc(p.title||'Meeting')+'</div>',
    '<div>'
    + '<div style="font-size:12.5px;color:var(--text2);padding:0 0 12px">Click a member\'s initials to toggle their vote for a time slot. When all members vote for the same slot, it automatically books and clears the other placeholders from Team Calendar.</div>'
    + '<div style="border:1px solid var(--border);border-radius:var(--r);overflow:hidden">'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 14px;background:var(--surface2);border-bottom:1px solid var(--border)">'
    + '<div style="font-size:11.5px;font-weight:700;color:var(--text2)">Time Slot</div>'
    + '<div style="display:flex;align-items:center;gap:5px">'
    + members.map(function(m){return '<span style="font-size:10.5px;font-weight:600;color:var(--text3);width:28px;text-align:center">'+esc(m.name.split(' ')[0].slice(0,4))+'</span>';}).join('')
    + '</div>'
    + '</div>'
    + slotRows
    + '</div>'
    + '</div>',
    '<button class="btn btn-default" onclick="closeModal()">Close</button>',
    true
  );
}

function pollCastVote(pollIdx, slotKey, memberEmail) {
  var polls = getMeetingPolls();
  var p     = polls[pollIdx]; if (!p) return;
  if (!p.votes) p.votes = {};
  if (!p.votes[slotKey]) p.votes[slotKey] = [];
  var arr = p.votes[slotKey];
  var pos = arr.indexOf(memberEmail);
  if (pos === -1) arr.push(memberEmail);
  else arr.splice(pos, 1);
  saveMeetingPolls(polls);

  // Check if consensus reached — auto-cleanup
  pollCheckConsensus(pollIdx);
}

function pollCheckConsensus(pollIdx) {
  var polls   = getMeetingPolls();
  var p       = polls[pollIdx]; if (!p || p.status === 'booked') return;
  var members = EMAIL_SENDERS[co] || [];
  if (!members.length) return;
  var needed  = members.length;
  var votes   = p.votes || {};
  var winner  = null;

  Object.keys(votes).forEach(function(sl) {
    if ((votes[sl]||[]).length >= needed) winner = sl;
  });

  if (!winner) {
    // Just save updated votes, re-render modal
    saveMeetingPolls(polls);
    schedTrackVotes(pollIdx);
    return;
  }

  // ── Consensus reached! ──────────────────────────────────────
  // 1. Mark poll as booked
  p.status     = 'booked';
  p.bookedSlot = winner;
  saveMeetingPolls(polls);

  // 2. Remove all placeholder appointments for this poll EXCEPT the winner
  var durMin3  = parseInt((p.duration||'30').replace(/[^0-9]/g,''))||30;
  var hostEmail = p.hostEmail || '';
  var winnerApptId = 'poll-'+p.id+'-'+winner.substring(0,10)+'-'+winner.substring(11,16).replace(':','-');

  // Remove all other placeholders for this poll
  DATA[co].appointments = DATA[co].appointments.filter(function(a) {
    return !(a.pollId === p.id && a.id !== winnerApptId);
  });

  // 3. Convert the winner placeholder to a confirmed appointment
  var winnerAppt = DATA[co].appointments.find(function(a){ return a.id === winnerApptId; });
  if (winnerAppt) {
    winnerAppt.isPlaceholder = false;
    winnerAppt.title         = '\u2705 ' + (p.title||'Meeting') + ' (Confirmed)';
    winnerAppt.client        = members.map(function(m){return m.name;}).join(', ');
    winnerAppt.notes         = 'Confirmed via meeting poll. All team members voted for this time.';
    winnerAppt.updatedAt     = new Date().toISOString();
  } else {
    // Placeholder wasn't found (poll may have been created before placeholder logic) — create it
    var endD3 = new Date(winner); endD3.setMinutes(endD3.getMinutes()+durMin3);
    DATA[co].appointments.push({
      id:         winnerApptId,
      pollId:     p.id,
      title:      '\u2705 ' + (p.title||'Meeting') + ' (Confirmed)',
      client:     members.map(function(m){return m.name;}).join(', '),
      agentEmail: hostEmail,
      dt:         winner,
      endDt:      endD3.getFullYear()+'-'+String(endD3.getMonth()+1).padStart(2,'0')+'-'+String(endD3.getDate()).padStart(2,'0')+'T'+String(endD3.getHours()).padStart(2,'0')+':'+String(endD3.getMinutes()).padStart(2,'0')+':00',
      location:   p.location||'',
      notes:      'Confirmed via meeting poll. All team members voted for this time.',
      isPlaceholder: false,
      createdAt:  new Date().toISOString(),
      updatedAt:  new Date().toISOString()
    });
  }

  persist();

  // 4. Close modal and celebrate
  closeModal();
  var d2 = new Date(winner);
  var MONTHS_S2 = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  var DAYS_S2   = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  var h2=d2.getHours(),m2=String(d2.getMinutes()).padStart(2,'0'),ap2=h2>=12?'pm':'am';h2=h2%12||12;
  var winLabel  = DAYS_S2[d2.getDay()]+', '+MONTHS_S2[d2.getMonth()]+' '+d2.getDate()+' at '+h2+':'+m2+ap2;
  toast('\u2705 All voted! "'+p.title+'" booked for '+winLabel+'. Placeholders removed from Team Calendar.', 'ok');
  schedulingTab = 'meeting-polls';
  renderSchedulingPage();
}

function schedDeletePoll(idx) {
  requireDeleteAuth(function(){
    var polls = getMeetingPolls();
    var p = polls[idx];
    if (p && p.id) {
      DATA[co].appointments = DATA[co].appointments.filter(function(a){ return a.pollId !== p.id; });
      persist();
    }
    polls.splice(idx, 1);
    saveMeetingPolls(polls);
    toast('Poll and calendar placeholders deleted', 'ok');
    renderSchedulingPage();
  }, 'delete this meeting poll');
}

function schedCopyPollLink(idx) {
  var polls = getMeetingPolls(); var p = polls[idx]; if (!p) return;
  navigator.clipboard.writeText(p.link||'').then(function(){ toast('Poll link copied!','ok'); });
}

// ════════════════════════════════════════════════════════════════
// BACKUP & RESTORE — Per-company, per-page, 15-min auto-scheduler
// ════════════════════════════════════════════════════════════════

// ── Page map: every backupable type grouped by page/section ─────
var BACKUP_PAGE_MAP = [
  { group:'Core CRM',   key:'clients',        label:'Clients',              page:'clients'      },
  { group:'Core CRM',   key:'prospects',       label:'Prospects',            page:'clients'      },
  { group:'Core CRM',   key:'agreements',      label:'Agreements',           page:'agreements'   },
  { group:'Core CRM',   key:'invoices',        label:'Invoices',             page:'invoices'     },
  { group:'Contacts',   key:'mailing',         label:'Mailing List',         page:'mailing'      },
  { group:'Contacts',   key:'holding',         label:'Holding Contacts',     page:'holding'      },
  { group:'Calendarly', key:'appointments',    label:'Teams / Appointments', page:'appointments' },
  { group:'Calendarly', key:'events',          label:'Industry Events',      page:'events'       },
  { group:'Calendarly', key:'bookingPages',    label:'Booking Pages',        page:'booking'      },
  { group:'Content',    key:'forms',           label:'Forms',                page:'forms'        },
  { group:'Content',    key:'recurringEmails', label:'Recurring Emails',     page:'emails'       },
];
var BACKUP_TYPES       = BACKUP_PAGE_MAP; // backwards-compat alias
var BACKUP_FILTER_CO   = 'rl';
var BACKUP_LIST        = {};
var BACKUP_LOADING     = {};
var _backup15Timer     = null;
var _lastBackupTime    = {};

// ═══════════ UNLOCKMLS AUTO-SYNC ═══════════════════════════════
// Periodically pulls fresh agent data from UnlockMLS and smart-merges
// into Holding Contacts for both rl and nl.
// Settings stored in localStorage:
//   crm_mls_interval  — sync frequency in ms (default 6h)
//   crm_mls_last_rl   — ISO timestamp of last rl sync
//   crm_mls_last_nl   — ISO timestamp of last nl sync
// ────────────────────────────────────────────────────────────────

var _mlsSyncTimer   = null;
var MLS_SYNC_INTERVALS = {
  '1h':  1  * 60 * 60 * 1000,
  '6h':  6  * 60 * 60 * 1000,
  '12h': 12 * 60 * 60 * 1000,
  '24h': 24 * 60 * 60 * 1000,
  'off': 0
};
var MLS_DEFAULT_INTERVAL = '6h';

function getMlsInterval() {
  return localStorage.getItem('crm_mls_interval') || MLS_DEFAULT_INTERVAL;
}
function setMlsInterval(val) {
  localStorage.setItem('crm_mls_interval', val);
}
function getMlsLastSync(pub) {
  return localStorage.getItem('crm_mls_last_' + pub) || null;
}
function setMlsLastSync(pub) {
  localStorage.setItem('crm_mls_last_' + pub, new Date().toISOString());
}

function startMlsSyncScheduler() {
  if (_mlsSyncTimer) { clearInterval(_mlsSyncTimer); _mlsSyncTimer = null; }
  var key = getMlsInterval();
  var ms  = (MLS_SYNC_INTERVALS||{})[key] || 0;
  if (!ms) { console.log('[MLS Sync] Disabled'); return; }
  // Warmup: run after 60s if last sync was >ms ago
  setTimeout(function() {
    var last = getMlsLastSync('rl');
    var due  = !last || (Date.now() - new Date(last).getTime()) >= ms;
    if (due) runMlsSync(true);
  }, 60 * 1000);
  _mlsSyncTimer = setInterval(function() { runMlsSync(true); }, ms);
  console.log('[MLS Sync] Scheduled every', key);
}

function restartMlsSyncScheduler() {
  startMlsSyncScheduler();
  if (currentPage === 'holding') renderHolding();
}

// ── Core sync: fetch from UnlockMLS, smart-merge into holding ───
function runMlsSync(silent, pub) {
  // pub: 'rl' | 'nl' | undefined (both)
  var pubs = pub ? [pub] : ['rl', 'nl'];
  var regionMap = { rl: 'Austin Texas', nl: 'San Antonio Texas' };

  pubs.forEach(function(c2) {
    var region = regionMap[c2] || 'Texas';
    // Fetch a broad list — multiple queries to cover different agent types
    var queries = ['realtor '+region, 'broker '+region, 'agent '+region];
    var allResults = [];
    var pending = queries.length;

    queries.forEach(function(q) {
      fetchWithTimeout(CAXTON_PROXY + '/api/unlockmls/search', {
        method:  'POST',
        headers: { 'Content-Type': 'application/json' },
        body:    JSON.stringify({ query: q, limit: 100 })
      }, 30000)
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var arr = Array.isArray(data.results) ? data.results : [];
        arr.forEach(function(r) { allResults.push(r); });
      })
      .catch(function() {}) // silent on individual query failure
      .then(function() {
        pending--;
        if (pending > 0) return;
        // All queries done — merge
        mlsMergeResults(c2, allResults, silent);
      });
    });
  });
}

function mlsMergeResults(c2, rawResults, silent) {
  // Guard: don't persist if DATA looks uninitialized (pre-DB-load race condition)
  var existingTotal = (DATA['rl'].clients||[]).length + (DATA['nl'].clients||[]).length
    + (DATA['rl'].mailing||[]).length + (DATA['nl'].mailing||[]).length
    + (DATA['rl'].agreements||[]).length + (DATA['nl'].agreements||[]).length;
  if (!rawResults.length) {
    if (!silent) toast('No results from UnlockMLS', 'err');
    return;
  }

  if (!DATA[c2].holding) DATA[c2].holding = [];
  var contacts = DATA[c2].holding;

  // Deduplicate incoming results by license then name
  var seen = new Set();
  var incoming = rawResults.filter(function(r) {
    var key = (r.license || r.name || '').trim().toLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).map(function(r, i) {
    var first = r.firstName || (r.name||'').split(' ')[0] || '';
    var last  = r.lastName  || (r.name||'').split(' ').slice(1).join(' ') || '';
    return {
      id:          'mls_' + c2 + '_' + Date.now() + '_' + i,
      name:        r.name || [first, last].filter(Boolean).join(' '),
      firstName:   first,
      lastName:    last,
      company:     r.company  || '',
      title:       r.title    || '',
      email:       r.email    || '',
      phone:       r.phone    || '',
      mobile:      r.mobile   || '',
      address:     r.address  || '',
      city:        r.city     || '',
      state:       r.state    || 'TX',
      zip:         r.zip      || '',
      license:     r.license  || '',
      tags:        'unlockmls-sync',
      source:      'UnlockMLS',
      addrStatus:  r.address ? 'Pending' : '',
      emailStatus: r.email   ? 'Pending' : '',
      createdAt:   new Date().toISOString(),
      updatedAt:   new Date().toISOString(),
    };
  });

  var added = 0, updated = 0;
  incoming.forEach(function(inc) {
    // Match on license (strongest) then name
    var existing = contacts.find(function(c) {
      if (inc.license && c.license) {
        return inc.license.trim().toLowerCase() === c.license.trim().toLowerCase();
      }
      if (inc.name && c.name) {
        return inc.name.trim().toLowerCase() === c.name.trim().toLowerCase();
      }
      return false;
    });

    if (existing) {
      // Update fields that UnlockMLS might have fresher data on
      // but preserve verification status and local edits
      if (inc.company  && !existing.company)  existing.company  = inc.company;
      if (inc.title    && !existing.title)     existing.title    = inc.title;
      if (inc.email    && !existing.email)     existing.email    = inc.email;
      if (inc.phone    && !existing.phone)     existing.phone    = inc.phone;
      if (inc.address  && !existing.address)   existing.address  = inc.address;
      if (inc.city     && !existing.city)      existing.city     = inc.city;
      if (inc.state    && !existing.state)     existing.state    = inc.state;
      if (inc.zip      && !existing.zip)       existing.zip      = inc.zip;
      if (inc.license  && !existing.license)   existing.license  = inc.license;
      existing.updatedAt = new Date().toISOString();
      updated++;
    } else {
      contacts.push(inc);
      added++;
    }
  });

  setMlsLastSync(c2);

  // Only persist if DATA was already loaded (guard against pre-DB-load race)
  if (existingTotal > 0 && (added > 0 || updated > 0)) {
    var savedCo = co;
    co = c2;
    persist();
    co = savedCo;
  }

  var msg = '[MLS Sync ' + c2.toUpperCase() + '] ' + added + ' added, ' + updated + ' updated (' + incoming.length + ' from UnlockMLS)';
  console.log(msg);
  if (!silent) toast(msg, 'ok');
  if (currentPage === 'holding') renderHolding();
}

// ── Manual sync trigger ──────────────────────────────────────────
function mlsSyncNow() {
  toast('Syncing from UnlockMLS...', '');
  runMlsSync(false);
}

// ── Format last-sync time ────────────────────────────────────────
function mlsLastSyncLabel(pub) {
  var ts = getMlsLastSync(pub);
  if (!ts) return 'Never';
  var d   = new Date(ts);
  var now = new Date();
  var diffMs  = now - d;
  var diffMin = Math.floor(diffMs / 60000);
  if (diffMin < 1)  return 'Just now';
  if (diffMin < 60) return diffMin + 'm ago';
  var diffHr = Math.floor(diffMin / 60);
  if (diffHr  < 24) return diffHr + 'h ago';
  return Math.floor(diffHr / 24) + 'd ago';
}

// ── 15-minute auto-backup scheduler ─────────────────────────────
function startBackupScheduler() {
  if (_backup15Timer) clearInterval(_backup15Timer);
  _backup15Timer = setInterval(runScheduledBackup, 15 * 60 * 1000);
  setTimeout(runScheduledBackup, 30 * 1000);
}

function runScheduledBackup() {
  ['rl', 'nl'].forEach(function(c2) {
    (BACKUP_PAGE_MAP||[]).forEach(function(t) {
      var raw = (t.key === 'tracking') ? (DATA[c2].tracking || {}) : (DATA[c2][t.key] || []);
      var arr = Array.isArray(raw) ? raw : [raw];
      if (!arr.length) return;
      crmFetch(API_BASE + '/api/crm/' + c2 + '/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ data_type: t.key, payload: arr, label: 'Scheduled 15-min' })
      }).catch(function() {});
    });
    _lastBackupTime[c2] = Date.now();
  });
  console.log('[Backup] 15-min run:', new Date().toLocaleTimeString());
}

// ── Manual backup — both companies, all types ────────────────────
function backupNow() {
  toast('Backing up all data...', '');
  var total = 0, done = 0;
  ['rl', 'nl'].forEach(function(c2) {
    (BACKUP_PAGE_MAP||[]).forEach(function(t) {
      var raw = (t.key === 'tracking') ? (DATA[c2].tracking || {}) : (DATA[c2][t.key] || []);
      var arr = Array.isArray(raw) ? raw : [raw];
      if (!arr.length) return;
      total++;
      crmFetch(API_BASE + '/api/crm/' + c2 + '/backup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ data_type: t.key, payload: arr, label: 'Manual — ' + new Date().toLocaleTimeString() })
      }).then(function() {
        done++;
        if (done === total) {
          toast('Backup complete — ' + total + ' snapshots saved', 'ok');
          if (currentPage === 'backups') { BACKUP_LIST = {}; BACKUP_LOADING = {}; renderBackups(); }
        }
      }).catch(function() {});
    });
  });
  if (total === 0) toast('No data to back up', 'warn');
}

// ── Fetch snapshot list for one company + type ───────────────────
function _fetchBackupList(c2, type) {
  var key = c2 + '_' + type;
  BACKUP_LOADING[key] = true;
  if (currentPage === 'backups') renderBackups();
  crmFetch(API_BASE + '/api/crm/' + c2 + '/backups?data_type=' + type + '&limit=25')
    .then(function(r) { return r.json(); })
    .then(function(rows) {
      BACKUP_LIST[key] = Array.isArray(rows) ? rows : [];
      BACKUP_LOADING[key] = false;
      if (currentPage === 'backups') renderBackups();
    })
    .catch(function() {
      BACKUP_LIST[key] = [];
      BACKUP_LOADING[key] = false;
      if (currentPage === 'backups') renderBackups();
    });
}

function loadBackupList() {
  var c2 = BACKUP_FILTER_CO;
  (BACKUP_PAGE_MAP||[]).forEach(function(t) {
    var key = c2 + '_' + t.key;
    if (BACKUP_LIST[key]) return; // already loaded
    var raw = DATA[c2] ? DATA[c2][t.key] : null;
    var cnt = Array.isArray(raw) ? raw.length : 0;
    if (cnt === 0) return; // skip empty pages
    _fetchBackupList(c2, t.key);
  });
  if (currentPage === 'backups') renderBackups();
}

// ── Restore confirmation modal ───────────────────────────────────
function confirmRestore(backupId, dtStr, dataType, recordCount, targetCo) {
  var t      = (BACKUP_PAGE_MAP||[]).find(function(x) { return x.key === dataType; });
  var typLbl = t ? t.label : dataType;
  var coLbl  = targetCo === 'rl' ? 'RealtyLine' : 'Newsline';
  var raw    = DATA[targetCo] ? DATA[targetCo][dataType] : null;
  var curCnt = (dataType === 'tracking') ? 1 : (Array.isArray(raw) ? raw.length : 0);
  var diff   = (recordCount || 0) - curCnt;
  var diffStr = diff === 0 ? 'same as live'
    : diff > 0 ? '+' + diff + ' more than live'
    : Math.abs(diff) + ' fewer than live';
  openModal(
    '<div class="modal-title" style="color:#DB1924">' + icon('refresh') + ' Restore ' + esc(typLbl) + '</div>',
    '<div style="background:color-mix(in srgb,var(--destructive) 8%,transparent);border:1px solid color-mix(in srgb,var(--destructive) 22%,transparent);border-radius:var(--r);padding:12px 16px;margin-bottom:14px">'
    + '<div style="font-size:13px;font-weight:700;color:#DB1924;margin-bottom:8px">&#9888; This will overwrite live ' + esc(coLbl) + ' data</div>'
    + '<table style="font-size:13px;color:var(--text2);border-collapse:collapse;width:100%">'
    + '<tr><td style="padding:3px 0;width:110px;color:var(--text3)">Data type</td><td><strong>' + esc(typLbl) + '</strong></td></tr>'
    + '<tr><td style="padding:3px 0;color:var(--text3)">Snapshot</td><td><strong>' + esc(dtStr) + '</strong></td></tr>'
    + '<tr><td style="padding:3px 0;color:var(--text3)">Snapshot</td><td><strong>' + (recordCount || 0) + ' records</strong> (' + esc(diffStr) + ')</td></tr>'
    + '<tr><td style="padding:3px 0;color:var(--text3)">Live now</td><td><strong>' + curCnt + ' records</strong></td></tr>'
    + '</table></div>'
    + '<p style="font-size:13px;color:#DB1924">This cannot be undone. The app reloads after restore.</p>',
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-sm" onclick="executeRestore(' + backupId + ',\'' + esc(dataType) + '\',\'' + esc(targetCo) + '\')" style="background:#DB1924;color:#fff;font-weight:600;gap:5px">' + icon('refresh') + ' Restore ' + esc(typLbl) + '</button>'
  );
}

// ── Execute restore ──────────────────────────────────────────────
function executeRestore(backupId, dataType, targetCo) {
  requireDeleteAuth(function() {
    closeModal();
    toast('Restoring ' + dataType + ' (' + (targetCo === 'rl' ? 'RealtyLine' : 'Newsline') + ')...', '');
    crmFetch(API_BASE + '/api/crm/' + targetCo + '/restore', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ backup_id: backupId, company: targetCo, data_type: dataType })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data && data.error) { toast('Restore failed: ' + sanitizeApiError(data.error), 'err'); return; }
      var cnt = (data && data.restored_count != null) ? data.restored_count : '?';
      toast('Restored ' + cnt + ' records — reloading...', 'ok');
      localStorage.removeItem('crm_data');
      localStorage.removeItem('crm_events');
      setTimeout(function() { window.location.reload(); }, 1500);
    })
    .catch(function(e) { toast('Restore error: ' + sanitizeApiError(e.message) + ' — try Force Reload from DB', 'err'); });
  }, 'restore ' + dataType + ' data');
}

// ── Force reload from DB ─────────────────────────────────────────
function forceReloadFromDb() {
  openModal(
    '<div class="modal-title">' + icon('refresh-cw') + ' Force Reload from Database</div>',
    '<p style="color:var(--text2)">Clears the browser cache and pulls all data fresh from the database. Use this if data appears missing after a restore.</p>',
    '<button class="btn btn-default" onclick="closeModal()">Cancel</button>'
    + '<button class="btn btn-sm" onclick="closeModal();localStorage.removeItem(\'crm_data\');localStorage.removeItem(\'crm_events\');toast(\'Reloading...\',\'\');setTimeout(function(){window.location.reload();},800)" style="background:var(--accent);color:#fff;font-weight:600">Clear Cache &amp; Reload</button>'
  );
}

// ── Render Backups page ──────────────────────────────────────────
function renderBackups() {
  var accent  = ACCENT[co];
  BACKUP_FILTER_CO = co;
  var bc      = co;
  var coLbl   = bc === 'rl' ? 'RealtyLine' : 'Newsline';
  var lastBk  = (_lastBackupTime||{})[bc];
  var lastStr = lastBk
    ? 'Last auto-backup at ' + new Date(lastBk).toLocaleTimeString('en-US', { hour:'numeric', minute:'2-digit' })
    : 'Auto-backups run every 15 min';

  var html = '<div class="page-header">'
    + '<div><div class="page-title">' + icon('database') + ' Backup &amp; Restore</div>'
    + '<div class="page-subtitle">' + esc(lastStr) + ' &mdash; per-company, per-page snapshots</div></div>'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap">'
    + '<button class="btn btn-default btn-sm" style="gap:5px" onclick="forceReloadFromDb()">' + icon('refresh-cw') + ' Force Reload from DB</button>'
    + '<button class="btn btn-sm" style="background:' + accent + ';color:#fff;gap:5px" onclick="backupNow()">' + icon('download') + ' Backup All Now</button>'
    + '</div>'
    + '</div>'
    + '<div class="page-content">';

  // Company follows main RL/NL switcher

  // Groups
  var groups = {};
  var groupOrder = [];
  (BACKUP_PAGE_MAP||[]).forEach(function(t) {
    if (!groups[t.group]) { groups[t.group] = []; groupOrder.push(t.group); }
    groups[t.group].push(t);
  });

  groupOrder.forEach(function(grpName) {
    html += '<div style="margin-bottom:28px">'
      + '<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--text3);margin-bottom:12px;display:flex;align-items:center;gap:10px">'
      + '<span style="flex:1;height:1px;background:var(--border)"></span>'
      + esc(grpName)
      + '<span style="flex:1;height:1px;background:var(--border)"></span>'
      + '</div>';

    groups[grpName].forEach(function(t) {
      var key     = bc + '_' + t.key;
      var list    = BACKUP_LIST[key] !== undefined ? BACKUP_LIST[key] : null;
      var loading = !!BACKUP_LOADING[key];
      var raw     = DATA[bc] ? DATA[bc][t.key] : null;
      var curCnt  = (t.key === 'tracking') ? 1 : (Array.isArray(raw) ? raw.length : 0);
      // Only show block if this page has data or has existing snapshots
      if (curCnt === 0 && !list) return;
      var latest  = list && list[0];
      var latestAge = latest ? Math.round((Date.now() - new Date(latest.created_at).getTime()) / 60000) : null;
      var ageStr  = latestAge === null ? '' : latestAge < 60 ? latestAge + 'm ago' : Math.round(latestAge / 60) + 'h ago';
      var healthy = latestAge !== null && latestAge < 20;

      html += '<div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--rlg);overflow:hidden;margin-bottom:10px">';

      // Card header
      html += '<div style="display:flex;align-items:center;gap:14px;padding:13px 16px;background:var(--surface2)">'
        + '<div style="flex:1;min-width:0">'
        + '<div style="font-size:13.5px;font-weight:700;color:var(--text);display:flex;align-items:center;gap:8px;flex-wrap:wrap">'
        + esc(t.label);
      if (healthy) {
        html += ' <span style="font-size:10px;background:color-mix(in srgb,#22c55e 12%,transparent);color:#16a34a;border:1px solid color-mix(in srgb,#22c55e 28%,transparent);padding:1px 7px;border-radius:var(--rfull);font-weight:700">&#10003; ' + esc(ageStr) + '</span>';
      }
      html += '</div>'
        + '<div style="font-size:11.5px;color:var(--text3);margin-top:3px">'
        + curCnt.toLocaleString() + ' records live'
        + (list ? '&nbsp;&nbsp;&middot;&nbsp;&nbsp;' + list.length + ' snapshots' : '')
        + '</div></div>';

      if (!loading) {
        var btnKey = bc;
        var btnType = t.key;
        if (list === null) {
          html += '<button onclick="_fetchBackupList(\'' + btnKey + '\',\'' + btnType + '\')" '
            + 'style="padding:5px 12px;font-size:12px;font-weight:600;border:1px solid var(--border2);border-radius:var(--r);background:var(--surface);color:var(--accent);cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:4px">'
            + icon('download') + ' Load</button>';
        } else {
          html += '<button onclick="_fetchBackupList(\'' + btnKey + '\',\'' + btnType + '\')" '
            + 'style="padding:5px 10px;font-size:12px;border:1px solid var(--border2);border-radius:var(--r);background:var(--surface);color:var(--text2);cursor:pointer;font-family:inherit;display:flex;align-items:center;gap:4px" title="Refresh">'
            + icon('refresh') + '</button>';
        }
      }
      html += '</div>'; // end card header

      // Snapshot table
      if (loading) {
        html += '<div style="padding:14px 20px;text-align:center;color:var(--text3);font-size:13px;border-top:1px solid var(--border)">Loading...</div>';
      } else if (list && list.length) {
        html += '<div style="overflow-x:auto;border-top:1px solid var(--border)">'
          + '<table style="width:100%;border-collapse:collapse">'
          + '<thead><tr style="background:var(--muted)">'
          + '<th style="text-align:left;padding:7px 16px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3)">Date &amp; Time</th>'
          + '<th style="text-align:left;padding:7px 16px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3)">Records</th>'
          + '<th style="text-align:left;padding:7px 16px;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--text3)" class="hide-sm">Label</th>'
          + '<th style="padding:7px 16px"></th>'
          + '</tr></thead><tbody>';

        list.slice(0, 10).forEach(function(b, i) {
          var dt    = new Date(b.created_at);
          var dtStr = dt.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' })
                    + ' ' + dt.toLocaleTimeString('en-US', { hour:'numeric', minute:'2-digit' });
          var diff  = (b.record_count || 0) - curCnt;
          var diffHtml = diff === 0 ? ''
            : diff > 0 ? ' <span style="font-size:11px;color:#16a34a;font-weight:700">+' + diff + '</span>'
            : ' <span style="font-size:11px;color:#DB1924;font-weight:700">' + diff + '</span>';
          var rowBc = bc;
          html += '<tr style="border-bottom:1px solid var(--border)">'
            + '<td style="padding:9px 16px;font-size:13px;color:var(--text);white-space:nowrap">' + esc(dtStr)
            + (i === 0 ? ' <span style="font-size:10px;background:color-mix(in srgb,' + accent + ' 12%,transparent);color:' + accent + ';padding:1px 6px;border-radius:var(--rfull);font-weight:700;vertical-align:middle">Latest</span>' : '')
            + '</td>'
            + '<td style="padding:9px 16px;font-size:13px;color:var(--text2)">' + (b.record_count || 0).toLocaleString() + diffHtml + '</td>'
            + '<td style="padding:9px 16px;font-size:12px;color:var(--text3)" class="hide-sm">' + esc(b.label || 'Auto-save') + '</td>'
            + '<td style="padding:9px 16px;text-align:right;white-space:nowrap">'
            + '<button onclick="confirmRestore(' + b.id + ',\'' + esc(dtStr) + '\',\'' + esc(t.key) + '\',' + (b.record_count || 0) + ',\'' + rowBc + '\')" '
            + 'class="btn btn-sm btn-default" style="gap:4px;font-size:12px">' + icon('refresh') + ' Restore</button></td>'
            + '</tr>';
        });
        html += '</tbody></table></div>';
        if (list.length > 10) {
          html += '<div style="padding:8px 16px;font-size:12px;color:var(--text3);text-align:center;border-top:1px solid var(--border)">'
            + (list.length - 10) + ' older snapshots not shown</div>';
        }
      } else if (list && !list.length) {
        html += '<div style="padding:14px 20px;font-size:13px;color:var(--text3);border-top:1px solid var(--border)">No snapshots yet &mdash; changes auto-save every 15 min, or click Backup All Now</div>';
      }

      html += '</div>'; // card
    });
    html += '</div>'; // group
  });

  html += '</div>'; // page-content
  document.getElementById('pageArea').innerHTML = html;
}

